import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святим преподобним Антонію і Феодосію Печерським","e":"Akathist to the Holy Venerable Anthony and Theodosius of the Caves","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії і Ду́ха Свята́го ісполне́нії, преподо́бнії і богоно́снії отці́ на́ші, Анто́ніє і Феодо́сіє Пече́рстії, преізя́щная Ру́ськия землі́ прозябе́нія, пречу́дная ру́ськаго наро́да украше́нія, хотя́щу мні, недосто́йному, похва́льноє вам соверши́ти пі́ніє, смире́нно вас молю́, потемненний мой ра́зум сві́том да́нния вам от Бо́га благода́ті озарі́те, мрак неві́дінія просвіті́те, неудо́бства і препони разруші́те, мою́ не́мощ укріпі́те, нас же всіх, сино́в ру́ських от всіх бід і напа́стей, скорбе́й і болі́зней оте́чеськи свободи́те, да в теплоті́ се́рдця із глубини́ душі́ всі ку́пно вопіє́м вам:","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Ікос 1","ps":["А́нгелом подо́бнаго жела́юще житія́, а́біє в ю́ності своє́й вся кра́сная ми́ра разсудне пренебрего́сте; і а́ки сме́тіє от себе́ отве́ргше, детськими попра́сте нога́ми, вас же всеці́лих, в дар Христу́ Бо́гу і приноше́ніє освяти́сте, тім таково́є ва́ше свято́є і богоприя́тноє разсужда́юще проізволе́ніє, сицево́є вам прино́сим пі́ніє:","Ра́дуйтеся, отці́ богоно́снії, вся земна́я, блага́я і кра́сная ми́ра презрі́вшії;","ра́дуйтеся, Христа́ от ю́ности всім се́рдцем і все́ю душою возлюби́вшії.","Ра́дуйтеся, дом, імі́нія і вся роди́телей стяжа́нія ні во что вміни́вшії;","ра́дуйтеся, благо́є і сла́дкоє і́го Христо́во на ра́мена, в детстві єще́ су́ще, взе́мшії.","Ра́дуйтеся я́ко уподо́бистеся преподо́бнаго А́веля богоприя́тному приноше́нію;","ра́дуйтеся, я́ко подража́теліє би́сте боголюби́ваго Но́я в благодарном єго́ по ізше́ствії із ковче́га жертвоприношенії.","Ра́дуйтеся, ва́ша тілеса́ вмі́сто ту́чних а́гнцев і тельцо́в, Созда́телю своєму́ прине́сшії;","ра́дуйтеся, душі́ ва́ша, вмі́сто благово́ннаго фимія́ма, Христу́ Спаси́телю вознесшії.","Ра́дуйтеся, се́рдця ва́ша во всегда́шнєє Бо́гу і Бо́жієй Ма́тері служе́ніє до́брі уготовавшії і всеці́ло преда́вшії;","ра́дуйтеся, все ва́ше житіє́, подо́бні Самуї́лу, на служе́нії Бо́жії да́же до последнего іздиха́нія красно́ і богоуго́дно препроведшії.","Ра́дуйтеся, мно́гоє мно́жество муже́й і жен, ю́ношей і дів ва́шему подража́ти житію́ научи́вшії;","ра́дуйтеся, благи́й і ле́гкий яре́м Христо́в мно́гим усладившії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 2","ps":["Ви́дя всеви́дящеє о́ко Отця́ Сві́тов таково́є ва́ше Бо́гу вельми́ благоуго́дноє начина́ніє і душеспаси́тельноє намі́реніє, а́ще і не а́біє вас ку́пно жи́тельствовати устро́ї, оба́че не в до́лгом вре́мені си́це вас соєдини́ і совокупи́, я́коже соєдини́ і совокупи́ Па́вла Петру́, да єди́н яре́м поне́сше, мно́гих в небе́сная введе́те оби́телі; чесо́му ми удивля́ющеся, благода́рственно Бо́гу, та́ко устро́ївшему, поє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богоприя́тен, Анто́ніє, всехва́льне, тебі́ же самому́ і про́чим душеполезен стяжа́ти усердствуя, сего́ днем і но́щію от Всеми́лостиваго Бо́га с те́плими слеза́ми прилі́жно проси́л єси́, проро́чеськи віща́я: “Скажи́ мі, Го́споди, путь, во́ньже пойду́”. Ті́мже человіколюби́вий Бог, вняв твоєму́ сле́зному моле́нію, вложи́ в твоє́ се́рдце, да не медля в Афо́нськую Го́ру і́деши, ти же, а́ки втори́й Авраа́м, я́лся єси́ путі́ с ве́ліїм тща́нієм, Бо́жиє ісполня́я велі́ніє, чесо́ ра́ди вопіє́м тебі́ такова́я:","Ра́дуйся, о́тче Анто́ніє, дре́внему уподо́бивийся Авраа́му, по сло́ву Бо́жию, доброхотно і послушно, без ско́рби і сі́тованія от сро́дник і южик свої́х удаляющемуся;","ра́дуйся, в далеча́йшую неві́домую страну́, обрі́тенія ра́ди мона́шеськаго житія́, от свої́х сі нескорбно удали́вийся.","Ра́дуйся, до́лгий, тру́дний і приско́рбний путь скороте́чно без смуще́нія преше́дий;","ра́дуйся, А́нгела Бо́жія в том путі́ спу́тника, я́коже іногда́ Тові́я, імі́вий.","Ра́дуйся, Афо́нськия Гори́, по твоєму́ жела́нію, Бо́жию же ізволе́нію, благополу́чно дости́гнувий;","ра́дуйся, мно́гая та́мо духо́вная блага́я і душеполе́зная сокро́вища стяжа́вий.","Ра́дуйся, мно́гих та́мо свої́м любому́дрим житіє́м в пості́ і моли́тві, неустанном труді́ і бді́нії, і безответнем, Го́спода ра́ди, послуша́нії удиви́вий;","ра́дуйся, в і́ночеських труді́х і по́двизіх вели́ким ста́рцем Святи́я Гори́ тебі́ сравнивий.","Ра́дуйся, Анто́ніє, а́ки богому́драя пчела́, от тружда́ющихся та́мо оте́ць, а́ки от разли́чних цвіто́в, сла́дость і́ночеськую собра́вий;","ра́дуйся, ту́южде сла́дость во Оте́чество сохра́нно принеси́й, і зді благоуспі́шно насади́вий і возрасти́вий стори́цею.","Ра́дуйся, я́ко в монашество то́южде сла́достію мно́гих, с ни́миже і Феодо́сія Вели́каго в сло́ві і ді́лі привле́кл єси́;","ра́дуйся, я́ко со́бранную бра́тію твою́ духо́вною сла́достію ізоби́льно наси́тил і в доброді́теліх укріпи́л єси́.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго в чи́стоє твоє́ і непоро́чноє все́льшися се́рдце, преблаже́нне Феодо́сіє, та́ко всего́ тебі́ Бо́жиєю любо́вію разжже́, я́ко всіх земни́х і вре́менних удаля́тися, ві́чних же і несконча́ємих ви́ну іска́ти тебі́ научи́ і вразуми́. Тім таково́є твоє́ о спасе́нії душі́ зря́ще тща́ніє і усе́рдіє, уми́льно Всеси́льному Бо́гу поє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́л єси́, о́тче преблаже́нне Феодо́сіє, превели́коє жела́ніє, є́же Свята́я в Ієрусали́мі посіти́ти мі́ста, і к сему́ ді́лу жела́ємую обрі́л єси́ удо́бность, ко гряду́щим в Ієрусали́м приобщи́вся, но зло́бний враг спо́ну тебі́ і преп'я́тіє соді́ла, наусти бо ма́тер твою́, я́же вслід тебі́ гнавши, і дости́гши, а́ки злоді́я свя́зана, в дом привлекши, по мно́гом біє́нії, тве́рдо в хра́мині заключи́, ти же, а́ки адама́нт, сія́ злострада́нія терпіли́во поне́сл єси́, посе́м от заключе́нія іспуще́н, па́ки на хлебопеченіє церковному литургиса́нію прили́чноє вда́лся єси́, чесо́му удивля́ющеся, си́це тебі́ вопіє́м:","Ра́дуйся, о́тче Феодо́сіє, непоколеби́мий і неруши́мий терпі́нія сто́лпе;","ра́дуйся, пречу́дний і прекра́сний смире́нія і кро́тости о́бразе.","Ра́дуйся, тя́жкая ма́терняя біє́нія і нога́ма попиранія благоду́шно і му́жественно терпі́вий;","ра́дуйся, тоя́жде ласка́нія і лобза́нія а́ки смертоно́сний вред себі́ вміни́вий.","Ра́дуйся, служе́ніє Бо́гу і Бо́жієй Ма́тері па́че всего́ вседу́шно возлюби́вий;","ра́дуйся, церковному служе́нію со вся́ким усе́рдієм от ді́тства прилежавий.","Ра́дуйся, све́рстников поруга́нія і посмія́нія в честь себі́ вміни́вий;","ра́дуйся, всім ста́рим і ю́ним о́браз смире́нія і кро́тости тебі́ предста́вивий.","Ра́дуйся, всім обидящим тебі́ вседу́шно прегріше́нія прости́вий;","ра́дуйся, всі́ми доброді́тельними челові́ки па́че све́рстник твої́х хвали́мий, люби́мий і почита́ємий.","Ра́дуйся, добронравієм і благоче́стієм краснєє, не́же сві́тлими ри́зами, тебі́ украси́вий;","ра́дуйся, ма́терняя і властительськая одія́нія, я́ко скве́рноє бла́то, вміни́вий.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 4","ps":["От богоме́рзьких сласте́й і волне́ній непреодоленен яви́лся єси́, преподо́бне о́тче наш Феодо́сіє, і́бо твоє́, є́же непреста́нно рабо́тати Го́сподеві всегда́ іму́щи в умі́ і в се́рдці проізволе́ніє, на ки́йждо день на бо́льшія простира́лся єси́ труди́, і на ки́йждо день приятнейшим і любе́знійшим Бо́гу би́ти усе́рдствовал єси́, вся́коє же ми́ра сладостра́стіє і любоче́стіє побіжда́я, Єди́ному Бо́гу ви́ну воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав преблаже́нне о́тче Феодо́сіє, жесто́коє свята́го Анто́нія і о́строє в пеще́рнім затво́рі житіє́, скороте́чно, а́ки єле́нь на істо́чники водни́я, к нему́ о́тай ма́тере твоєя́ текл єси́, іді́же доспі́вши прилі́жно єго́ моли́л єси́, да тя в своє́ сожи́тельство при́йметь і в число́ і́ночествующих впишеть, он же, прови́дів в тебі́ живу́щую благода́ть Бо́жию, неотлагательно повелі́ на тя і́ночеський возложи́ти о́браз, ти же за то благодаривши Бо́га Благоді́теля, обоєручно і́ночеськаго яви́лся єси́ житія́, і со Анто́нієм ку́пно непреста́нно тружда́лся єси́, о чесо́м ми помишля́юще, та́ко взива́єм к вам:","Ра́дуйтеся, Анто́ніє і Феодо́сіє, і́ночеськаго житія́ основателі;","ра́дуйтеся, перві́йшії новонача́льних і́ноков в Русі́ наста́вници.","Ра́дуйтеся, в мона́шеськоє оти́шіє, а́ки в ні́кий кора́бль безопасний, к вам приходя́щих вводители;","ра́дуйтеся, предо́брії в пучи́ні ми́ра сего́ вла́ющихся упра́вителі.","Ра́дуйтеся, мирськи́я бу́ри, волне́нія і м'яте́жи в тишину́ му́дре прелага́ющії;","ра́дуйтеся, всіх любе́зно в до́броє і спаси́тельноє приста́нище наставля́ющії.","Ра́дуйтеся, свирепеющия враго́в шата́нія му́дре усмиряющії;","ра́дуйтеся, от всіх неприя́зненних обурева́ній к вам притека́ющих удо́бно спасающії.","Ра́дуйтеся всіх под ваш покро́в і защище́ніє оте́чеськи приє́млющії;","ра́дуйтеся, всіх без лицеприя́тія от всіх напа́стей і бід защища́ющії.","Ра́дуйтеся, бедствующим всегда́ і во всем, і на ко́ємждо мі́сті до́брі предста́тельствующії;","ра́дуйтеся, оби́димих, озлобля́ємих і уничижаємих присноходатайствующії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 5","ps":["Богоявленния зві́зди, ї́хже на тве́рди Ру́ськой яви́ со́лнце преми́рноє, луча́ми висо́кия ва́шея святи́ні мно́гих просвіща́ющия, мно́гих на путь богові́дінія наставляющия, мно́гих к іночествованію приводя́щия, мно́гих же в доброді́теліх, остром же і прискорбном житії́ утвержда́ющия і укрепляющия, сіє́ Бо́жиє ізволе́ніє во вас до́брі ісполнившеєся зря́ще, поє́м благода́рно Всемилостивому́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше мно́зі богоуго́дноє ва́ше в пеще́рах, а́ки во гробі́х, заключе́нноє житіє́, умиляхуся душа́ми, се́рдці же сокруша́ющеся, спі́шно к вам, спасе́нія і́щуще, притека́ху смире́нно прося́ще, да і їх такова́го житія́ о́бщники соді́лавше, во всегда́шнєє Бо́гу служе́ніє освяті́те, ви же по́мняще Ре́кшаго: “Гряду́щаго ко Мні не іждену́ вон”, всіх приходя́щих любе́зно прийма́сте, і оте́чеськи поучасте. Ті́мже сицеви́м вас вінча́єм піснопі́нієм:","Ра́дуйтеся, преблаже́ннії отці́ мно́гих от рабо́тнаго і́га мирська́го в сла́дкую ду́ха свобо́ду ізве́дшії;","ра́дуйтеся, мно́гих і́стинно Христу́ рабо́тати, і і́скренно Єму́ служи́ти научи́вшії.","Ра́дуйтеся, ва́шими доброді́тельми мно́гим ко спасе́нію, я́коже іногда́ Мойсе́й в зе́млю обітова́нную, путь открившії;","ра́дуйтеся, мно́гих не уже́ в зе́млю обітова́нную, но в са́мая Небе́сная жили́ща введшії.","Ра́дуйтеся, не сло́вом то́чію, но мно́жає па́че ді́лом і усе́рдною к Бо́гу моли́твою своя́ ученики́ і послі́дователі поучающії;","ра́дуйтеся, ва́ших купножителей мона́шеськими пра́вили красно́ і боголі́пно управля́ющії.","Ра́дуйтеся, разли́чними іскуше́нії і напа́стьми отягченним ско́ро пособствующії;","ра́дуйтеся, от супоста́ть бори́мим і тя́жко насильствуємим всегда́ помоществующії.","Ра́дуйтеся, одолеваємих от сопроти́вних, но не отчаївающихся і богонадежно в моли́тві вас призива́ющих, внеза́пним ва́шим посо́бієм подкрепляющії;","ра́дуйтеся, вся́коє враждебноє устремле́ніє си́льно восп'ящающії.","Ра́дуйтеся, со́бранноє ва́ми духо́вноє ста́до бо́дренним о́ком ви́ну назирающії;","ра́дуйтеся, ва́ших ученико́в і наслі́дников непреста́нно на путь Бо́жиїх за́повідей наставля́ющії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 6","ps":["Проповедуємо і везді́ попремно́гу похваля́ємо бі ва́ше, преподо́бнії отці́, богоуго́дноє і безмо́лвноє житіє́, кто бо то́чію нестяжа́тельноє і в пеще́рних затво́ріх продолжаємоє сіє́ ви́дів іли́ сли́шав, а́нгелов вас па́че, не́жели челові́ков би́ти не мня́ще; терпі́нію же ва́шему і различному ті́ла умерщвле́нію ки́йждо удивля́яся, Бо́гу прили́чноє воздая́ благодаре́ніє, ку́пно с ва́ми поя́ше піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсіяєте на кру́зі Ру́ськия церко́вния о́бласти, преблаже́ннії, а́ще бо і сами́х себі́ в те́мних пеще́рах, а́ки под спу́дом, заключи́сте, оба́че луча́ми ва́ших по́двигов і доброді́телей, та́кожде вся окре́стния страни́ озари́сте і просвіті́те, я́коже чу́вственноє со́лнце мир озаря́єть і просвіща́єть і та́ко мно́гих се́рдця к богоуго́дному житію́ возбудисте і согрі́ясте, і удо́бна к добродеянію сотвори́сте, я́ко і со́лнце, согріва́я зе́млю, удо́бну твори́ть ю к прозябе́нію разли́чних древ і плодо́в і би́лій се́льних і вся́каго зла́ка на слу́жбу челові́ком і ското́м. О сем благодаря́ще Бо́га, сицево́є вам прино́сим пі́ніє:","Ра́дуйтеся, просвіти́телі в омраче́нії страсте́й пребива́ющих;","ра́дуйтеся, вразумители в суєті́ і самозабвенії жи́тельствующих.","Ра́дуйтеся, руководи́тели в недоумі́нії і заблужде́нії су́щих;","ра́дуйтеся, упра́вителі до́брі жи́ти начина́ющих.","Ра́дуйтеся, укрепители в благо́м ізнемога́ющих, і малоду́шієм і уни́нієм коле́блемих;","ра́дуйтеся, возбудители в небреже́нії спя́щих.","Ра́дуйтеся, бо́дрости і трезві́нія предо́брії учи́тели;","ра́дуйтеся, нераде́нія і пра́здности ізві́стнії прогони́телі.","Ра́дуйтеся, трудолю́бія, є́же вся́кому бла́гу нача́ло і утвержде́ніє, теплі́йшії рачи́тели;","ра́дуйтеся, чи́стаго і непорочного житія́ неусипающії храни́тели.","Ра́дуйтеся, всіх ко спасе́нію ізя́щнії і ві́рнії путеводители;","ра́дуйтеся, всіх благоче́стно і богоуго́дно жи́ти хотя́щих му́дрії наста́вници.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 7","ps":["Хотя́ всезло́бний враг до́брому ва́шему начина́нію спо́ну і преп'я́тіє сотвори́ти, та́ко кня́зя проти́ву вас гні́вом разжже́ і я́ростію распали́ за постриже́ніє в і́ночество слуг єго́, па́че про́чих люби́мих, ні́коєго євну́ха і си́на болярська, я́ко ну́жда вам бі своя́ пещерная оста́вити жили́ща і і́нуді пресели́тися; оба́че не до́лго сим свої́м ухищре́нієм вражде́бник веселя́шеся, і́бо благодушний князь, вразумле́н сий своє́ю богобоящеюся супру́жницею, вско́рі позна́во ва́ше незло́біє, і вра́жию разсмотрі́в хи́трость і кова́рство, с моле́нієм посла́ к вам, да на своє́ па́ки возвраті́теся пре́жнєє местопребиваніє, о чесо́м возра́довавшеся, благода́рно воспесте Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий труд, і но́вий по́двиг по возвраще́нії в пещерная ва́ша жили́ща восприя́ли єсте́, отці́ преподо́бнії: на разширеніє бо мона́шеських ке́ллій і на устроє́ніє моли́твеннаго хра́ма нелі́ностно устреми́стеся, да злоко́зненнаго врага́ горди́ню поперете́ і єго́ безсту́дноє безу́міє посраміте́, со́бранную же бра́тію к богоуго́дному і доброді́тельному житію́ вя́щше возбу́діте, і на усерднейшеє Христу́ Бо́гу служе́ніє подви́гнете, на то ми у́мнима взира́юще очи́ма, си́це взива́єм к вам:","Ра́дуйтеся, пеще́рнаго і́ночеськаго пребива́нія трудолюбнії обріта́телі і ревни́тели;","ра́дуйтеся, те́плії мона́шеськаго житія́ і пресла́внії защи́тници.","Ра́дуйтеся, оби́телей ва́ших бо́дрії і неусипающії храни́тели;","ра́дуйтеся, княжеськаго гні́ва і я́рости смире́ннійшії укротителі.","Ра́дуйтеся, враго́в і неприятелей ва́ших і́стиннії і нелицемернії люби́телі;","ра́дуйтеся, оби́ди вам творя́щих і напа́сти деющих пра́веднії рачи́тели.","Ра́дуйтеся, за́повідей і сові́тов Бо́жиїх усерднейшиє ісполни́тели;","ра́дуйтеся, к чи́стому і непоро́чному житію́ предводители благопоспешнії.","Ра́дуйтеся, добронра́вія і благогові́нія учи́тели преізя́щнії;","ра́дуйтеся, подвиза́ющихся в благоче́стії і тружда́ющихся в благотворе́нії всеси́льнії си́лою Христо́вою помо́щници.","Ра́дуйтеся, в і́ночеських труді́х неутружденнії подви́жници;","ра́дуйтеся, собра́нному ва́ми ста́ду необори́мії во всем побо́рници.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 8","ps":["Стра́нноє ва́ше і вельми́ ско́рбноє житіє́ не то́кмо челові́ков на землі́, но і А́нгелов на небесі́ удиви́: ви бо, заключившеся в пеще́рах, а́ки в те́мних гробі́х, всеусе́рдно в теплоті́ се́рдця і душі́ Єди́ному Бо́гу рабо́тасте, да та, я́же во дні і в нощі́ Созда́телю ва́шему приноси́мая служе́нія, неві́дома і незна́єма бу́дуть ми́рові, ві́дома же і зна́єма Самому́ Творцю́ яв'я́ться. Сего́ ра́ди ми Бо́гу, та́ко вас научи́вшему і вразумившему, при́сно поє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Все ва́ше, преблаже́ннії і богоно́снії отці́, тща́ніє і все о том бя́ше попече́ніє, да ви́ну всезлобному ро́да християнського врагу́ сопротивляєтеся і го́рдую єго́ главу́ попира́єте і стираєте, о́бщаго же всім Творця́, ку́пно со ученики́ свої́ми в душа́х і тілесі́х ва́ших просла́віте і в сем благо́м ізволе́нії ва́шем і богоуго́дном по́двигі укрепляємії си́лою сви́ше, толи́ко преуспесте, я́ко вся возмого́сте о укріпля́ющем вас Христе́ Ісу́се. Ті́мже і сла́ва Бо́жия возсія́ із пеще́р ва́ших і озари́ вся конці́ землі́, чесо́ ра́ди таково́є вам похва́льноє воздає́м пі́ніє:","Ра́дуйтеся неутомимії хвали́ і че́сти Бо́жія в ми́рі ревни́тели і пропові́дници;","ра́дуйтеся, високоумниє вра́жия горди́ні крі́пції смирители.","Ра́дуйтеся, вражде́бних наві́тов і стуже́ній достохва́льнії упразднители;","ра́дуйтеся, неприя́зненних сіте́й і па́губних ко́зней му́жественнії восп'ятителі.","Ра́дуйтеся, глубо́ким смире́нієм і кро́тостію, а́ки драгоці́нними бисерами себі́ украси́вшії;","ра́дуйтеся, в тіх же боголюбе́зних доброді́теліх мно́гих утверди́вшії.","Ра́дуйтеся, в по́стничестві і воздержа́нії дре́внім пустинножителем поревновавшії;","ра́дуйтеся, в неустанней моли́тві, без вся́каго стуже́нія і уни́нія, дні і нощі́ проводи́вшії.","Ра́дуйтеся, в то́йже пребива́ти моли́тві ва́ших последователей до́брі научи́вшії;","ра́дуйтеся, ка́ко бо́дрствовати проти́во вра́жиїм наві́том і о́них одоліва́ти, о́браз і путь нам показа́вшії.","Ра́дуйтеся, на ми́сленния враги́ пост, моли́тви і колінопреклоне́нія, вмі́сто ору́жія, употреблявшії;","ра́дуйтеся, сицеви́м ва́шим ті́сним і ско́рбним житіє́м Бо́жию в ми́рі сла́ву умножившії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 9","ps":["Вся́кий человечеського єстества́ чин, ни́щих і бога́тих, худородних і високородних на убо́гоє, смире́нноє і вельми́ о́строє житіє́ ва́ше взира́я, ве́ліє Бо́гу воздаваше благодаре́ніє і попремно́гу прославля́ше Єго́ благости́ню і неізрече́нноє милосе́рдіє, я́ко си́це ті́сноє і прискорбноє проходи́ти житіє́ вас устро́ї, да ви мно́гих от душегуби́тельния ізве́дше стезі́, па́стирськи на стезю́ спасе́нія наста́віте, поучающе їх при́сно пі́ти Созда́телю і Промисли́телю: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї ізбра́ннії яви́стеся, пресла́внії отці́ на́ші, но не по о́бразу ми́ра сего́ витийствовавшії, і́бо я́же мир сей лю́бить, ви всім усе́рдієм возненави́дісте, і я́же блажи́ть і вельми́ почита́єть, ви презрі́сте, і дале́че от себе́ отве́ргше, а́ки непотре́бноє і неполе́зноє сме́тіє, нога́ма свої́ма попра́сте, ті́мже от всіх таково́є похва́льноє приє́млете почита́ніє:","Ра́дуйтеся, ми́ра і всіх єго́ сласте́й, красо́т і пре́лестей доблестнії презри́тели;","ра́дуйтеся, і́ночеськаго нестяжа́нія і нищети́ теплі́йшії люби́телі.","Ра́дуйтеся, ті́ла ва́шего і всіх тіле́сних чувств суровії умертвители;","ра́дуйтеся, кро́тости, смире́нія і воздержа́нія при́снії рачи́тели.","Ра́дуйтеся, все ва́ше утіше́ніє і блаже́нство в нищеті́ і нестяжа́нії положи́вшії;","ра́дуйтеся, безмо́лвієм і от ми́ра устраненієм зіло́ себі́ удобри́вшії.","Ра́дуйтеся, всеці́ло сами́х себе́ на Бо́жий про́мисл і попече́ніє возложи́вшії;","ра́дуйтеся, сла́дких бра́шен і гортаноугодних пи́тій нікогда́же похотевшії.","Ра́дуйтеся, м'я́гких і сві́тлих одія́ній на ся ніка́коже возложи́вшії;","ра́дуйтеся, многошвенная ру́бища, а́ки многоці́нния украше́нія, во всецелом ва́шем житії́ всегда́ с любо́вію носи́вшії.","Ра́дуйтеся, вмі́сто ізбра́нния пи́щі, посто́м многодневним і о́стрим тілесі́ умерщвле́нієм вас пита́вшії;","ра́дуйтеся, вмі́сто сладкого питія́, серде́чними слеза́ми себі́ сами́х напаявавшії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мно́гих, всіх обраще́нія і спасе́нія ми́лостивно ожида́яй Премилосе́рдий Бог, други́х вас апо́столов Русі́ яви́, да ва́ми мно́гих вразуми́ть і на пра́вий спасе́нія путь наста́вить, в чем ви апо́стольськи потруждшеся, в неві́дінії су́щих єва́нгельськой і́стині нелі́ностно поуча́я, к правові́рію приведо́сте і ко хране́нію Бо́жиїх за́повідей і богоуго́дному і чи́стому житію́ сло́вом і ді́лом непреста́нно возбуждасте, пою́ще Бо́гу Помо́щнику: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і крі́пкоє огражде́ніє яви́стеся, всехва́льнії отці́, к вам прибегающим, не то́чію бо і́ночествовати с ва́ми хотя́щим ру́ку по́мощі ми́лостивно подава́сте, но і разли́чними мирськи́ми ді́ли, напа́стьми і скорбми́ отягче́нних і утесненних та́ко утешасте, я́коже роди́телі ча́да своя́ во обстоя́нії скорбе́й і болі́зней су́щия, утіша́ють, отра́ду їм свої́м попече́нієм подаю́ще і оте́чеською лаською тя́жесть скорбе́й облегча́юще. За каково́є ва́ше благоді́тельство сицево́є вам благода́рственноє воздає́м пі́ніє:","Ра́дуйтеся, бедствующим і разли́чними напа́стьми бори́мим ско́рії помо́щници;","ра́дуйтеся, оби́димих і озло́бленних ізві́стнії защи́тници.","Ра́дуйтеся, обурева́ємих тя́жкими ми́ра сего́ прило́ги предо́брії ко́рмчії;","ра́дуйтеся, убожествующих і в ско́рбній нищеті́ су́щих всещедрії обогати́телі.","Ра́дуйтеся, а́лчущих і гладствующих ми́лостивії кормители;","ра́дуйтеся, нестерпи́мою пали́мих і утесняємих жа́ждою преди́внії прохладители.","Ра́дуйтеся, оде́жди і кро́ва лише́нним в ні́драх милосе́рдія Бо́жия покро́в і убі́жище откривающії;","ра́дуйтеся, слепотствующих, найпа́че же в зако́ні Госпо́дні заблужда́ющих, пречу́днії руководи́тели.","Ра́дуйтеся, болі́зньми і тя́жкими неду́ги одержи́мих і томи́мих прему́дрії уврачевателі;","ра́дуйтеся, всіх напа́стей, бід і скорбе́й си́льнії і крі́пції прогони́телі.","Ра́дуйтеся, вся́каго добра́ вре́меннаго і ві́чнаго подателі;","ра́дуйтеся, с ві́рою к вам притека́ющих от всіх ско́рбних обстоя́ній те́плії защитителі.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 11","ps":["Пі́ніє є́же прино́сим вам, богоно́снії отці́, ність дово́льно к похвале́нію пресла́вних ва́ших по́двигов і трудо́во вишечеловечеських, я́ко бо житіє́ бі превосходя́щеє житіє́ челові́чеськоє, а́нгельському же подо́б'ящеєся, си́це і похвала́м от а́нгел па́че, не́жели от челові́к вам приноси́мим би́ти досто́їть: оба́че усе́рдноє на́ше зря́ще проізволе́ніє, любе́зно приноси́моє на́ми приймі́те пі́ніє, нас же от гріх і вся́ких скверен і нечисто́т ва́шими моли́твами очи́стіте, на всяк день і час чи́стим се́рдцем поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельная на земно́м кру́зі яви́стася світи́ла, Бо́жия благода́ті іспо́лненная, отці́ преблаже́ннії, всю вселе́нную, із подземнаго пеще́рнаго спу́да, пресві́тлими ва́шими доброді́тельми я́сно просвіща́ющия, діла́ бо ва́ші із подзе́мних воссіявше заключеній, та́ко всему́ ми́ру во уві́дініє і позна́ніє прийдо́ша, я́ко і Восто́к о́ная ублажа́єть, і За́пад велича́єть, і Юг восхваля́єть, і Сі́вер попремно́гу прославля́єть. Ті́мже і ми си́це вам от любве́ припіва́єм:","Ра́дуйтеся, всіх доброді́телей неленостнії ісполни́тели;","ра́дуйтеся, мно́гих мона́шеських оби́телей предо́брії соградители.","Ра́дуйтеся, вся́ких доброді́телей пресві́тлая зерца́ла;","ра́дуйтеся, крі́пкая і непреодолимая ва́ших оби́телей забра́ла.","Ра́дуйтеся, прекра́сная і пречу́дная Ду́ха Свята́го жили́ща;","ра́дуйтеся, всіх богоуго́дних і благоприя́тних діл преудобре́нная вмісти́лища.","Ра́дуйтеся, Творцю́ і Бо́гу ва́шему во вре́меннім житії́ до́брі угоди́вшії;","ра́дуйтеся, к ісхо́ду от сея́ вре́менния і многотру́дния жи́зні прекра́сно себі́ угото́вившії.","Ра́дуйтеся, ва́ших ученико́в, а́ки і́стинних чад, не то́чію в животі́ сем, но і при ісхо́ді найпа́че на богоуго́дноє житіє́ наставившії;","ра́дуйтеся, ті́мже ученико́м, по отше́ствії отсю́ду, неви́димоє спребива́ніє і всегда́шнєє содействіє і по́мощ обещавшії.","Ра́дуйтеся, в небе́сная жили́ща благопоспі́шно без вся́каго преп'я́тія вше́дшії;","ра́дуйтеся, мзду ве́лію за ва́ша і́ночеськия злострада́нія от Всеще́драго Мздовоздая́теля восприє́мшії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 12","ps":["Благода́ть, ю́же Всеми́лостивий і Всеще́дрий Бог, от Свої́х неістощи́мих подава́ше сокро́вищ, нікогда́же во вас тща і пра́здна бива́ше, но ви́ну оби́лен плод творя́ше, а́ки зе́рно до́броє в до́брую вверженноє зе́млю, ви бо ві́рним і му́дрим рабо́м, от своєго́ господи́на тала́нти вземшим, уподо́бившеся, та́ко си́лами, сви́ше вам подаваємими, трудолю́бні ді́ласте, я́ко да і Бо́гу прия́тни і любе́зні явіте́ся, і себі́ в небе́сних селе́ніїх несконча́ємоє приобря́щете воздая́ніє, непреста́нно пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ва́ше безмо́лвноє і весьма́ от жите́йських і мирськи́х попече́ній удаленноє, со Єди́ним Бо́гом житіє́, похваля́єм многоболі́зненния труди́ і по́двиги ва́ша, почита́єм дневна́я і всено́щная бді́нія і моли́тви, сла́вим ча́стая долулеганія і колінопреклоне́нія, і вся та чтим пло́ті умерщвле́нія і ду́ха сокруше́нія, я́же любве́ ра́ди Христо́ви благоду́шно под'ясте, воспомина́єм ку́пно і мздовоздая́нія, я́же от Пра́веднаго Судії́ і Мздовоздая́теля Бо́га оби́льно восприя́ли єсте́, си́це воспіва́юще:","Ра́дуйтеся, в Небе́сній несконча́ємій Сла́ві А́нгелом уподобившіїся;","ра́дуйтеся, честь ра́вную Патріа́рхом приє́мшії.","Ра́дуйтеся, в чи́ні проро́ков, я́ко дар проро́чества іму́щії вписаннії;","ра́дуйтеся, к ли́ку апо́столов і євангели́стов, я́ко сло́вом і ді́лом Христа́ благовестившії, сопричтеннії.","Ра́дуйтеся, в со́нмі му́чеников, я́ко мно́го Христа́ ра́ди претерпі́вшії, благоче́стно восприя́тії;","ра́дуйтеся, в собра́нії іспові́дников са́ном іспові́дничества почтеннії.","Ра́дуйтеся, с девствующими, я́ко ді́вственници, возвеличеннії;","ра́дуйтеся, со всі́ми святи́ми до́брі Бо́гу угоди́вшими, уча́стіє і наслі́діє обрі́тшії.","Ра́дуйтеся, пресладким і блаже́нним Пресвяти́я Тро́йці лицезрі́нієм ви́ну насища́ющіїся;","ра́дуйтеся, по і́ночеських по́двизіх і по́стничеських труді́х нескончаємим упокоє́нієм наслажда́ющіїся.","Ра́дуйтеся, неізрече́нних благ, пра́ведним от ві́ка угото́ванних, наслі́дія пра́ведно удостоївшіїся;","ра́дуйтеся, Ца́рствія Небе́снаго, вся в себі́ сла́дости і красоти́, вся вели́чія і блаже́нства, ум челові́чеський превосходя́щая, содержа́щаго, о́бщници і обладателі явившіїся.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 13","ps":["О преблаже́ннії і вся́кия че́сти досто́йнії, отці́ богоно́снії, Анто́ніє і Феодо́сіє Пече́рстії, ма́лоє сіє́ моле́ніє, на́ми, недосто́йними, вам от любве́ приноси́моє, любе́зно приі́мше, ва́ше ку́пно же і на́ше Оте́чество, от всіх неприя́зненних нападе́ній і вра́жиїх наві́тов непоколеби́мо і невреди́мо соблюді́те, нас же, сино́вне с ві́рою і любо́вію к вам притека́ющих, от вся́ких бід, скорбе́й і напа́стей оте́чеськи ізба́віте, да ви́ну благода́рно поє́м о вас Бо́гу Спаси́телю: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом подо́бнаго жела́юще житія́, а́біє в ю́ності своє́й вся кра́сная ми́ра разсудне пренебрего́сте; і а́ки сме́тіє от себе́ отве́ргше, детськими попра́сте нога́ми, вас же всеці́лих, в дар Христу́ Бо́гу і приноше́ніє освяти́сте, тім таково́є ва́ше свято́є і богоприя́тноє разсужда́юще проізволе́ніє, сицево́є вам прино́сим пі́ніє:","Ра́дуйтеся, отці́ богоно́снії, вся земна́я, блага́я і кра́сная ми́ра презрі́вшії;","ра́дуйтеся, Христа́ от ю́ности всім се́рдцем і все́ю душою возлюби́вшії.","Ра́дуйтеся, дом, імі́нія і вся роди́телей стяжа́нія ні во что вміни́вшії;","ра́дуйтеся, благо́є і сла́дкоє і́го Христо́во на ра́мена, в детстві єще́ су́ще, взе́мшії.","Ра́дуйтеся я́ко уподо́бистеся преподо́бнаго А́веля богоприя́тному приноше́нію;","ра́дуйтеся, я́ко подража́теліє би́сте боголюби́ваго Но́я в благодарном єго́ по ізше́ствії із ковче́га жертвоприношенії.","Ра́дуйтеся, ва́ша тілеса́ вмі́сто ту́чних а́гнцев і тельцо́в, Созда́телю своєму́ прине́сшії;","ра́дуйтеся, душі́ ва́ша, вмі́сто благово́ннаго фимія́ма, Христу́ Спаси́телю вознесшії.","Ра́дуйтеся, се́рдця ва́ша во всегда́шнєє Бо́гу і Бо́жієй Ма́тері служе́ніє до́брі уготовавшії і всеці́ло преда́вшії;","ра́дуйтеся, все ва́ше житіє́, подо́бні Самуї́лу, на служе́нії Бо́жії да́же до последнего іздиха́нія красно́ і богоуго́дно препроведшії.","Ра́дуйтеся, мно́гоє мно́жество муже́й і жен, ю́ношей і дів ва́шему подража́ти житію́ научи́вшії;","ра́дуйтеся, благи́й і ле́гкий яре́м Христо́в мно́гим усладившії.","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Кондак 1","ps":["Ізбра́ннії і Ду́ха Свята́го ісполне́нії, преподо́бнії і богоно́снії отці́ на́ші, Анто́ніє і Феодо́сіє Пече́рстії, преізя́щная Ру́ськия землі́ прозябе́нія, пречу́дная ру́ськаго наро́да украше́нія, хотя́щу мні, недосто́йному, похва́льноє вам соверши́ти пі́ніє, смире́нно вас молю́, потемненний мой ра́зум сві́том да́нния вам от Бо́га благода́ті озарі́те, мрак неві́дінія просвіті́те, неудо́бства і препони разруші́те, мою́ не́мощ укріпі́те, нас же всіх, сино́в ру́ських от всіх бід і напа́стей, скорбе́й і болі́зней оте́чеськи свободи́те, да в теплоті́ се́рдця із глубини́ душі́ всі ку́пно вопіє́м вам:","Ра́дуйтеся, Анто́ніє і Феодо́сіє, мона́шеськаго в Русі́ житія́ первонача́льници."]},{"h":"Молитва","ps":["Преподо́бнії і богоно́снії отці́ на́ші Анто́ніє і Феодо́сіє, к вам ми грі́шнії і смире́ннії, я́ко к те́плим засту́пником і ско́рим помо́щником і ізві́стним предста́телем, усе́рдно прибіга́єм, смире́нно прося́ще ва́шея по́мощі і заступле́нія в бе́здні зол і бід погружа́ємії, я́же на всяк день і час нам і от челові́к лука́вих приключа́ються і от духо́в зло́би поднебе́сния, всегда́ поги́белі душ і тіле́с на́ших і́щущих, нахо́дять на ни. Ізвестни бо єсьми́ несумні́нно, коль вели́коє к Милосе́рдому Бо́гу і́мате дерзнове́ніє: єще́ бо на землі́ между́ стра́нствующими ко Го́рнему Оте́честву пребива́юще, ве́лію си́лу благода́ті Бо́жієй, ва́ми чудоді́йствующия, в себі́ показа́сте, я́ко і огнь с небесе́, по подо́бію Іліїну́, на показа́ніє мі́ста, на не́мже вели́кая це́рков Пече́рськая стро́їтися хотя́ше, низведо́сте, і ро́су, по о́бразу Гедео́нову, на очище́ніє і ві́чноє прославле́ніє того́жде свята́го мі́ста призва́сте: та́кожде ві́ми, коль мно́гоє мно́жество муже́й і жен, із ра́зних стран і наро́дов, скорб'я́щих і напа́ствуємих, іли́ разли́чними тя́жкими болі́зньми одержи́мих, ва́шими моли́твами і заступле́нієм получи́ша ско́роє себі́ облегче́ніє і ізбавле́ніє. А́ще у́бо вся та помоществова́нія, єще́ в сме́ртном су́ще стра́нствованії, бедствующим ми́лостивно подава́сте, кольми́ па́че днесь, єгда́ уже́ Всемогу́щей предста́сте Тро́йце, і бо́льшеє прия́сте дерзнове́ніє, во є́же моли́ти ю о на́шем недосто́їнстві, і нас в біда́х і печа́ліх су́щих утіша́ти, в тя́жких ну́ждах і напа́стіх по нас ра́товати, в злоключе́ніях і бі́дствіях нас заступа́ти і защища́ти. Сего́ ра́ди і ми, столь мно́гими вражде́бними наві́тами, озлобленіями і кова́рними злоумишленіями отвсю́ду угрожа́ємії і тісни́мії, ва́шему те́плому і си́льному по Бо́зі вруча́єм себе́ покровительству і защище́нію, і усе́рдно мо́лим благости́ню ва́шу, сохрані́те нас неврежде́нних от всіх бід і зол, найпа́че же от бісо́вських ко́зней і хи́тростей, льсти́вих подступов і наглих нападе́ній: да не бу́дем їм в поруга́ніє і посмія́тельство, но та́ко їх крі́пкою ва́шею по́мощію от нас отжені́те, я́коже во дні о́ни от оби́телі отгна́сте їх, мно́гія па́кості іногда́ деющих. Сицева́я же їх неполе́зная укроти́вше на ни воста́нія і устремле́нія, та́ко нас, утвержде́нних во ві́рі, наде́жде і любві́ постоянних соді́лайте, да ніколи́же на́ми каково́є возоблада́єть недоумі́ніє, іли́ сумні́ніє в тіх, я́же Свята́я Ма́ти Це́рков ві́ровати поуча́єть, і іспові́дати дерзнове́нно повеліва́єть: наде́жду на́шу на Го́спода Бо́га в душа́х на́ших ві́сом і мі́рою пра́вди і ми́лости Бо́жия си́це устро́йте, я́ко да ніже́ ізли́шне упова́єм обіща́нная от Бо́га без труда́ і по́двига восприя́ти, ніже́, зря́ща вели́кая прегріше́нія і тя́жкая законопреступле́нія, весьма́ Бо́жия милосе́рдія отчаїваємся. Любо́во в сердця́х на́ших си́це утверді́те, і досто́йну соді́лайте, да нічто́же земно́є і скорогибнущеє па́че Бо́га, вся сотво́ршаго і вся в Себі́ содержа́щаго, ніже́ помишля́єм, ніже́ жела́єм, ніже́ предпочита́єм. Чу́вства на́ша душе́вная вку́пі і тіле́сная в таково́м благоустроє́нії і благолепной мі́рности на всяк день і час удерживайте і снабдіва́йте, да ті́ми нікогда́же Блага́го, Человіколюби́ваго Бо́га прогні́ваєм. Ра́зум уцілому́дріте, да он па́че о Бо́зі, Єго́ вездіпрису́тствії і благопромишле́нії помишля́єть, не́же о вре́менних і нічто́же су́щих пече́ться. Развраще́нную во́лю на́шу ви́ну ісправля́йте, да ніколи́же хо́щеть, є́же хоті́нію Бо́жию сопротивля́ється, но ті́ми да удовля́ється, і в сих безм'яте́жно і безпеча́льно да пребива́єть, я́же суть Бо́гу уго́дна і прия́тна, челові́ку же спаси́тельна і поле́зна. Па́м'ять істрезвляйте, да та непреста́нно представля́єть уму́ і сія́, і́миже Всеми́лостиваго прогні́ва Бо́га і єго́ благоутро́біє раздражи́ і о́ная, я́же вся́каго челові́ка, кромі́ вся́каго сумні́нія по вре́менной сей жи́зні ожида́ють: к си́мже і Оте́чества ва́шего не забива́йте, но в ми́рном устроє́нії пребива́ти єму́ у Престо́ла Вели́чества Бо́жия непреста́нно хода́тайствуйте. Вся лю́ди, су́щия в страні́ на́шей, ми́рних і безпеча́льних сохрані́те, і от вся́каго зла́го обстоя́нія вско́рі ізба́віте. Єгда́ же приспі́єть на́ше от вре́меннаго сего́ житія́ отше́ствіє і к ві́чності преселе́ніє, си́це нам в по́мощ предста́ніте і от наси́лій вра́жиїх свободи́те, я́коже предста́сте іногда́ Єра́зму мона́ху в тя́жком сме́ртном бі́дствії обріта́вшемуся, і си́це се́рдця на́ша к і́стинному покая́нію і жалі́нію о грехах подви́гніте, я́коже і о́наго се́рдце подвиго́сте, і́же в і́стинном покая́нії от зді́шніх к Бо́гу отиде, да і ми, в чи́стім со́вісти на́шея свиді́тельстві, Пресвяті́й і Неразділи́мій предста́вше Тро́йце, прославля́єм Ю ку́пно с ва́ми і всі́ми святи́ми в безконе́чния ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Зві́зди ми́сленния, / просія́вшия на тве́рди Церко́вній, / і́ноков Украї́нських основа́ніє / пі́сньми, лю́діє, почти́м, / ра́достния похвали́ сим воздаю́ще: / ра́дуйтеся, преблаже́ннії отці́, Анто́ніє с Феодо́сієм богому́дрим, // при́сно моля́щіїся о возсле́дствующих і чту́щих па́м'ять ва́шу."]},{"h":"Інший тропар, глас 3","ps":["Дво́їцю нача́льних Украї́нських світи́л почти́м: / Анто́нія, Бо́гом посла́ннаго, і Феодо́сія, Бо́гом дарова́ннаго. / Ті́ї бо пе́рвії, / равноа́нгельним в Украї́ні житіє́м просія́вше от гор Ки́євських, / освіти́ша оте́чествія на́шего вся конці́, / і путь к Небесі́ пра́вий мно́гим показа́ша, / і первоотці́ і́ноком би́вше, / ли́ки спаса́ємих Бо́гові приведо́ша, / і ни́ні, предстоя́ще во ви́шніх / немерца́ємому Божества́ Сві́ту // мо́ляться о душа́х на́ших."]},{"h":"Кондак, глас 8","ps":["Дво́їцю вели́ких оте́ць і пра́вило і́ноков сві́тлоє, / у́мния зари́ онебе́сившия Украї́нськую Це́рков / кто по достоя́нію хвала́ми воспоє́ть? / Ті́ї бо Престо́лу Бо́жию предстоя́ть. / Но я́ко іму́щії дерзнове́ніє к Святі́й Тро́йці, / Анто́ніє преблаже́нне і Феодо́сіє приснопа́м'ятне, / молі́теся о моле́бная к вам принося́щих, // і любо́вію пі́сньми вас ублажа́ющих."]},{"h":"Інший кондак, глас 2","ps":["Тве́рдия столпи́ благоче́стія, / недви́жимая і́ночеських законоположе́ній основа́нія, / і необори́мия сті́ни Украї́нськия восхва́лим: / Анто́нія, возлю́бльшаго Бо́га, / і Феодо́сія, возлю́бленнаго Бо́гом: / труди́ бо о́ніх і по́стничеськия по́двиги прия́т па́че вся́каго всепло́дія, // Єди́н во святи́х прославля́ємий."]},{"h":"Величання","ps":["Ублажа́єм вас, / преподо́бниє отці́ Анто́ніє і Феодо́сіє, / і чтим святу́ю па́м'ять ва́шу, / наста́вници мона́хов // і собесі́дниці А́нгелов."]}],"notes":[]},{"u":"Акафіст святим Семи отрокам Ефеським","e":"Akathist to the Holy Seven Youths of Ephesus","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії от воскре́сшаго пло́тію із ме́ртвих Христа́ Бо́га, во увіре́ніє о́бщаго всіх воскресе́нія ми́ру явле́ннії, преди́внії о́троци, і́же во Єфе́сі, прославля́юще просла́вльшагося во вас Го́спода, похва́льная пі́нія возно́сим вам, глаго́люще:","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, ві́дий ізнача́ла несумні́нную крі́пость іспові́данія ва́шего, сотвори́ вас в лю́тих обстоя́ніїх провозве́стники би́ти о́бщаго всіх воскресе́нія, я́ко ангелоподо́бния свиді́телі єва́нгельськаго обітова́нія. Сицево́му о нас смотре́нію Бо́жию див'я́щеся, во благогове́їнстві зове́м си́це:","Ра́дуйтеся, сві́тлия зві́зди гряду́щаго воскресе́нія;","ра́дуйтеся, пресла́внії лучи́ Христа́ Спа́са воскре́сшаго.","Ра́дуйтеся, денни́це вели́каго дне Госпо́дня;","ра́дуйтеся, із домо́в неві́рних ві́рная Христу́ ча́да яви́вшіїся.","Ра́дуйтеся, в чу́дний світ і свобо́ду сино́во воскресе́нія призва́ннії;","ра́дуйтеся, Ду́хом Святи́м в пропові́дники глаго́лов живота́ ві́чнаго ізбра́ннії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 2","ps":["Ви́дяще вас роди́телі ра́зум добр іму́щая, потща́шася в чин во́їнський дружи́ни царе́ви вас устро́їти; ви же, вся тлі́нная ми́ра презрі́вше, в Сіо́н го́рній к Царю́ Небе́сному сердці́ свої́ми востеко́сте, да я́ко дру́зі Бо́жії і служи́теліє та́йни о́бщаго воскресе́нія вмене́нни бу́дете, пою́ще Христу́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Христо́в чи́стими душа́ми восприя́ти сподо́бившеся, ди́внії о́троци, посреді́ гріхо́вния жи́зні све́рстник ва́ших благода́тію Христо́вою соблюда́єми, друг ко дру́гу любо́вію і єдине́нієм ду́ха бра́тіє яви́стеся, і во єди́но сверше́нни би́сте. Сего́ ра́ди приймі́те от нас похвали́ сія́:","Ра́дуйтеся, єди́ною ба́нею пакибитія́ возрожде́ннії;","ра́дуйтеся, любо́вію Христо́вою а́ки бра́тіє соєдине́ннії.","Ра́дуйтеся, Це́ркве Бо́жия ча́да возлю́бленная;","ра́дуйтеся, А́нгелов Бо́жиїх собесі́дниці.","Ра́дуйтеся, па́че бра́шен єсте́ственних і́стинним хлі́бом жи́зні себі́ пита́вшії;","ра́дуйтеся, се́ю пи́щею чрез благода́ть Свята́го Ду́ха от сме́рти в жизнь процві́тшії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго, таї́нники благода́ті в злострада́ніїх укріпля́ющи, сих вінце́м добропобе́дним іспові́данія увінча́тися пред челові́ки і а́нгели сподо́би, нас же научи́ пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще тща́ніє в дом Госпо́день на моли́тву по вся дні приходи́ти, ніка́коже сего́ оби́чая отверго́стеся, святі́ї, гоне́нію Де́кієву би́вшу; є́же уві́дівше вразі́ ві́ри Христо́ви, царя́ о сем ізвісти́ти потща́шася, оба́че мучи́телева преще́нія на прославле́ніє вам си́лою Бо́жиєю преміни́шася. Таково́му у́бо о вас Бо́жию промишле́нію ра́дующеся, со умиле́нієм глаго́лем вам си́це:","Ра́дуйтеся, те́мния си́ли кня́зя ми́ра сего́ благода́тію Христо́вою сокруши́вшії;","ра́дуйтеся, зло́бу і кова́рство слуг єго́ всепобе́дно посрами́вшії.","Ра́дуйтеся, ко́зней і преще́ній їх не убоя́вшіїся, ніже́ смути́вшіїся;","ра́дуйтеся, по́мощію Бо́жиєю ви́димо укрепи́вшіїся.","Ра́дуйтеся, я́ко дре́вле Данії́л в пеще́рі льво́ве, посреді́ мучи́телей сохране́ннії;","ра́дуйтеся, си́лою Влади́чнею із среди́ їх неврежде́нно ізведе́ннії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 4","ps":["Бу́рею я́рости дви́жим, злочести́вий Де́кий цар во гні́ві святи́я вопроша́єть: почто́ не би́сте с на́ми в пра́здник бого́в, всю вселе́нную призва́вших к поклоне́нію? Єму́же Максимилія́н, єди́н от седьми́, отвіща́єть: і́мами єди́наго Бо́га і Царя́, і́же на небесі́, Єму́же прино́сим на всяк час же́ртву хвале́нія, іспові́данія і моле́нія, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав нечести́вий цар, ка́ко ві́ру ва́шу со дерзнове́нієм іспові́даєте, че́сти во́їнськия лиши́ти вас повелі́, і та́ко іспита́нія ва́ша Христа́ ра́ди нача́шася, Христо́м скоропослу́шно в пречу́дноє успе́ніє преображе́нная. Ті́мже і ни́ні крі́пость в іспита́ніїх от Бо́га умолі́те пою́щим:","Ра́дуйтеся, во́їни царя́ земна́го, к во́їнству Царя́ небе́снаго сопричте́ннії;","ра́дуйтеся, честь земну́ю оста́вльшії, да сла́ву небе́сную воспри́ймете.","Ра́дуйтеся, земни́я че́сти за Христа́ лише́ннії;","ра́дуйтеся, сего́ ра́ди вінці́ нетлі́нними от Него́ увенча́ннії.","Ра́дуйтеся, побі́ди Єго́ пропові́дници явле́ннії;","ра́дуйтеся, сла́ви Єго́ ві́чния седьмочи́сленноє блиста́ніє.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 5","ps":["Боже́ственния любве́ теплото́ю грі́ємії, благода́тію Христо́вою от мучи́телей покрове́ни яви́лися єсте́, святі́ї о́троци, Максимилія́не, Іямвли́ше, Мартинія́не, Іоа́нне, Діоні́сіє, Єксакустодія́не же і Антони́не, в лі́тіх ю́них красоту́ вну́тренняго челові́ка с лі́потою вні́шнею сочетава́юще і, я́ко А́нгели, в пла́мені іспові́данія ва́шего воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів злохи́трий цар Де́кий зіло́ благолі́пную ю́ность ва́шу, на ні́колико дній і осла́бу от уз вам да́руєть, прельсти́ти вас ко отрече́нію от Христа́ наді́яся. Ви же, во своя́си отше́дше, сребро́ і зла́то ни́щим разда́ти потща́стеся, ко ісхо́ду себі́ уготовля́юще. Сего́ ра́ди воспису́єм вам похва́льная сія́:","Ра́дуйтеся, закосні́вшаго во злі мучи́теля на ні́коє милосе́рдіє подви́гшії;","ра́дуйтеся, младе́нчеською кро́тостію ва́шею кова́рную зло́бу єго́ на вре́м'я угаси́вшії.","Ра́дуйтеся, красото́ю сино́в сві́та злообра́зния служи́телі гріха́ пліни́вшії;","ра́дуйтеся, Ду́ха Свята́го благода́тію кова́рство їх побі́дно посрами́вшії.","Ра́дуйтеся, чрез раздая́ніє земни́х бога́тств сокро́вищем небе́сним обогати́вшіїся;","ра́дуйтеся, і нас взаї́м дава́ти Бо́гу науча́ющії, да бога́тство неоскудіва́ємоє на небесі́х обря́щем.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 6","ps":["Пропові́дуєть пеще́ра гори́ Охло́н чу́дную сла́ву ва́шу, святі́ї о́троци, де́бри бо і верте́пи єя́ моли́твою ва́шею облагоуха́ли єсте́, отону́дуже на тве́рди церко́вній, я́коже зві́зди сла́ви небе́сния, із мра́ка гробо́в чу́дно возсія́вшия, яви́стеся і нас Первонача́льнику о́бщаго воскресе́нія Христу́ Бо́гу пі́ти научи́сте: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ти хотя́ лю́дем світ і́стини, мглу же заблужде́нія разгна́ти, Христо́с Бог сни́ти вам во мрак моги́льний соізво́ли я́ко да по́сліжде в ди́внім воста́нії ва́шем о́бщеє воскресе́ніє уві́рить. Пред такови́м Бо́жиїм о вас благоволе́нієм преклоня́ющеся, возсила́єм вам хвале́нія сія́:","Ра́дуйтеся, тве́рдости ра́ди іспові́данія от мук промисли́тельно ізба́вленнії;","ра́дуйтеся, і нас крі́пці за пра́вду бра́тися науча́ющії.","Ра́дуйтеся, безболі́зненно по́двиг ваш сконча́вшії;","ра́дуйтеся, чу́дним сном почи́вшії, во є́же воста́нієм от сего́ сна сме́рті мглу заблужде́нія разсі́яти.","Ра́дуйтеся, в нетлі́нії тіле́с ва́ших Го́сподем соблюде́ннії;","ра́дуйтеся, пре́жде о́бщаго воскресе́нія ізволе́нієм Бо́жиїм воста́вшії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 7","ps":["Хотя́ безбо́жний цар ну́ждею к ідолослуже́нію святи́я привлещи́, па́ки пра́здник і́дольський устроя́єть і ти́я нань привести́ повеліва́єть; не обрі́тшим же тіх во гра́ді Єфе́сі слуго́м єго́, роди́телі їх ка́знію устраши́ти тщи́ться, но от сих ізвіще́н бива́єть, я́ко святі́ї в пеще́рі сокри́шася, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє устремле́ніє зло́би мир яви́л єсть, єгда́ роди́теліє мі́сто поко́їща чад свої́х царе́ві откри́ша, і та́ко любве́ о́тчія к ним отреко́шася. Сего́ ра́ди ко ізбра́нником Бо́жиїм глаго́лем си́це:","Ра́дуйтеся, ми́ром отве́рженнії і Не́бо восприя́вшії;","ра́дуйтеся, Отця́ ра́ди Небе́снаго отці́ земни́ми пре́даннії.","Ра́дуйтеся, оте́чеською любо́вію Єго́ в таї́нственнем сні чу́дно сохране́ннії;","ра́дуйтеся, нетлі́ніє улучи́вшії і мир сві́том воскресе́нія осія́вшії.","Ра́дуйтеся, путь к сему́ ди́вному сві́ту нам указу́ющії;","ра́дуйтеся, час кончи́ни сбитіє́м обітова́нія Бо́жия нам услажда́ющії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до всемогу́щества Бо́жия на вас, святі́ї о́троци, показа́ся, ка́менієм бо по повелі́нію Де́кієву в пеще́рі загражде́ннії і печа́тію запечатле́ннії, сто і о́смдесят літ да́же до дній царя́ Феодо́сія та́мо спя́ще преби́ли єсте́, воста́вше же а́ки живі́ї, саддуке́йськоє мудрова́ніє посрами́ли єсте́, пою́ще Христу́, вас воскреси́вшему: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь седьмочи́сленний іспові́дников лик, во гро́бі ка́меннім заключе́н бив, жи́зні ві́чния ніка́коже отлучи́ся, но істе́кшим стом і осми́десятим лі́том сон от оче́с їх проізволе́нієм Бо́жиїм отрясе́ся, і та́ко святі́ї о́троци живі́ї воста́ша, весь мир о воскресе́нії всіх увіря́юще і нас пі́ти науча́юще си́це:","Ра́дуйтеся, упова́ніє о́бщаго воскресе́нія обітова́нієм Бо́жиїм утвержда́ющії;","ра́дуйтеся, краєуго́льнаго ра́ди Ка́мене Христа́ Бо́га ка́менієм во гро́бі загражде́ннії.","Ра́дуйтеся, Єго́ ра́ди, во гро́бі запечатле́ннаго, печа́тію запечатле́ннії;","ра́дуйтеся, А́гнцем, взе́мшим на Себі́ гріх ми́ра, от уз сме́рті свобожде́ннії.","Ра́дуйтеся, во увіре́ніє о́бщаго воскресе́нія, я́коже Ла́зар четверодне́вен, із гро́ба ізведе́ннії;","ра́дуйтеся, числу́ седьми́ херуви́м, Престо́лу сла́ви Бо́жия предстоя́щих, сообра́знії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє возра́довася о чу́днім по мно́зіх лі́тіх воста́нії ва́шем і ужаса́шеся: ка́ко ви, пресла́внаго у́бо чудесе́, о вас би́вшаго, не ві́дуще, оби́чноє цілова́ніє друг дру́гу подає́те і у́треннєє пі́ніє Го́споду, а́ки вчера́ ко сну отше́дшії, прино́сіте, пою́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий язи́к не возмо́жеть ізрещи́ чуде́с Твої́х, Го́споди, ві́ми бо, ка́ко блаже́нний о́трок Іамвли́х, многоле́тняго успе́нія своєго́ не разумі́я і во град за пи́щею ісше́дий, удиви́ся, єгда́ Єфе́с, Христо́вою ві́рою ізда́вна просвіще́нний, уви́ді, і Го́спода просла́ви, нас же глаго́лати сотвори́ такова́я:","Ра́дуйтеся, ді́лателіє на ни́ві Госпо́дней, моли́твенния сле́зи оби́льно проли́вшії;","ра́дуйтеся, в ску́дости і гоне́нії почи́вшії, во сла́ві і бога́тстві воста́вшії.","Ра́дуйтеся, зрі́нієм торжества́ ві́ри Христо́ви, во дні ва́ша гони́мия, по воста́нії обра́дованнії;","ра́дуйтеся, побі́ду Христа́ над ми́ром я́ві узре́вшії.","Ра́дуйтеся, і нас на сію́ упова́ти науча́ющії;","ра́дуйтеся, от уни́нія нас огражда́ющії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Бог і во ві́рі утверди́ти лю́ди, сія́ о многоле́тнем успе́нії Іамвли́ха чрез дре́вній пі́нязь, на то́ржищі їм принесе́нний, науча́єть, єпи́скопу гра́да сія́ уразуме́вшу і Бо́га просла́вившу с пі́снію: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і утвержде́ніє ві́ри яви́стеся, святі́ї, челові́ком, в пеще́ру ва́шу прише́дшим і ковче́жець с хартіє́ю обрі́тшим, на не́йже імена́ ва́ша і кончи́ни о́браз напи́сана би́ша, во є́же пі́ти всім:","Ра́дуйтеся, седьм ізбра́нних сосу́дов Бо́жиїх;","ра́дуйтеся, вку́пі со святи́ми му́ченики єле́єм ра́дованія пома́заннії.","Ра́дуйтеся, седьм світи́льников пред Престо́лом Хода́тая Бо́га і челові́ков;","ра́дуйтеся, седьм труб благові́стія втора́го прише́ствія Си́на Челові́чеськаго.","Ра́дуйтеся, седьм а́нгел, благовіству́ющих нам сла́ву до конця́ претерпі́вших;","ра́дуйтеся, я́ко седьмисве́щник злати́й, це́рков Бо́жию украша́ющії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє Пресвяті́й Тро́йце вознося́, благочести́вий цар Феодо́сій со тща́нієм во Єфе́с устреми́ся, во є́же святи́я о́троки ви́діти, і седьм дній та́мо пребива́ше, до́ндеже сії́, глави́ прекло́нше, дух свой Го́споду преда́ша, ку́пно с ни́ми побі́дную возсила́я піснь Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници, тьму є́ресі разгоня́ющії, яви́лися єсте́, святі́ї о́троци, сві́том нетлі́нія ва́шего сія́ющії і блаже́нним по воста́нії па́ки успе́нієм і́стину гряду́щаго живота́ утвержда́ющії, саддуке́йськоє бо мудрова́ніє посрами́вше, вся раздо́ри церко́вния ути́шили єсте́, о́бщеє воскресе́ніє вку́пі с дре́внім Ла́зарем увіря́юще. Ті́мже, благодаря́ще о сем Го́спода, со умиле́нієм зове́м вам:","Ра́дуйтеся, ско́рбноє житіє́ на́ше до́брим упова́нієм осіява́ющії;","ра́дуйтеся, посреді́ волн житія́ сего́ к приста́нищу небе́сному нас направля́ющії.","Ра́дуйтеся, я́ко зві́зди, во оти́шіє блаже́ннаго поко́я в черто́зі Христо́ві нас путеводя́щії;","ра́дуйтеся, блаже́нство ві́чноє, скорб'я́щим угото́ванноє, благовіству́ющії.","Ра́дуйтеся, я́ко недосто́йни суть стра́сті ни́нішняго вре́мене к бу́дущей сла́ві, уверя́ющії;","ра́дуйтеся, до́блії ві́стници ца́рства небе́снаго би́вшії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 12","ps":["Благода́ть даде́ся вам от Бо́га, во є́же вся лю́б'ящия і чту́щия ви в чу́дний світ Єго́ руково́дствовати. Ті́мже і на́шея жи́зні ско́рбний путь крі́пкою наде́ждою воскресе́нія озарі́те, от гріхо́вния поги́белі нас соблюді́те і в час сме́ртний нам предста́ніте, да ва́шим заступле́нієм невече́рняго сві́та вели́чествія Бо́жия і ми грі́шнії дости́жем, іді́же с ли́ки пра́ведних воспої́м о вас Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́вноє прославле́ніє си́ли Бо́жия во вас, святі́ї о́троци, ублажа́єм ви, я́ко засту́пники і моли́твенники на́ша пред Го́сподем, і с любо́вію, святі́й іко́ні ва́шей предстоя́ще, возглаша́єм вам хвале́нія сія́:","Ра́дуйтеся, в Украї́нській землі́ гра́да Ста́риці похвало́ і утвержде́ніє;","ра́дуйтеся, вся окре́стния ві́си сла́вою благода́тния по́мощі ва́шея іспо́лнившії.","Ра́дуйтеся, боля́щих младе́нцев прибі́жище і ісціле́ніє;","ра́дуйтеся, скорбе́й роди́телей їх нело́жноє врачева́ніє.","Ра́дуйтеся, всім лю́б'ящим і чту́щим ви покро́ве і огражде́ніє;","ра́дуйтеся, всего́ ми́ра христия́нськаго по́моще і заступле́ніє.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 13","ps":["О чу́днії о́троци, сві́том небе́сния сла́ви ва́шея і увіре́нієм несконча́ємаго живота́ ско́рбний путь житія́ на́шего озаря́ющії! Приймі́те ма́лоє сіє́ моле́ніє на́ше і не отри́ніте нас, притека́ющих к вам: молі́те при́сно всіх Влади́ку, да і ми ра́йськаго черто́га не лише́ни бу́дем, но вку́пі со святи́ми воспої́м та́мо Христу́ Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, ві́дий ізнача́ла несумні́нную крі́пость іспові́данія ва́шего, сотвори́ вас в лю́тих обстоя́ніїх провозве́стники би́ти о́бщаго всіх воскресе́нія, я́ко ангелоподо́бния свиді́телі єва́нгельськаго обітова́нія. Сицево́му о нас смотре́нію Бо́жию див'я́щеся, во благогове́їнстві зове́м си́це:","Ра́дуйтеся, сві́тлия зві́зди гряду́щаго воскресе́нія;","ра́дуйтеся, пресла́внії лучи́ Христа́ Спа́са воскре́сшаго.","Ра́дуйтеся, денни́це вели́каго дне Госпо́дня;","ра́дуйтеся, із домо́в неві́рних ві́рная Христу́ ча́да яви́вшіїся.","Ра́дуйтеся, в чу́дний світ і свобо́ду сино́во воскресе́нія призва́ннії;","ра́дуйтеся, Ду́хом Святи́м в пропові́дники глаго́лов живота́ ві́чнаго ізбра́ннії.","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Кондак 1","ps":["Ізбра́ннії от воскре́сшаго пло́тію із ме́ртвих Христа́ Бо́га, во увіре́ніє о́бщаго всіх воскресе́нія ми́ру явле́ннії, преди́внії о́троци, і́же во Єфе́сі, прославля́юще просла́вльшагося во вас Го́спода, похва́льная пі́нія возно́сим вам, глаго́люще:","Ра́дуйтеся, страстоте́рпці Христо́ви, всеми́рнаго воскресе́нія ме́ртвих пречу́днії пропові́дници."]},{"h":"Молитва перша","ps":["Бо́же вели́кий, хва́льний і непостижи́мий, і неісповіди́мий, созда́вий челові́ка руко́ю Твоє́ю, персть взем от землі́, і о́бразом Твої́м почти́вий єго́, Ісу́се Христе́, прежела́ємоє і́м'я, со Безнача́льним Твої́м Отце́м і с Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, яви́ся на рабі́ Твоє́м (ім'ярі́к), і посіти́ єго́ ду́шу і ті́ло, умоля́єм от пресла́вния Влади́чиці на́шея Богоро́диці і Присноді́ви Марі́ї, святи́х Небе́сних Сил Безпло́тних, і честна́го сла́внаго проро́ка, і Предте́чі і Крести́теля Іоа́нна, святи́х сла́вних і всехва́льних апо́столов, і́же во святи́х оте́ць на́ших, і вселе́нських учи́телей, Васи́лія Вели́каго, Григо́рія Богосло́ва, Іоа́нна Златоу́стаго, Афана́сія і Кири́лла, Никола́я і́же в Ми́ріх, Спиридо́на чудотво́рця, і всіх святи́х священнонача́льников, свята́го апо́стола первому́ченика і архідия́кона Стефа́на, святи́х сла́вних великому́чеников Гео́ргия Побідоно́сця, Дими́трія Мирото́чця, Фео́дора Стратила́та, і всіх святи́х му́чеников, преподо́бних і богоно́сних оте́ць на́ших Анто́нія, Євфи́мія, Са́вви Освяще́ннаго, Феодо́сія о́бщаго житія́ нача́льника, Ону́фрія, Арсе́нія, Афана́сія Афо́нськаго, і всіх преподо́бних, святи́х і ісціли́телей, безсре́бренников Косьми́ і Дамія́на, Ки́ра і Іоа́нна, Фалале́я і Три́фона і про́чих, свята́го пра́веднаго Іоа́нна Кроншта́дтськаго, свята́го преподо́бнаго Іоа́нна Ри́льськаго, святи́я блаже́нния Ксе́нії Петербу́ржськой і всіх Твої́х святи́х. І даждь єму́ сон упокоє́нія, сон тіле́сний здра́вія і спасе́нія і живота́, і крі́пость душе́вную і тіле́сную, я́коже посіти́л єси́ іногда́ Авимеле́ха уго́дника Твоєго́ во хра́мі Агри́ппові, і дал єси́ єму́ сон утіше́нія, є́же не ви́діти паде́нія Ієрусали́мова, і сего́ успи́вий сном пита́тельним, і па́ки сего́ воскреси́вий во єди́ном мгнове́нії вре́мене, в сла́ву Твоєя́ бла́гости. Но і святи́я Твоя́ сла́вния седьм о́троки, іспові́дники і свиді́телі Твоєго́ явле́нія показа́вий, во дні Де́кия царя́ і отсту́пника, і сія́ успи́вий во верте́пі на літ сто і о́смдесят, я́ко младе́нці согріва́ємия в ложесна́х ма́тере своєя́, і ніка́коже претерпі́вшия тлі́нія, в похвалу́ і сла́ву человіколю́бія Твоєго́, і в показа́ніє, і ізвіще́ніє на́шего пакибитія́, і воскресе́нія всіх. Сам у́бо Человіколю́бче Царю́, предста́ни і ни́ні наї́тієм Свята́го Твоєго́ Ду́ха, і посіти́ раба́ Твоєго́ (ім'ярі́к), і да́руй єму́ здра́віє, крі́пость, і благомо́щіє, Твоє́ю бла́гостію, я́ко от Тебе́ єсть вся́ко дая́ніє бла́го, і всяк дар соверше́н. Ти бо єси́ врач душ і тіле́с на́ших, і Тебі́ сла́ву і благодаре́ніє і поклоне́ніє возсила́єм, со Безнача́льним Твої́м Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О пречу́днії святі́ї седьмочи́сленнії о́троци, Єфе́са гра́да похвало́ і всея́ вселе́нния упова́ніє! Воззрі́те с висоти́ небе́сния сла́ви на нас, любо́вію па́м'ять ва́шу чту́щих, найпа́че же на младе́нці христия́нськия, ва́шему заступле́нію от роди́телей свої́х препоруче́нния. Низведі́те на ни благослове́ніє Христа́ Бо́га, ре́кшаго: оста́віте діте́й приходи́ти ко Мні. Боля́щия у́бо в них ісцілі́те, скорб'я́щия уті́шіте; сердця́ їх в чистоті́ соблюді́те, кро́тостію іспо́лніте я, і в землі́ серде́ць їх зерно́ іспові́данія Бо́жия насаді́те і укріпі́те, во є́же от си́ли в си́лу їм возраста́ти. І всіх нас, святі́й іко́ні ва́шей предстоя́щих рабо́в Бо́жиїх (ім'ярі́к), і те́плі вам моля́щихся, сподо́біте Ца́рствіє Небе́сноє улучи́ти і немо́лчними гла́си ра́дованія та́мо прославля́ти великолі́поє і́м'я Пресвяти́я Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Ве́лія ві́ри чудесе́, / в пеще́рі, я́ко в черто́зі ца́рськом, / святі́ї седьм о́троци преби́ша, / і умро́ша без тлі, / і по мно́зіх вре́меніх воста́ша, я́ко от сна, / во увіре́ніє воскресе́нія всіх челові́ков. // Тіх моли́твами, Христе́ Бо́же, поми́луй нас."]},{"h":"Кондак, глас 4","ps":["Ми́ра су́щая тлі́нная презрі́вше, / і нетлі́нния да́ри приє́мше, / уме́рше, кромі́ тлі́нія преби́ша. / Ті́мже востаю́ть по мно́гих лі́тіх, / все погре́бше лю́тих неві́ріє, // я́же во хвале́нії днесь, ві́рнії, восхваля́юще, Христа́ воспої́м."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпці святі́ї, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст святому апостолу Хомі","e":"Akathist to the Holy Apostle Thomas","secs":[{"h":"Кондак 1","ps":["Ізбра́нний самови́дче Сло́ва і свиді́телю Єго́ сла́вний, да́же до послі́дніх землі́ благовісти́л єси́ ві́ру твою́: «Єго́же ра́ни аз осяза́х, Сей єсть Госпо́дь і Бог». Ті́мже і ни́ні, созерца́яй нам незри́мая, за взиску́ющия ві́ри моли́ся, да зове́м ті:","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Ікос 1","ps":["А́нгелом неві́домоє та́їнство позна́л єси́, Плоть Бо́га жи́ва дерзнове́нною десни́цею осяза́я, ті́мже, ужаса́ющеся і див'я́щеся, зове́м ті:","Ра́дуйся, я́ко дерзнове́ніє твоє́ Бог предуві́ді;","ра́дуйся, я́ко на служе́ніє Своє́ тя предуста́ви.","Ра́дуйся, я́ко неві́ріє твоє́ не осуди́ся;","ра́дуйся, я́ко ві́ра твоя́ утверди́ся.","Ра́дуйся, я́ко Христо́с в лик апо́стольський тя ізбра́;","ра́дуйся, я́ко стопи́ твоя́ по словесі́ Своєму́ напра́ви.","Ра́дуйся, я́ко уста́ ко усто́м тебі́ бисть Бо́жиє віща́ніє;","ра́дуйся, я́ко приклони́ся Госпо́дь к любопи́тнаго пе́рста осяза́нію.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 2","ps":["«Словеса́ ва́ша о явле́нії Воскре́сшаго неудобоприя́тельна мі явля́ються, — вопія́ше Фома́ іни́м ученико́м, — а́ще не ви́жду на руку́ Єго́ я́зви гвозди́нния, і не вложу́ пе́рста моєго́ в я́зви гвозди́нния, і вложу́ ру́ку мою́ в ре́бра Єго́, не дерзну́ взива́ти Сему́: Аллилу́я»."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий догма́тов ві́ри разумі́ти і́щуще, вопроша́єм в см'яте́нії: во двою́ єстеству́ єди́но Лице́ ка́ко Це́рков му́дрствуєть і воспіва́єть? Оба́че неві́рієм твої́м, апо́столе, увіря́ємі в сем, взива́єм:","Ра́дуйся, я́ко Христо́с єди́н хліб с тобо́ю вкуси́;","ра́дуйся, я́ко єди́но со́лнце над ва́ма возсія́.","Ра́дуйся, я́ко хлі́бом і́стини мно́гі наси́тил єси́;","ра́дуйся, я́ко Со́лнце пра́вди возлюби́л єси́.","Ра́дуйся, я́ко єди́н істо́чник ви напої́;","ра́дуйся, я́ко єди́на смоко́вниця ва́ма сінь даде́.","Ра́дуйся, я́ко рі́ки благода́ті істочи́л єси́;","ра́дуйся, я́ко не безпло́дная смоко́вниця показа́лся єси́.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 3","ps":["«Си́лі Ви́шняго вся возмо́жна суть, — вопія́ше Фома́, — мо́жеть бо і уме́ршія воскреша́ти, оба́че ка́ко сме́рті приобщи́ся Сей, Єму́же подоба́єть воспіва́ти: Аллилу́я»."]},{"h":"Ікос 3","ps":["Богоприя́тну Ді́ву прозрі́ младе́нець, во чре́ві Єлисаве́тином сий, ми же, о́чі іму́ще, не зрим блага́я діла́ Госпо́дня, оба́че сло́во Христо́во, апо́столу рече́нноє: блаже́нні не ви́дівшії і ві́ровавшії, помина́єм с наде́ждою, і та́ко сему́ взива́єм:","Ра́дуйся, спасе́нія возжела́вий;","ра́дуйся, я́ко проро́ки ча́янная узрі́л єси́.","Ра́дуйся, Ада́мом утра́ченная взиска́вий;","ра́дуйся, я́ко Спаси́теля обрі́л єси́.","Ра́дуйся, Сві́том ми́ра просвіще́нний;","ра́дуйся, я́ко Не́бо отве́рзеся ті.","Ра́дуйся, Сло́вом О́тчим умудре́нний;","ра́дуйся, я́ко та́йни Ца́рствія откри́шася ті.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 4","ps":["«Бу́рю внутр імі́ю помишле́ній сумни́тельних, — вопія́ше Фома́, — ка́ко бо во гроб положе́н бисть по вода́м Ходи́вий і Ла́заря Воскреси́вий, Єму́же аз жела́ю воспі́ти: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шаша у́бо па́стиріє А́нгелов, пою́щих Младе́нця Спа́са, і, ше́дше, поклони́шася Єму́; ми же, у́ші іму́ще, не вне́млем гла́су Госпо́дню, оба́че на твоє́ предста́тельство, апо́столе, упова́єм і зове́м ті:","Ра́дуйся, в корабли́ со Христо́м ходи́вий;","ра́дуйся, по волна́м Ходя́щу поклони́вийся.","Ра́дуйся, мре́жею Христо́вою уловле́нний;","ра́дуйся, в ковче́г спасе́нія ступи́вий.","Ра́дуйся, я́ко во́ди неві́рствія не поглоти́ша тя;","ра́дуйся, я́ко бу́ря сомні́ній тя не потопи́.","Ра́дуйся, я́ко Христо́с над бе́здною тя удержа́;","ра́дуйся, я́ко десни́цю с я́звою ті простре́.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 5","ps":["«Боготе́чной звізді́ послі́доваша волсви́, — вопія́ше Фома́, — та́ко і аз вожделі́ю слі́довати Тебі́, Го́споди і Бо́же мой, даждь мі то́кмо прикосну́тися Ті, да і аз воспою́: Аллилу́я»."]},{"h":"Ікос 5","ps":["Да́ри принесо́ша халде́йстії о́троци сідя́щу на руку́ Діви́чу Созда́телю тва́рі, ми же, ру́ці іму́ще пра́здни от діл благи́х, ка́ко присту́пим к Сему́, ві́ри прося́ще, а́ще не апо́стола Фому́ помина́юще і та́ко єму́ зову́ще:","Ра́дуйся, я́ко Господи́н жа́тви призва́ тя;","ра́дуйся, я́ко во вертогра́ді Того́ до́брі потруди́лся єси́.","Ра́дуйся, я́ко ді́латель і ни́ва яви́лся єси́;","ра́дуйся, я́ко плод стори́цею прине́сл єси́.","Ра́дуйся, я́ко со Влади́кою дній у́треневал єси́;","ра́дуйся, я́ко ча́шу Христо́ву іспи́л єси́.","Ра́дуйся, я́ко і нощ просвіще́ніє ті бисть;","ра́дуйся, я́ко Го́споду Сла́ви спросла́вился єси́.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 6","ps":["«Пропові́дници богоно́сни би́вше волсви́, — вопія́ше Фома́, — іспові́даша Тя, Христе́, я́ко Спа́са всіх; а́ще у́бо не уві́рую во Воскресе́ніє Твоє́, не явлю́ся ли і аз я́ко І́род, не ві́дий пі́ти: Аллилу́я»."]},{"h":"Ікос 6","ps":["Возсія́вий во Єги́пті Світ і́стини да разсі́єть, я́ко дим, вся сомні́нія на́ша: ві́руєм бо, Го́споди, помози́ неві́рію на́шему; ти же, апо́столе, укріпи́ свиді́тельством твої́м зову́щия ті:","Ра́дуйся, в сла́дость Христа́ послу́шавий;","ра́дуйся, во сла́ву Єго́ пожи́вий.","Ра́дуйся, с терпі́нієм Тому́ послужи́вий;","ра́дуйся, с весе́лієм за Него́ уме́рий.","Ра́дуйся, ра́ну Прободе́ннаго осяза́вий;","ра́дуйся, Кро́вію Христо́вою іскупле́нний.","Ра́дуйся, копіє́м мучи́тельським прободе́нний;","ра́дуйся, кров за Христа́ пролія́вий.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 7","ps":["«Хотя́щу Симео́ну пра́ведному умре́ти, — вопія́ше Фома́, — вда́лся єси́ я́ко Младе́нець тому́, но позна́лся єси́ єму́ і Бог соверше́нний; сотвори́ у́бо, Го́споди, і мні та́ко, да а́біє воззову́ Ті: Аллилу́я»."]},{"h":"Ікос 7","ps":["Но́воє показа́ Творе́ць снисхожде́ніє нам, на безсме́ртнім Ті́лі сме́ртния я́зви яви́ти ізво́ливий апо́столу Своєму́, єму́же с любо́вію взива́єм:","Ра́дуйся, от Прему́дрости му́дрость приє́мий;","ра́дуйся, от Любве́ любві́ научи́вийся.","Ра́дуйся, у Смире́нія смире́нію нави́кший;","ра́дуйся, Бла́гом во бла́зі утвержде́нний.","Ра́дуйся, Терпі́нієм в терпі́нії наста́вленний;","ра́дуйся, Кро́тости в кро́тості подража́вий.","Ра́дуйся, Послуша́нієм к послуша́нію приведе́нний;","ра́дуйся, Си́ном Отцю́ усиновле́нний.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 8","ps":["«Стра́нноє чу́до ви́жду, — вопія́ше Фома́. — Две́рем затворе́нним, я́ко дух, вхо́дить Христо́с. Осяза́ю оба́че ра́ни і я́зви Єго́, і что у́бо реку́, то́кмо: Госпо́дь мой і Бог мой; что у́бо воспою́, то́кмо: Аллилу́я»."]},{"h":"Ікос 8","ps":["Всі єсьми́ в ни́жніх і ви́шніх ніка́коже достига́єм, оба́че ві́руєм, я́ко обоя́ соєдини́ в Себі́ Госпо́дь, я́коже яви́ сіє́ апо́столу Своєму́, от нас воспева́єму си́це:","Ра́дуйся, с четверодне́вним Ла́зарем вечеря́вий;","ра́дуйся, увіре́нія во і́стині ре́вностно взиска́вий.","Ра́дуйся, «Оса́нна во ви́шніх!» возгласи́вий;","ра́дуйся, любо́вію увіре́ніє сіє́ улучи́вий.","Ра́дуйся, воплоще́ніє Сло́ва уві́дівий;","ра́дуйся, ми́ром гони́мий.","Ра́дуйся, безслове́сная пло́ті попра́вий;","ра́дуйся, мир от Христа́ приє́мий.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 9","ps":["«Вся́коє єстество́ тва́рноє вмісти́ти Боже́ственноє ніка́коже возмога́єть, — вопія́ше Фома́, — Ти Єди́ний о́ба несли́тно і неразді́льно в Себі́ сочета́л єси́, Тебі́ пою́: Аллилу́я»."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії нічесо́же приложи́ти дерза́ють, апо́столе, до́брому іспові́данію твоєму́: Госпо́дь мой і Бог мой; за сіє́ і от нас прийми́ сицева́я:","Ра́дуйся, я́ко но́зі ко умове́нію Христу́ просте́рл єси́;","ра́дуйся, я́ко до́ма на землі́ не імі́л єси́.","Ра́дуйся, я́ко но́зі на путь ми́рен напра́вил єси́;","ра́дуйся, я́ко оби́тель в дому́ О́тчі сниска́л єси́.","Ра́дуйся, я́ко строї́тель ца́рський наре́клся єси́;","ра́дуйся, я́ко архите́ктон прему́дрий обрі́лся єси́.","Ра́дуйся, я́ко зла́то ни́щим разда́л єси́;","ра́дуйся, я́ко черто́г Небе́сний царю́ воздви́гл єси́.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 10","ps":["«Спасти́ хотя́ мир, — вопія́ше Фома́, — животворя́щею Кро́вію із прободе́нних ребр, Го́споди Бо́же мой, напої́л єси́ вся, я́же осяза́в, Тебі́ пою́: Аллилу́я»."]},{"h":"Ікос 10","ps":["Сті́ни Ієрусали́ма Небе́снаго на двана́десяти основа́ніїх утверди́шася; я́коже єди́но от сих тя почита́єм, апо́столе сла́вне, і та́ко ті воспису́єм:","Ра́дуйся, я́ко язи́к о́гнен на тебі́ почи́;","ра́дуйся, я́ко сла́ва Христо́ва тя осія́.","Ра́дуйся, я́ко язи́ки мно́гі просвіти́л єси́;","ра́дуйся, я́ко і́м'я Христо́во просла́вил єси́.","Ра́дуйся, я́ко неду́жних ісціля́л єси́;","ра́дуйся, я́ко ме́ртвих восставля́л єси́.","Ра́дуйся, я́ко і ду́си повинова́хуся ті;","ра́дуйся, я́ко і́м'я твоє́ написа́ся на Небесі́.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 11","ps":["«Пі́ніє вся́коє побіжда́ється, — вопія́ше Фома́, — тща́щеєся воспі́ти сла́ву Воскресе́нія Твоєго́, Го́споди, оба́че сіє́ возвіщу́ до послі́дніх землі́, да всяк язи́к І́стинному Бо́гу зове́ть: Аллилу́я»."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим тя, апо́столе сла́вний, прикоснове́нієм к обоже́нной Пло́ті возжже́нную, ті́мже прино́сим ті сицева́я:","Ра́дуйся, би́сере ри́зи церко́вния;","ра́дуйся, вертогра́дарю І́стини.","Ра́дуйся, ко́реню богосло́вія;","ра́дуйся, цві́те благоче́стія.","Ра́дуйся, ро́ждіє лози́ боже́ственния;","ра́дуйся, благоуха́ніє, прия́тно Бо́гові.","Ра́дуйся, злати́це, огне́м очище́нная;","ра́дуйся, весно́ цілому́дрія.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 12","ps":["«Благода́ть і жизнь прише́дий да́ти вся́кой пло́ті, — вопія́ше Фома́ іни́м ученико́м, — не возда́сть ли сія́ Пода́вшей Єму́ плоть? Оба́че укажі́те мні гроб Єя́, да со слеза́ми воззову́ Бо́гові: Аллилу́я»."]},{"h":"Ікос 12","ps":["Пою́ще Успе́ніє Богоро́диці, апо́столи проводи́ша тя ко гро́бу Єя́, і, вшед і обрі́т сей пуст, возда́л єси́ хвалу́ Го́споду; ті́мже зове́м ті:","Ра́дуйся, Бо́жиєю Ма́терію возлю́бленний;","ра́дуйся, ко проща́нію То́ю призва́нний.","Ра́дуйся, я́ко ма́тер, Ю возлюби́вий;","ра́дуйся, Бо́жиїм Про́мислом удержа́нний.","Ра́дуйся, на гроб Єя́ пла́кати прише́дий;","ра́дуйся, ка́мень от него́ отвали́вий.","Ра́дуйся, ра́дость ве́лію лю́дем откри́вий;","ра́дуйся, воста́ніє Пречи́стия возвісти́вий.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 13","ps":["О пресла́вний апо́столе Христо́во Фомо́, ма́лоє сіє́ прийми́ от нас приноше́ніє і умоли́ за ни Го́спода Сла́ви, да утверди́вшеся по́мощію твоє́ю, обря́щем і ми ві́ри плоди́ благи́я, Творцю́ вся́чеських пою́ще: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом неві́домоє та́їнство позна́л єси́, Плоть Бо́га жи́ва дерзнове́нною десни́цею осяза́я, ті́мже, ужаса́ющеся і див'я́щеся, зове́м ті:","Ра́дуйся, я́ко дерзнове́ніє твоє́ Бог предуві́ді;","ра́дуйся, я́ко на служе́ніє Своє́ тя предуста́ви.","Ра́дуйся, я́ко неві́ріє твоє́ не осуди́ся;","ра́дуйся, я́ко ві́ра твоя́ утверди́ся.","Ра́дуйся, я́ко Христо́с в лик апо́стольський тя ізбра́;","ра́дуйся, я́ко стопи́ твоя́ по словесі́ Своєму́ напра́ви.","Ра́дуйся, я́ко уста́ ко усто́м тебі́ бисть Бо́жиє віща́ніє;","ра́дуйся, я́ко приклони́ся Госпо́дь к любопи́тнаго пе́рста осяза́нію.","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Кондак 1","ps":["Ізбра́нний самови́дче Сло́ва і свиді́телю Єго́ сла́вний, да́же до послі́дніх землі́ благовісти́л єси́ ві́ру твою́: «Єго́же ра́ни аз осяза́х, Сей єсть Госпо́дь і Бог». Ті́мже і ни́ні, созерца́яй нам незри́мая, за взиску́ющия ві́ри моли́ся, да зове́м ті:","Ра́дуйся, апо́столе Фомо́, неві́рієм до́брим ві́ру утверди́вий."]},{"h":"Молитва","ps":["О благознамени́тий і сла́вний апо́столе Христо́во Фомо́! Єгда́ на коне́ць віко́в к челові́ком прише́дий Бог ізбра́ тя в ученики́ Своя́ і даде́ ті власть боля́щия ісціля́ти, прокаже́нния очища́ти, ме́ртвия воскреша́ти, бі́си ізгоня́ти, тогда́ не сих ра́ди, но найпа́че любо́вію приліпи́лся єси́ ко Христу́, жела́нієм вожделі́в да́же до сме́рти слі́довати по Нем. Сего́ ра́ди, а́ще попуще́нієм Боже́ственним і не зрел єси́ со іни́ми ученики́ воскре́сшаго Спа́са, а́ще і отре́клся єси́ ві́ровати сему́, до́ндеже вложи́ши перст свой в я́зви гвозди́нния і вложи́ши ру́ку свою́ в ре́бра Єго́, оба́че іспо́лни Госпо́дь проше́ніє се́рдця твоєго́ і непрело́жно па́ки ві́ру твою́ утверди́. Ті́мже мо́лим тя: отве́рзи нам о́чі ві́ри, да плотськи́м неви́димая яв'я́ться нам; пода́ждь нам наде́жду на снисхожде́ніє Бо́жиє, да отча́яніє гріхо́вноє не пожре́ть ни; откри́й нам блаже́нство любве́, я́же кріпка́ єсть, я́ко смерть, і єди́на возмога́єть над то́ю, да порабо́тавше Христу́ на землі́, воздви́гнем і ми себі́ кро́ви Небе́сния і с тобо́ю і всі́ми святи́ми просла́вим пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Учени́ко Христо́в бив, Боже́ственнаго собо́ра апо́стольськаго соприча́стник, / неві́рствієм бо Христо́во Воскресе́ніє ізвісти́в, / і того́ пречи́стую страсть осяза́нієм уві́рив, Фомо́ всехва́льне, // і ни́ні нам проси́ ми́ра і ве́лія ми́лости."]},{"h":"Кондак, глас 4","ps":["Прему́дрости благода́ті іспо́лнен / Христо́в апо́стол, і служи́тель і́стинний, / в покая́нії вопія́ше Тебі́: // Ти мой єси́ Бог же і Госпо́дь."]},{"h":"Величання","ps":["Велича́єм тя, апо́столе Христо́во Фомо́, і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ во благові́стії Христо́ві."]}],"notes":[]},{"u":"Акафіст великомученику Артемію Антіохійському","e":"Akathist to the Great Martyr Artemius of Antioch","secs":[{"h":"Кондак 1","ps":["Взбра́нному воєво́ді і августа́лію страни́ Єги́петськия, царе́м земни́м че́стію превознесе́нному, посліди́ же от Юлія́на злочести́ваго му́чимому і во главу́ усече́нному, я́ко зі́льні страда́вшему і победи́тельне вся претерпі́вшему, от Бо́га же прия́вшему нетлі́ніє і благода́ть чудотворе́нія, днесь ві́рнії в похва́льная возопії́м:","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Ікос 1","ps":["Антіохи́йстії лю́діє диви́шася святі́й ре́вности твоє́й о і́мені Христо́ві, сла́вне Арте́міє, не терп'я́ бо зрі́ти муче́нія святи́х і хули́ сли́шати на Го́спода, Юлія́ном ізрига́ємия; а́ще і честь єму́ возда́ти от Александрі́ї прише́л, оба́че і обличи́ти того́ не устраши́лся єси́. Ті́мже, і чи́на своєго́ во́їнськаго ізве́рженний за дерзнове́ніє своє́, осужде́ніє на ра́ни і смерть прия́л єси́. Ми же ни́ні, а́ки обстоя́ще ті на позо́рищі му́чимому, вопіє́м ті си́це:","Ра́дуйся, безсла́віє і муче́ніє от Юлія́на претерпі́вий;","ра́дуйся, в сла́ву і осія́ніє от Бо́га облече́нний.","Ра́дуйся, лю́тая страда́нія под'я́вий;","ра́дуйся, вели́чіє ві́ри показа́вий.","Ра́дуйся, блиста́яйся сла́вою терпі́нія;","ра́дуйся, крі́посте на́ша в ско́рбіх і ізнеможе́нії.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 2","ps":["Бу́ди ві́рен царю́, преща́ше святи́й Арте́мій нечести́вому Юлія́ну: «Я́ко су́єтни твоя́ начина́нія і не́мощна єсть го́рдость твоя́ істреби́ти христия́ни: отне́ліже бо при́йде Христо́с, і водрузи́ся Крест, і воздви́жеся на нем Госпо́дь - паде́ злочести́вих горди́ня і попра́на бисть лука́ваго крі́пость, Христо́ва же непобіди́ма і непреодоле́нна єсть си́ла, є́юже огражда́ющеся, возмо́жем устоя́ти проти́ву ко́зней вра́жиїх, побі́дні вопія́ Бо́гу: Аллилу́я»."]},{"h":"Ікос 2","ps":["Во́їнствуя за вели́каго царя́ Константи́на, крі́пкою си́лою кре́стною побіжда́л єси́ враги́, оружебо́рче Арте́міє; то́ю же си́лою і мучи́теля своєго́ Юлія́на одолі́л єси́. Виді́нієм бо креста́ овогда́ на небесі́ во ві́рі Христо́вій утверди́лся, лесть і́дольськую і по́чести во́їнськаго зва́нія презрі́в, за христия́ни пред отсту́пником му́жественно ра́товал єси́, і во́їнов началовождя́ ві́ри на́шея, Го́спода Христа́, себі́ наре́к, живо́т свой за Того́ до́блественно положи́л єси́. Ті́мже і притяжа́л єси́ себе́ от нас зва́нія такова́я:","Ра́дуйся, зна́мена і́дольськая ке́саря–отсту́пника отри́нувий;","ра́дуйся, зна́менію Креста́ послі́довавий.","Ра́дуйся, і ни́ні си́ли борю́щихся под стя́гом ві́ри укріпля́яй;","ра́дуйся, упова́ніє ізнемога́ющих утвержда́яй.","Ра́дуйся, до́брий Христо́в ору́жниче;","ра́дуйся, святи́я ві́ри тве́рдий защи́тниче.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 3","ps":["«Го́споди, дале́че єсьм от терпі́нія і незло́бія Твоєго́»,– вопія́л єси́, свя́те Арте́міє, пе́рвая муче́нія претерпі́в,– «Ти бо, Го́споди, за мене́, грі́шнійшаго, по всему́ тілесі́ содробле́н бил єси́ ра́нами, от ног до глави́ не бі в Тебі́ ці́лости. Молю́ у́бо Тя, Влади́ко, я́ко Твої́ми страда́ньми вінча́л м'я єси́, да і соверши́ши тече́ніє моє́ во іспові́данії Тебі́ с пі́снію: Аллилу́я»."]},{"h":"Ікос 3","ps":["Даде́ злочести́вий цар повелі́ніє оружено́сцем свої́м восхи́тити тя, сла́внаго во́їнськаго вождя́, Арте́міє, і сано́вний по́яс твой от'є́мше, і ри́зи совле́кше, на́га істяза́ти. Они́ же, связа́вше ру́ці і но́зі твої́, растяго́ша ті́ло твоє́ на че́тверо і бія́ху воло́вими жи́лами по хребту́ і чре́ву толи́ко, я́ко оскуді́ти си́лам їх. Ти же а́ки нечу́вствен пребива́л єси́, я́ко всім, о́крест стоя́щим, і самому́ Юлія́ну чуді́теся зіло́. Прийми́ у́бо і от нас похва́льная удивле́нія сицева́я:","Ра́дуйся, во ві́рі непобіди́мий;","ра́дуйся, в упова́нії непреодоли́мий.","Ра́дуйся, на ка́мені терпі́нія но́зі свої́ поста́вивий;","ра́дуйся, му́жественні стопи́ своя́ іспра́вивий.","Ра́дуйся, ра́довавийся в страда́ніях;","ра́дуйся, просла́вленний в поруга́ніях.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 4","ps":["Єгда́ святі́ї іспові́дниці Євге́ній і Мака́рій му́чими бя́ху, тогда́ і ти, блаже́нне Арте́міє, ре́вностію по Бо́зі дви́жим, моли́тву твори́л єси́, да не пока́жеть Бог тебі́ не то́чію недосто́йна страда́льчеськаго начина́нія, но да іспра́виться пред Ним і твоя́ ісхо́дная піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Жи́лами воло́вими біє́мий і по земле́ протяза́ємий нічто́же малоду́шествовал єси́, но ра́дуяся і веселя́ся, страда́ньми Христо́вими просвіща́єм, по́двиг му́ченичества до конця́ соверши́л єси́ до́брі. Ті́мже і досто́їн яви́лся єси́ ублаже́нія сицева́го:","Ра́дуйся, скуде́льний сосу́д пло́ті своєя́ сокруши́вий;","ра́дуйся, світ ві́ри і си́лу му́жества із него́ яви́вий.","Ра́дуйся, в єго́же не́мощі си́ла Госпо́дня соверши́ся;","ра́дуйся, єго́же терпі́нію мучи́тель почуди́ся.","Ра́дуйся, я́ко Бог прия́т твою́ же́ртву муче́нія;","ра́дуйся, я́ко Благи́й даде́ тебі́ жре́бій спасе́нія.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 5","ps":["«За Мене́ стра́ждеши, Арте́міє, дерза́й і ра́дуйся», - глаго́ла Христо́с, яви́вся свято́му в темни́ці, - «Со Мно́ю бу́деши во Ца́рствії Моє́м». Сія́ сли́шав му́ченик, а́біє от ран ісцілі́, і душе́ю іспо́лнився Боже́ственнаго утіше́нія, пребива́ше в темни́ці, благословля́я Бо́га і поя́ Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["І гла́дом, і жа́ждею му́чиша тя в темни́ці, блаже́нне Арте́міє. Ти же, на щедро́ти Преблага́го Го́спода себі́ возве́рг, єди́наго проси́л єси́, да і са́мую ду́шу твою́, я́ко же́ртву живу́ю при́йметь Влади́ка Христо́с от тебе́ с єще́ оста́вшеюся кро́вію твоє́ю. І не вотще́ бисть раче́ніє твоє́: запові́да бо Госпо́дь А́нгелом Свої́м в темни́ці пита́ти і сохраня́ти тя, пото́м же і Сам яви́ся, укріпля́я тебі́, нас же возглаша́ти тебі́ науча́я:","Ра́дуйся, от руки́ А́нгел в темни́ці пита́вийся;","ра́дуйся, хлі́бом живо́тним с небесе́ укрепля́вийся.","Ра́дуйся, от ран Госпо́днім посіще́нієм во у́зах ісцели́вийся;","ра́дуйся, явле́нієм Христо́вим утіше́нія іспо́лнивийся.","Ра́дуйся, Го́сподем в темни́ці обра́дованний;","ра́дуйся, восше́дий к Нему́ прия́ти віне́ць сла́ви тебі́ угото́ванний.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 6","ps":["«Коль мно́га суть Влади́ки моєго́ страда́нія і что бо́ліє Єго́ претерпі́х аз, недосто́йний», - вопія́ше блаже́нний Арте́мій, - «Той ко Кресту́ пригвожде́н бисть гріха́ ра́ди моєго́, Сам не позна́в гріха́, ніже́ лесть во усті́х соді́ла. Ра́дуюся і веселю́ся просвіща́ємий Го́спода моєго́ страда́ньми, я́же облегчева́ють мі болі́зні моя́». Та́ко святи́й в себі́ бесі́дуя, чрез всю нощ ку́пно со страда́льцями Євге́нієм і Мака́рієм воспіва́ше Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Люті́йшим му́кам предаде́ тя, страда́льче Арте́міє, нечести́вий цар, єгда́ со студо́м от Аполло́на Дафні́йськаго возврати́ся і от тебе́ посмія́ніє і прорече́ніє поги́белі своєя́ сли́шав, зі́льною я́ростію распали́ся. Ті́мже і ми за о́ния страда́нія мно́жайшими ликостоя́нії ублажа́єм тя си́це:","Ра́дуйся, я́ко тобо́ю Бог, ди́вний во святи́х Свої́х, язи́ком яви́ся;","ра́дуйся, я́ко тобо́ю сладча́йшеє і́м'я Христо́во просла́вися.","Ра́дуйся, я́рости мучи́телеви не устраши́вийся;","ра́дуйся, в Христо́вім упова́нії над і́доли посмея́вийся.","Ра́дуйся, в ду́сі проро́честем бу́дущих предзри́телю;","ра́дуйся, Ду́ха Госпо́дня до́блій носи́телю.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 7","ps":["Мно́га досажде́нія творя́ше нечести́вий Юлія́н христия́ном, лжу́ще на ня, я́ко сожго́ша храм Аполло́на Дафні́йськаго. Єгда́ же сей лжець пред Арте́мієм мно́жайшия преще́нія ізрека́ше на христия́ни, святи́й Арте́мій отвіща́: «Богопу́стний гнів і огнь с небесе́ пояде́ і́дола твоєго́ і ка́пище єго́ сожже́; посмева́юся безу́мію ва́шему, я́ко слу́жіте безду́шному бо́гу, утеша́юся о паде́нії єго́ і ра́дуюся о всіх сих, я́же Христо́с чудоді́йствова, Єму́же досто́їть пі́ти велегла́сно: Аллилу́я»."]},{"h":"Ікос 7","ps":["Не терп'я́ сли́шати пра́ведних слов твої́х, свя́те Арте́міє, беззако́нний Юлія́н, разгні́вався зіло́, повелі́ каменосі́чцем разсіщи́ вели́кий ка́мень, да посреді́ часте́й єго́ согнете́н бу́деши. І сему́ угото́ванному, па́дший ка́мень все ті́ло твоє́ сотре́, і вну́тренняя твоя́ распадо́шася, і сломи́шася вся чле́ни твоя́. І бі зрі́ти чу́до ве́ліє, я́ко в таково́м согнете́нії посреді́ ка́мней ти жив оста́ся. Ми же Бо́жієй си́лі, укрепля́вшей тя, удивля́яся, вопіє́м:","Ра́дуйся, гро́зде виногра́да Христо́ва в точи́лі істо́птанная;","ра́дуйся, же́ртво жива́я, Го́споду верху́ ка́мене кро́вію возлія́нная.","Ра́дуйся, му́чениче, єго́же все ті́ло а́ки дська согнете́ся;","ра́дуйся, скрижа́ле жива́я, на не́йже іспові́даніє ві́ри кро́вію написа́ся.","Ра́дуйся, кровми́ свої́ми, а́ки бре́нієм ка́меніє смеси́вий;","ра́дуйся, себі́ самаго́ жи́ва в созида́ніє Це́ркве Христо́ви положи́вий.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 8","ps":["О́чі твої́ от мук іскочи́ша, свя́те, і лице́ бі сотре́но, душа́ же єще́ бі держа́щися і язи́к до́брі віща́ющ, і́мже і в согнете́нії призва́л єси́ Бо́га, Помо́щника своєго́, і во упова́нії на Него́ взива́л єси́: Аллилу́я."]},{"h":"Ікос 8","ps":["Привиді́нієм почте́ тя цар, єгда́ узрі́ ви́дом стра́шна і єстество́ челові́чеськоє проісходя́ща; оба́че і увіща́ тебі́ єще́ поклони́тися і́долом, да поми́лують тя і поне́ я́же во а́ді му́кам не предадя́ть. Ти же, посмія́вся царю́, отвіща́л єси́: «Я́ко і́доли і са́мі огня́ не мо́гуть ізбіжа́ти, с ни́миже і ти, царю́, безконе́чному огню́ пре́дан бу́деши». За є́же, я́ко ху́льника, цар на смерть осуди́ тя. Ми же, сше́ствуя тебі́ на мі́сто усіче́нія, ув'яза́єм главу́ твою́ похва́льними вінці́ та́ко:","Ра́дуйся, страда́льче, посреді́ ка́меній согнете́нний;","ра́дуйся, іспові́дниче, в крі́пості ві́ри не одоле́нний.","Ра́дуйся, і́стину без стра́ха пред цари́ віща́вий;","ра́дуйся, за сіє́ посліди́ всіх злострада́ній усіче́ніє ме́чноє прия́вий.","Ра́дуйся, главу́ свою́ свяще́нную под меч самово́льне подклони́вий;","ра́дуйся, терпі́нієм свої́м глави́ неви́димих враго́в сокруши́вий.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 9","ps":["Ра́нами содробле́н бил єси́ по всему́ тілесі́, я́ко лю́дем на тя зрі́ти бі стра́шно: согнете́нний а́ки дська, ко́сті сокруше́нни і вся вну́тренняя іспадо́ша. Таково́є злострада́ніє за ма́лую болі́знь почита́л єси́, наді́яся у Го́спода, за Него́же страда́л єси́, імі́ти поко́й ві́чний, науча́я в злострада́нії не малоду́шествовати, но па́ки возсила́ти Бо́гу благода́рні: Аллилу́я."]},{"h":"Ікос 9","ps":["«Се я́зви Христо́ви на ті́лі твоє́м начерта́ни суть», - глаго́ла к себі́ святи́й, - «оста́лося у́бо, да і са́мую ду́шу за Христа́ отда́м с оста́вшеюся во мні кро́вію». І на щедро́ти Госпо́дні себі́ возве́рг, небоя́зненно Христа́ іспові́дал пред челові́ки, за Него́же і усіче́ніє с ра́достію прия́л єси́. Сего́ ра́ди, за превосходя́щую любо́в твою́ к Бо́гу, похваля́єм тя си́це:","Ра́дуйся, Христо́ва Єва́нгелія ско́рий послу́шателю;","ра́дуйся, вели́кия за́повіді Єго́ гото́вий ісполни́телю.","Ра́дуйся, крі́пкую любо́в ко Го́споду Христу́ показа́вий;","ра́дуйся, і ду́шу свою́ с кро́вію ра́достно за Того́ преда́вий.","Ра́дуйся, содробле́нієм свої́м на́ше разслабле́ніє укріпля́яй;","ра́дуйся, я́звами свої́ми на́ша болі́зні ісціля́яй.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 10","ps":["Тве́рдою ві́рою вооружи́вся, неі́стовство мучи́телево презрі́л єси́, і осужде́ніє на усіче́ніє ме́чноє с ра́дованієм прия́л єси́, і ві́домий на смерть, ше́ствовал єси́ весе́лими нога́ми, вопія́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Усіче́нієм глави́ по́двиг свой му́ченичеський запечатлі́вий, утверди́ моли́твами твої́ми і нас, глави́ своя́ под і́го Христо́во подклони́вших, чрез все житіє́ по́двигом до́брим подвиза́тися, люби́ти Го́спода у тебе́ поуча́тися, вопія́ тебі́ си́це:","Ра́дуйся, си́льне, на одолі́ніє мучи́телей меч ві́ри при бедрі́ препоя́савий;","ра́дуйся, шле́мом спасе́нія от Го́спода защище́нний.","Ра́дуйся, по́ясом сла́ви от Него́ до́брі украше́нний;","ра́дуйся, щито́м моли́тв свої́х всіх прибіга́ющих к тебі́ охраня́яй.","Ра́дуйся, за страда́льцев Госпо́дніх во всеору́жії ополча́яйся;","ра́дуйся, ше́ствующих у́зьким путе́м в Ца́рствіє Небе́сноє неукло́нно провожда́яй.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 11","ps":["Фія́л злострада́нія уготовля́яся до конця́ іспи́ти, на мі́сті усіче́нія преклони́вся до землі́, моли́твою к Бо́гу дух свой укріпля́л єси́. І сли́шав глас с не́ба глаго́лющ: «Вни́ди со святи́ми прия́ти воздая́ніє тебі́ угото́ванноє», - преклони́л єси́ главу́ под меч, с ра́достію вознося́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Хва́лим тя всі, страстоте́рпче святи́й, і почита́єм честна́я страда́нія твоя́, я́же па́че єстества́ челові́чеськаго претерпі́л єси́, і Ца́рствіє Небе́сноє притяжа́л єси́. Ті́мже воздвиза́ємся вопи́ти тебі́ та́ко:","Ра́дуйся, ізможде́нія і членоврежде́нія прия́вий;","ра́дуйся, висоту́ ду́ха в му́ках яви́вий.","Ра́дуйся, щито́м упова́нія себі́ огради́вий;","ра́дуйся, тве́рдостію своє́ю де́рзость мучи́телей істощи́вий.","Ра́дуйся, єго́же муче́нію А́нгели предстоя́ху со удивле́нієм;","ра́дуйся, єго́же страда́нія лю́діє почита́ють со умиле́нієм.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 12","ps":["Ціно́ю кро́ві твоєя́ притяжа́л єси́ Ца́рствіє Небе́сноє, великострада́льче Христо́в Арте́міє. Упра́ви і нас твої́м предста́тельством во оби́телі небе́сния, да, наслажда́яся с тобо́ю ча́сти пра́ведних, ви́ну сла́вим с тобо́ю Бо́га пі́снію: Аллилу́я."]},{"h":"Ікос 12","ps":["Черто́г небе́сний отве́рзе ті Страстополо́жник Христо́с і даде́ ті досто́йно віне́ць сла́ви: і ни́ні на небесі́х со А́нгельськими чи́ньми ра́дуєшися. Ті́мже і ми, благода́рнії лю́діє і любому́ченици, пі́сньми вопіє́м ті:","Ра́дуйся, воєво́до, ники́миже в му́жестві одоле́нний;","ра́дуйся, ратобо́рче за Христа́, в си́лі неоскуде́ємий.","Ра́дуйся, великострада́льче, му́ками твої́ми єстество́ челові́чеськоє удиви́вий;","ра́дуйся, несокруши́мость ду́ха в тіле́снім содробле́нії яви́вий.","Ра́дуйся, во упова́нії на Бо́га Жи́ва не усумне́вийся;","ра́дуйся, ча́сти пра́ведних на небесі́х наслажда́яйся.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 13","ps":["О пресла́вні великому́чениче Христо́в Арте́міє! Поє́м страда́нія твоя́, чтим до́блюю кончи́ну твою́, с усе́рдним моле́нієм к тебі́ притека́юще: укріпи́ і нас с терпі́нієм в по́двизі крестоноше́нія пребива́ти, іспита́нія і злострада́нія чрез все житіє́ до конця́ понести́ не унива́юще, но бо́дренне пребива́юще в пі́нії Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Антіохи́йстії лю́діє диви́шася святі́й ре́вности твоє́й о і́мені Христо́ві, сла́вне Арте́міє, не терп'я́ бо зрі́ти муче́нія святи́х і хули́ сли́шати на Го́спода, Юлія́ном ізрига́ємия; а́ще і честь єму́ возда́ти от Александрі́ї прише́л, оба́че і обличи́ти того́ не устраши́лся єси́. Ті́мже, і чи́на своєго́ во́їнськаго ізве́рженний за дерзнове́ніє своє́, осужде́ніє на ра́ни і смерть прия́л єси́. Ми же ни́ні, а́ки обстоя́ще ті на позо́рищі му́чимому, вопіє́м ті си́це:","Ра́дуйся, безсла́віє і муче́ніє от Юлія́на претерпі́вий;","ра́дуйся, в сла́ву і осія́ніє от Бо́га облече́нний.","Ра́дуйся, лю́тая страда́нія под'я́вий;","ра́дуйся, вели́чіє ві́ри показа́вий.","Ра́дуйся, блиста́яйся сла́вою терпі́нія;","ра́дуйся, крі́посте на́ша в ско́рбіх і ізнеможе́нії.","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Кондак 1","ps":["Взбра́нному воєво́ді і августа́лію страни́ Єги́петськия, царе́м земни́м че́стію превознесе́нному, посліди́ же от Юлія́на злочести́ваго му́чимому і во главу́ усече́нному, я́ко зі́льні страда́вшему і победи́тельне вся претерпі́вшему, от Бо́га же прия́вшему нетлі́ніє і благода́ть чудотворе́нія, днесь ві́рнії в похва́льная возопії́м:","Ра́дуйся, святи́й Арте́міє, пресла́вний Христо́во великому́чениче."]},{"h":"Молитва перша","ps":["Святи́й уго́дниче Бо́жий, Арте́міє пра́ведний! При́зри ми́лостивно на усе́рдную моли́тву нас, грі́шних (імена́), і твої́м благомо́щним предста́тельством проще́ніє согріше́ній на́ших у Го́спода іспроси́, преспі́яніє же во ві́рі і благоче́стії і от ко́зней дия́вольських огражде́ніє ісхода́тайствуй нам. Найпа́че же моли́ Го́спода, да сподо́бит всіх нас по христия́нськой кончи́ні Небе́сноє Ца́рствіє получи́ти, іді́же всі пра́веднії ку́пно с тобо́ю сла́в'ять Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в."]},{"h":"Молитва друга","ps":["Святи́й му́чениче Арте́міє! При́зри с небе́снаго черто́га на тре́бующих твоєя́ по́мощі і не отве́ргни проше́ній на́ших, но, я́ко при́сний благоді́тель і хода́тай наш, моли́ Христа́ Бо́га, да, человіколюби́в і многоми́лостив сий, сохрани́ть нас от вся́каго лю́таго обстоя́нія: от тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні. Да не осу́дить нас грі́шних по беззако́нієм на́шим, і да не во зло обрати́м блага́я, дару́ємая нам от Всеще́драго Бо́га, но во сла́ву свята́го і́мене Єго́ і в прославле́ніє крі́пкаго твоєго́ заступле́нія. Да моли́твами твої́ми дасть нам Госпо́дь мир по́мислов, воздержа́ніє от па́губних страсте́й і от вся́кия скве́рни і да укріпи́ть во всем ми́рі Свою́ Єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков, ю́же стяжа́л єсть честно́ю Своє́ю Кро́вію. Моли́ся прилі́жно, святи́й му́чениче, да благослови́ть Христо́с Бог держа́ву, да утверди́ть во святі́й Своє́й Правосла́вній Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да всі чле́ни єя́, чи́стії от суєму́дрія і суєві́рія, ду́хом і і́стиною покланя́ються Єму́ і усе́рдно пеку́ться о соблюде́нії Єго́ за́повідей, да ми всі в ми́рі і благоче́стії поживе́м в настоя́щем ві́ці і дости́гнем блаже́нния ві́чния жи́зні на небесі́, благода́тію Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О всехва́льний великому́чениче Арте́міє, Госпо́день во́їнственниче і всім нам крі́пкий побо́рниче! Скор бу́ди предста́тельством твої́м у Человіколю́бця Христа́, да дасть правові́рним лю́дем, почита́ющим тя і на поклоне́ніє моще́м твої́м приходя́щим, ми́лость і благи́х проше́ній ско́роє ісполне́ніє. Предстоя́й Престо́лу Бо́жию в ли́ці му́ченик, помина́й всіх нас, біда́ми, напа́стьми і скорбми́ обстої́мих, і в житії́ сем мно́го стра́ждущих: да твоє́ю по́мощію і крі́пким побо́рством преста́нуть приходя́щая на нас зла́я. Ми же, твої́ми злострада́ньми назида́єми, си́лою благода́ті Христо́ви чрез тебі́ ісполня́ємі, в терпі́нії крестоноше́нія жи́ти начне́м, во є́же Го́споду покая́нієм благоугоди́ти і неізрече́нная блага́я наслі́довати, я́же угото́вана лю́б'ящим Бо́га і прославля́ющим свято́є і́м'я Єго́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І́стинною бо Христо́вою ві́рою / утве́рждься, страстоте́рпче, / мучи́теля злочести́ва царя́ / побіди́л єси́ со і́дольським того́ возноше́нієм. / Тім от Царя́ Вели́каго, ві́чно ца́рствующаго, / пресві́тлим вінце́м побі́дним одаре́н бисть, / вся ісціля́яй боля́щия і призива́ющия тя, Арте́міє вели́кий, / моли́ Христа́ Бо́га // спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Благочести́ваго і вінцено́снаго му́ченика, / на враги́ побі́ди взе́мшаго одолі́ніє, / соше́дшеся, досто́йно пі́сньми восхва́лим Арте́мія, / превели́каго в му́чениціх, / чуде́с же да́теля пребога́таго, // мо́литься бо Го́споду о всіх нас."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Арте́міє, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст преподобному Саві, ігумену Сторожевському, Звенигородському","e":"Akathist to our Venerable Father Sabbas, Abbot of Storozhi near Zvenigorod","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди і Го́спода во́їнств небе́сних, преподо́бне о́тче наш Са́вво, си́лою креста́ Госпо́дня побіди́вий напа́сти, я́же от дия́вола, ми́ра і пло́ті, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких іскуше́ній, бід і наві́тов вра́жиїх моли́твами твої́ми сохраня́й нас, похва́льная с любо́вію тебі́ воспіва́ющих:","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́ на землі́, преподо́бне Са́вво, от ю́ности бо возлюби́в Бо́га, равноа́нгельному поревнова́л єси́ житію́ учи́теля твоєго́, преблаже́ннаго Се́ргия, і послужи́в Го́сподеві в пра́вді і преподо́бії во вся дні живота́ своєго́, по ісхо́ді нетлі́нієм тілесе́ сія́єши. Всі у́бо благогові́йно чту́ще тя, воспіва́єм си́це:","Ра́дуйся, і́стинний свята́го учи́теля твоєго́ ревни́телю.","Ра́дуйся, земни́й А́нгеле і небе́сний челові́че.","Ра́дуйся, ві́рний слуго́ Госпо́день.","Ра́дуйся, усе́рдний чистоти́ і воздержа́нія храни́телю.","Ра́дуйся, зерца́ло ві́ри благочести́вия.","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, пустинножи́телей красото́.","Ра́дуйся, і́ноков наста́вниче.","Ра́дуйся, мно́гим ко спасе́нію путеводи́телю.","Ра́дуйся, ско́рий помо́щниче притекающим к тебі́ с ві́рою.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 2","ps":["Ви́дя, я́ко в ми́рі сем вся́чеськая суєта́ і тлі́ніє, потща́лся єси́ ті́сним і приско́рбним путе́м тече́ніє жи́зні сея́ соверши́ти; всели́вся во оби́телі преподо́бнаго Се́ргия, і от него́ прия́в а́нгельський о́браз, поревнова́л єси́ богому́дрому єго́ смире́нію і трудолю́бію, і ку́пно с ним день і нощ воспіва́л єси́ Спаси́телю, всіх Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум і се́рдце покори́в Христу́ Спаси́телю, глаго́лющу: \"І́же хо́щеть по Мні іти́, да отве́ржеться себе́, і во́зьметь крест свой, і по Мні гряде́ть\",- невозвра́тно отврати́л єси́ лице́ своє́ от ми́ра сего́, я́ко от Вавило́на гріхо́внаго, і презрі́во вся кра́сная і блага́я єго́, водвори́лся єси́ в пусти́ні, ча́я Бо́га, спаса́ющаго воітелей Свої́х. Ни́ні же предстої́ши Престо́лу Бо́жию, наслажда́яся небе́сних благ, і ве́ліє дерзнове́ніє імі́я ко Го́споду, не забу́ди нас, к ра́ці моще́й твої́х усе́рдно притека́ющих і восхваля́ющих тя:","Ра́дуйся, жите́йських сує́ть і мирськи́х собла́знов ізбежавий.","Ра́дуйся, і́ночеськоє безстра́стіє і безмо́лвіє стяжа́вий.","Ра́дуйся, вся блага́я землі́, Небе́снаго ра́ди Ца́рствія, за уме́ти вміни́вий.","Ра́дуйся, равноа́нгельноє житіє́ до конця́ возлюби́вий.","Ра́дуйся, возненави́дівий ми́ра сего́ гріхо́вную сла́дость.","Ра́дуйся, восприє́мий обітова́ніє непрестаю́щия жи́зні.","Ра́дуйся, облече́нний сла́вою Небе́снаго Ца́рствія.","Ра́дуйся, сокро́вище некра́домоє і нетлі́нноє обріти́й.","Ра́дуйся, о Це́ркві Христо́вой, на землі́ во́їнствующей, моли́твенниче небе́сний.","Ра́дуйся, о всіх ві́рних, на поклоне́ніє к тебі́ притека́ющих, предста́телю.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 3","ps":["Си́лою, ізлія́нною на тя сви́ше, возше́д на висоту́ доброді́телей, посто́м і бді́нієм, моли́твами і цілому́дрієм, я́ко многоці́нним вінце́м благоустроє́нія і́ночеськаго, повсю́ду просія́л єси́: сего́ ра́ди всі вели́ка і пресла́вна тя почита́ху. Ти же, бі́гая сла́ви от челові́к, пребива́л єси́ я́ко єди́н от прости́х, тружда́яся па́че всіх і поя́ хвалу́ єди́ному, в Тро́йці сла́вимому, Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ду́шу, смиренному́дрія іспо́лнену, а́ще і устрашался бре́мене нача́льства, оба́че не преслу́шав во́лі Бо́жия, прия́л єси́ порученноє тебі́ ста́до Христо́во і до́брі в пасенії єго́ преби́л єси́. Ни́ні же, ви́ну предстоя́ Престо́лу Бо́жию, благоспоспешествуй моли́твами твої́ми всім, взивающим к тебі́:","Ра́дуйся, безпрекословний во́лі учи́теля твоєго́ ісполни́телю.","Ра́дуйся, до́брий стада́ Христо́ва наста́вниче.","Ра́дуйся, возлю́бленний па́че мно́гих ізбра́нником Бо́жиїм Се́ргиєм, от него́же не утаї́ся святи́ня твоя́.","Ра́дуйся, благово́нний кри́не вертогра́да церко́внаго.","Ра́дуйся, сві́тлий сосу́де Боже́ственния благода́ті.","Ра́дуйся, світи́льниче, не сокривийся под спу́дом, но на сві́щниці поста́вленний.","Ра́дуйся, честно́є Свята́го Ду́ха селе́ніє.","Ра́дуйся, преподо́бних сві́тлоє украше́ніє.","Ра́дуйся, і́ноков в по́двизіх по́стничеських укріпля́яй.","Ра́дуйся, заблуждшим путь спасе́нія показу́яй.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й і іскуше́ній вра́жиїх, препобіжда́я посто́м, бді́нієм і моли́твами, утоли́л єси́ до конця́. Ни́ні у́бо причаща́яся сла́ви небе́сния со всі́ми святи́ми, предстої́ши Царю́ сла́ви і поє́ши ку́пно с ни́ми: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще бли́жнії і да́льнії богоуго́дноє твоє́ житіє́, стека́хуся от окре́стних стран к тебі́, по́льзи ра́ди: ти же всіх любе́зно приє́мля, согріва́л єси́ се́рдця їх Боже́ственною любо́вію. К тебі́ у́бо і ми припа́дающе, мо́лим: наста́ви ни, я́ко оте́ць ча́да своя́, на стезі́ спасе́нія і не забу́ди взива́ющих к тебі́:","Ра́дуйся, всім прибегающим к тебі́ наста́вниче предо́брий.","Ра́дуйся, іщущим успокоє́нія со́вісти собесі́дниче прети́хий.","Ра́дуйся, унива́ющих душ уті́шителю пресла́дкий.","Ра́дуйся, ка́ющихся со умиле́нієм хода́таю преусердний.","Ра́дуйся, заблужда́ющих ісправи́телю прекроткий.","Ра́дуйся, беззако́нних обличи́телю незло́бивий.","Ра́дуйся, к воздержа́нію і цілому́дрію путеводи́телю неосла́бний.","Ра́дуйся, борющимся со страстьми́ помо́щниче неутоми́мий.","Ра́дуйся, пра́ваго путі́ ві́ри і благоче́стія указа́телю нело́жний.","Ра́дуйся, молящимся тебі́ от гні́ва Бо́жия защи́тниче неотсту́пний.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, преподо́бне о́тче Са́вво, от мра́ка гріхо́внаго хотя́щим прейти́ к Со́лнцю пра́вди, я́сно путь показу́ющая. Ті́мже мо́лим тя: просвіти́ і на́ша се́рдця, страстьми́ жите́йськими омраче́нная, і спосо́бствуй нам досто́йно воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя благові́рний князь Гео́ргій смиренному́дріє твоє́, я́ко уклони́лся єси́ от нача́льственния вла́сті во оби́телі учи́теля твоєго́, устремляяся к пусти́нному безмо́лвію, той умоли́ тя, да всели́шися на гора́х, глаго́лемих Сторо́жи. Ти же, ізволя́я благо́є послуша́ніє яви́ти благо́му жела́нію, і оби́тель і́ночеськую зді соста́вити хотя́, рекл єси́ со проро́ком: \"Се поко́й мой, зді вселю́ся, я́ко ізво́лих і\". І ско́ро на мі́сті сем храм Пресвяти́я Богоро́диці созда́ся, в не́мже ни́ні нетлі́нієм моще́й твої́х благоуха́єши, і немо́лчно ко Го́споду вопіє́ши о возглаша́ющих к тебі́ сицева́я:","Ра́дуйся, го́рлице пустиннолю́бная і добровидная.","Ра́дуйся, пусти́ні до́броє прозябе́ніє.","Ра́дуйся, цві́те присноцвіту́щий.","Ра́дуйся, смиренному́дрієм і вся́кими доброді́тельми страну́ сію́ облагоуха́вший.","Ра́дуйся, благополезно і му́дро проше́ніє кня́зя соверши́вий.","Ра́дуйся, це́рков прекра́сну зді во сла́ву Рождества́ Богоро́диці сооруди́вий.","Ра́дуйся, пусти́ню во оби́тель і́ночества претвори́вий.","Ра́дуйся, ста́ду твоєму́ ві́рний наста́вниче.","Ра́дуйся, всім притекающим к тебі́ мир і благослове́ніє от Го́спода моли́твами твої́ми низводящий.","Ра́дуйся, о всіх граді́х і ве́сіх украї́нських моли́твенниче неусипа́ющий.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 6","ps":["Про́повіді Єва́нгельськия послу́шав: \"Не пеци́теся душе́ю ва́шею, что я́сте, іли́ что піє́те; ні ті́лом ва́шим, во что облече́теся\",- упраздни́л єси́ се́рдце твоє́ от жите́йських забот, пита́яся би́лієм пусти́нним і малоценния ри́зи нося́. Сего́ ра́ди нетлі́нія оде́ждою оді́ялся єси́ по преставле́нії твоє́м, ю́же от Христа́ Бо́га получи́ти і нам іспроси́, вопію́щим Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко богосві́тлоє світи́ло, во страні́ Украї́нській, всеблаже́нне о́тче Са́вво, озаря́я нас луча́ми доброді́телей і чуде́с твої́х, ті́мже вопіє́м ті:","Ра́дуйся, дарованіями Свята́го Ду́ха сія́ющий члене Це́ркве Христо́ви;","Ра́дуйся, преізобилующий і́стинним к Бо́гу умиле́нієм.","Ра́дуйся, подража́телю преподо́бних в соверше́нном терпі́нії.","Ра́дуйся, по́двигов і́ночеських ревни́телю.","Ра́дуйся, стра́сті гріхо́вния, си́лою благода́ті, в себі́ умертви́вий.","Ра́дуйся, нищети́ і нестяжа́нія о́бразе.","Ра́дуйся, сві́тлоє святи́ні зерца́ло.","Ра́дуйся, всіх доброді́телей рачи́телю.","Ра́дуйся, немощни́х ціле́бниче.","Ра́дуйся, же́зле, па́дающих подкрепляющий.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 7","ps":["Хотя́щу благові́рному кня́зю Гео́ргію воїнствовати на супоста́ти, благослове́ніє препода́л єси́, о́тче, на одолі́ніє, глаго́ля проро́чеськи: \"Ізи́ди, благові́рний кня́же! Госпо́дь ті помо́жеть, і враго́в твої́х одолі́єши, і благода́тію Бо́жиєю здрав возврати́шися в оте́чество твоє́!\",- є́же і бисть, по глаго́лу твоєму́. Он у́бо, возврати́вся от бра́ні с побі́дою і сла́вою, і мно́гими дарми́ снабдіва́я оби́тель твою́, воспіва́ше благода́рственно ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий подража́тель дре́вніх ратоборцев на стра́сті плотські́я яви́лся єси́, о́тче Са́вво: от ю́ности бо ум твой впери́в к Бо́гу, я́ко столп ві́ри непоколеби́мий, да́же до ста́рости масти́тия преби́л єси́ в распинанії пло́ті своєя́ со страстьми́ і похотьми́. Сего́ ра́ди не можа́ху си́ли бісо́вськия запинати нога́ма твої́ма, ніже́ успеваху устраша́ти тя іздале́ча, от ї́хже наві́тов і напа́стей соблюди́ неврежде́нних і нас, торже́ственно воспіва́ющих тебі́:","Ра́дуйся, ли́ку дре́вніх по́стников сопричтенний.","Ра́дуйся, всено́щними моли́твами і бді́нієм всю пре́лесть бісо́вськую посрами́вий.","Ра́дуйся, чистоти́ і воздержа́нія храни́телю.","Ра́дуйся, страсте́й душе́вних і тіле́сних побіди́телю.","Ра́дуйся, во́їне Христо́в неустраши́мий.","Ра́дуйся, обдержимим бісо́вською си́лою наде́жний врачу́.","Ра́дуйся, надме́нних мудрова́нієм пло́ті к покоренію глаго́лам Бо́жиїм приводя́й.","Ра́дуйся, всім напа́ствуємим от ду́ха льсти духо́вноє зрі́ніє і трезві́ніє подава́яй.","Ра́дуйся, ду́ха вражди́ і любонача́лія от притека́ющих к тебі́ прогоня́яй.","Ра́дуйся, я́ко хода́тайством твої́м даро́в Свята́го Ду́ха, во воїнствованії Христо́вом укрепляющих, сподобля́ємся.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до сотвори́л єси́, преди́вний о́тче Са́вво, єгда́ нечести́вії хотя́ху расхи́тити достоя́ніє це́ркве твоєя́. Они́, я́ко та́тіє, устремля́хуся око́нцем, є́же бі у гро́ба твоєго́: зді же ве́лія гора́ показа́ся їм, на ню́же взи́ти ність мо́щно. Со студо́м у́бо возвра́щшеся отсю́ду, посліди́ же раска́явшеся, с во́плем і слеза́ми, гріх свой іспові́даша пред всі́ми, і ско́ро путь непра́вди оста́вльше, в покая́нії про́чеє пожи́ша, с ві́рою вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ в Бо́зі, єще́ сий на землі́, в по́двизіх і́ночеськаго житія́: предстоя́щу бо ті пред лице́м Госпо́днім на Боже́ственной службе, зри́мо бива́ше воспламененіє чу́дноє в ли́ці твоє́м от моли́твеннаго в ду́сі горі́нія к Бо́гу. Овогда́ же в толи́ком бі умиле́нії душа́ твоя́, я́ко істочатися потокам сле́зним от оче́с твої́х неудержи́мо, ї́хже ра́ди єдинонра́вна тя зря́ху би́ти со проро́ком, глаго́лющим: \"Би́ша сле́зи моя́ мні хліб день і нощ\". Оба́че, ве́ліє стяжа́в дерзнове́ніє к Бо́гу, не забу́ди і нас, со слеза́ми печа́лі о грісі́х свої́х к твоєму́ заступле́нію притека́ющих і вопію́щих к тебі́:","Ра́дуйся, огне́м Боже́ственния любве́ ве́тхаго челові́ка в себі́ попали́вий.","Ра́дуйся, во пло́ті, а́ки безпло́тен, на землі́ пожи́вий.","Ра́дуйся, живи́ми і спаси́тельними слеза́ми огнь по́хоті угаси́вий.","Ра́дуйся, го́рнія ра́дости і блаже́нства а́нгельськаго соприча́стниче.","Ра́дуйся, за премно́гую любо́в твою́ к Бо́гу Отцю́ сла́вою і че́стію препросла́вленний.","Ра́дуйся, за глубо́коє смире́ніє твоє́ от Христа́, Си́на Бо́жия, вінце́м нетлі́нія увінча́нний.","Ра́дуйся, за чистоту́ і безстра́стіє а́нгельськоє от Пресвята́го Ду́ха осія́нний.","Ра́дуйся, пречестна́я оби́теле Святи́я Тро́йці.","Ра́дуйся, Бо́жия Ма́тере служи́телю ві́рний і неусипа́яй.","Ра́дуйся, в хра́мі Єя́ го́ре возносивийся ду́хом, і ни́ні ті́лом па́ки пребива́яй.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 9","ps":["Вся́кия біди́ і ско́рби ізба́ви нас, преподо́бне о́тче Са́вво, твої́ми те́плими к Бо́гу моли́твами, і іспроси́ нам вся, ко вре́менной і ві́чной жи́зні потре́бная, да сподо́бимся го́рняго Ієрусали́ма дости́гнути і ку́пно с тобо́ю воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії недоумі́ють досто́йно восхвали́ти тя, богому́дре Са́вво: кто бо дово́лен разумі́ти вся боре́нія твоя́ с миродержи́тели тьми ві́ка сего́? Іли́ кто ізочте́ть труди́, болі́зні і по́двиги твоя́, в ни́хже пустиннолюбноє житіє́ соверша́л єси́? Оба́че ми, любо́вію твоє́ю побіжда́єми, благода́рні тебі́ зове́м:","Ра́дуйся, зако́на Бо́жия ісполни́телю всеусе́рдний.","Ра́дуйся, чистото́ю і цілому́дрієм многоці́ннаго би́сера честні́йший.","Ра́дуйся, в терпі́нії і боре́нії проти́ву пло́ті адама́нта тверді́йший.","Ра́дуйся, смиренному́дрієм і кро́тостію па́че сла́вних землі́ просла́вленний.","Ра́дуйся, борющимся со страстьми́ і похотьми́ помо́щниче непобіди́мий.","Ра́дуйся, в труді́х, бді́нії і воздержа́нії вели́ким по́стником подража́телю ревностнейший.","Ра́дуйся, в духо́вной му́дрости наста́вниче благоїскуснейший.","Ра́дуйся, по́двигов і́ночеських показа́телю рачительнейший.","Ра́дуйся, дру́гу Бо́жию, преподо́бному Се́ргію, єдинонра́вний.","Ра́дуйся, к ли́ку друго́в Бо́жиїх на Небеса́ пресели́вийся.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́ще ві́рнії от разли́чних напа́стей і бід ми́ра сего́, тебі́ те́плаго предста́теля і моли́твенника к Бо́гу предлага́єм: не тще́тну сотвори́ на́шу наде́жду на моли́тви твоя́, но хода́тайством твої́м ізба́ви нас от лю́тих бід, напа́стей, іскуше́ній і скорбе́й, да несмуще́нно, от ізби́тка се́рдця, глаго́лем всегда́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя тве́рду і моли́твенника ізря́дна стяжа́в, свята́я оби́тель твоя́ і всі страни́ Украї́нськия заступле́нієм твої́м хва́ляться. Ті́мже і ми грі́шнії, ко гро́бу твоєму́ прите́кше, я́ко ча́да отця́, мо́лим: заступи́ і сохрани́ нас от іскуше́ній і скорбе́й, бід і напа́стей, моли́твами твої́ми, да взива́єм ті ра́достно:","Ра́дуйся, благово́нний кри́не ра́йськаго вертогра́да.","Ра́дуйся, кипари́сі, ві́рних се́рдця благово́нієм услаждающий.","Ра́дуйся, дре́во благосінноли́ственноє, і́мже оби́тель твоя́ покрива́ється.","Ра́дуйся, неуси́пний моли́твенниче, жела́нія ві́рних во благи́х ісполня́яй.","Ра́дуйся, наде́ждо і оти́шіє в мо́рі житія́ сего́ пла́вающих.","Ра́дуйся, тве́рдоє огражде́ніє і прибі́жище усе́рдно Бо́гу рабо́тающих.","Ра́дуйся, неісчерпа́ємий істо́чниче ісціле́ній.","Ра́дуйся, струє́, напая́ющая і веселя́щая жа́ждущих пра́вди.","Ра́дуйся, я́ко в ско́рбіх жите́йських і обстоя́ніїх сподобля́ємся твоєго́ заступле́нія.","Ра́дуйся, всіх усе́рдно притека́ющих к тебі́ от іскуше́ній і бід ско́роє ізбавле́ніє.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, преблаже́нне о́тче Са́вво, і со дерзнове́нієм мо́лим: вознеси́ ко Го́споду о спасе́нії душ на́ших твою́ святу́ю моли́тву, да сподо́бимся ві́чно в ра́дості блаже́нній воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельними луча́ми блиста́єть житіє́ твоє́, о́тче наш Са́вво: вся́кия бо доброді́телі Єва́нгельськия явля́ється в тебі́ ісполне́ніє, ті́мже і глаго́лем:","Ра́дуйся, сугу́бия ра́ди нищети́ бога́тство небе́сноє обріти́й. Ра́дуйся, пла́чем і умиле́нія слеза́ми утіше́ніє ві́чноє прия́вий.","Ра́дуйся, алкавий і жаждавий пра́вди, ни́ні же насищаяйся ра́йським блаже́нством.","Ра́дуйся, ми́лостивим обіща́нноє воздая́ніє улучи́вий.","Ра́дуйся, чистото́ю се́рдця твоєго́ лицезрі́нія Бо́жия дости́гнувий.","Ра́дуйся, миротвореніями мно́гими в ли́ці сино́в Бо́жиїх би́ти сподо́бивийся.","Ра́дуйся, терпі́нієм пра́вди ра́ди в Ца́рство Небе́сноє водворивийся.","Ра́дуйся, о́бразом кро́тости, ти́хости і незло́бія поуче́ніє су́щим в озлобле́нії подава́яй.","Ра́дуйся, приме́ром братолю́бія, ко іска́нію не свої́х си, но я́же бли́жняго, і на́ша се́рдця утвержда́яй.","Ра́дуйся, всіх со стра́хом рабо́тающих Го́сподеві ра́досте.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 12","ps":["Благода́ть, да́нная ті от Бо́га, ціли́ти неду́ги душе́вния і тіле́сния, созива́єть ві́рних ко всечестни́м моще́м твої́м: при ни́хже, і ма́лоє моле́ніє принося́щим, ве́лія благода́ть от Бо́га подає́ться, ю́же приє́млюще, друг со друго́м ра́достно Бо́гу возглаша́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ве́лія твоя́, досточу́дне о́тче, по́двиги і труди́, ублажа́єм приснопа́м'ятноє успе́ніє твоє́: а́ще бо і преста́вился єси́ от нас, но жив сий і по сме́рті, не отступа́єши от нас ду́хом, оба́че і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́. К тебі́ у́бо припа́даєм, тебі́ мо́лимся і восхваля́єм тя си́це:","Ра́дуйся, во ві́рі і любві́ боже́ственной благогові́йно от ю́ности і благоче́стно до масти́тия ста́рости пожи́вий.","Ра́дуйся, многотру́дния і разнообразниє во і́ночестві по́двиги до́брі соверши́вий.","Ра́дуйся, я́ко соверше́ннаго освяще́нія от Ду́ха Свята́го іспо́лнен єси́.","Ра́дуйся, чу́дному учи́телю твоєму́ уподо́бивийся всеці́лою чистото́ю і свя́тостію.","Ра́дуйся, я́ко с богому́дрим Се́ргиєм на Небесі́х при́сно лику́єши.","Ра́дуйся, я́ко с ним ку́пно Бо́га о нас грі́шних умоля́єши.","Ра́дуйся, я́ко нетлі́нієм моще́й твої́х, а́ки трубо́ю, пропові́дується бу́дущеє всіх воскресе́ніє.","Ра́дуйся, страні́ сей і всему́ оте́честву на́шему многоці́нноє украше́ніє.","Ра́дуйся, я́ко тобо́ю мона́хов мно́жества в по́двизіх свої́х укріпле́ніє приє́млють.","Ра́дуйся, я́ко хода́тайством твої́м ві́рнії і в молвах жите́йських спаса́ються.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 13","ps":["О пресла́вний чудотво́рче і ско́рий засту́пниче наш, блаже́нне о́тче Са́вво! Ма́лоє сіє́ от нас приноше́ніє ни́ні приї́м, іспроси́ нам у Христа́ Бо́га утвержде́ніє во ві́рі і братолю́бії, є́же би́ти неврежде́нним от вся́ких іскуше́ній, бід і напа́стей, і во гряду́щем ві́ці мук ві́чних ізба́витися всім, вопію́щим Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́ на землі́, преподо́бне Са́вво, от ю́ности бо возлюби́в Бо́га, равноа́нгельному поревнова́л єси́ житію́ учи́теля твоєго́, преблаже́ннаго Се́ргия, і послужи́в Го́сподеві в пра́вді і преподо́бії во вся дні живота́ своєго́, по ісхо́ді нетлі́нієм тілесе́ сія́єши. Всі у́бо благогові́йно чту́ще тя, воспіва́єм си́це:","Ра́дуйся, і́стинний свята́го учи́теля твоєго́ ревни́телю.","Ра́дуйся, земни́й А́нгеле і небе́сний челові́че.","Ра́дуйся, ві́рний слуго́ Госпо́день.","Ра́дуйся, усе́рдний чистоти́ і воздержа́нія храни́телю.","Ра́дуйся, зерца́ло ві́ри благочести́вия.","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, пустинножи́телей красото́.","Ра́дуйся, і́ноков наста́вниче.","Ра́дуйся, мно́гим ко спасе́нію путеводи́телю.","Ра́дуйся, ско́рий помо́щниче притекающим к тебі́ с ві́рою.","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Кондак 1","ps":["Ізбра́нний от Воєво́ди і Го́спода во́їнств небе́сних, преподо́бне о́тче наш Са́вво, си́лою креста́ Госпо́дня побіди́вий напа́сти, я́же от дия́вола, ми́ра і пло́ті, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких іскуше́ній, бід і наві́тов вра́жиїх моли́твами твої́ми сохраня́й нас, похва́льная с любо́вію тебі́ воспіва́ющих:","Ра́дуйся, о́тче наш Са́вво, чудотво́рче пресла́вний."]},{"h":"Молитва","ps":["О пречестна́я і свяще́нная главо́! Небе́снаго Ієрусали́ма граждани́не, Пресвяти́я Тро́йці обита́лище, преподо́бне о́тче Са́вво! Ве́ліє імі́я дерзнове́ніє ко Всемилостивому́ Влади́ці, моли́ся о ста́ді огра́ди твоєя́ і о всіх по ду́ху ча́діх твої́х. Не премолчи́ за ни ко Го́споду і не пре́зри ві́рою і любо́вію чту́щих тя. Іспроси́ предста́тельством твої́м у Царя́ ца́рствующих мир Це́ркві, под зна́менієм креста́ во́їнствующей, Архієре́ом святи́тельства благолі́піє, монашествующим до́броє в по́двизіх тече́ніє; святі́й оби́телі сей, гра́ду сему́ і всім градо́м і страна́м охране́ніє; ми́ру безм'яте́жіє і мир, гла́да і па́губи ізбавле́ніє; ста́рим і немощни́м утіше́ніє і подкріпле́ніє, ю́ним і младенцям благо́є во ві́рі возраста́ніє, в Єва́нгельськом уче́нії тве́рдоє обуче́ніє, і в чистоті́ і цілому́дрії пребива́ніє; вдови́цям і сирота́м ми́лость і заступле́ніє, пліне́нним отра́ду і возвраще́ніє, боля́щим ісціле́ніє, малоду́шним успокоє́ніє, заблуждшим ісправле́ніє, согрешающим дух сокруше́нія, бедствующим благовре́менну по́мощ. Не посрами́ нас, к тебі́ с ві́рою притека́ющих, споспі́шествуй, я́ко чадолюби́вий оте́ць ча́дам, і нам понести́ і́го Христо́во во благоду́шії і терпі́нії, і всіх упра́ви в ми́рі і покая́нії сконча́ти живо́т свой непости́дно і пресели́тися со упова́нієм во оби́телі небе́сния. Іді́же ти, по труді́х і по́двизіх, ни́ні водворя́єшися со А́нгели і Святи́ми, зря і прославля́я Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Пусти́ні яви́лся єси́ до́броє прозябе́ніє, преподо́бне: / от ю́ности бо ізво́лил єси́ чи́стоє житіє́, / духо́вному твоєму́ учи́телю послі́дуя, / і Того́ уче́нієм ум к Небе́сним впери́в, / і ста́ду твоєму́ прему́др наста́вник показа́лся єси́; / тім і Христо́с, я́ко пресві́тла тя світи́льника, чудеси́ обогати́. // Са́вво о́тче наш, моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 8","ps":["От ю́ности боже́ственною распаля́єм ре́вностію, возлюби́л єси́ чи́стоє житіє́, презрі́в ми́ра сего́ кра́сная і су́єтная, послі́довал єси́ твоєму́ Богому́дрому учи́телю, преблаже́нному Се́ргію, в труді́ і бді́нії, в пості́ і по́двизі: на Сторо́жи я́влься безмо́лвія ра́ди і стра́жи духо́вния, недре́мленним на Боже́ственній стра́жі предстоя́нієм стяжа́л єси́ ум, зряй к Бо́гу, і де́монськия ко́зні і обстоя́нія прозира́яй: озаре́ніє Пресвята́го Ду́ха в себі́ восприє́м, я́ко звізда́ пресві́тлая возсія́л єси́ ві́рним. Ті́мже і прему́др і світоза́рен предстоя́тель і па́стир ста́ду твоєму́ яви́лся єси́, сві́том твої́м просвіща́яй і всіх, приходя́щих тебі́ ві́рою, о́тче наш Са́вво, і моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Госпо́днім жела́нієм распали́вся, / стра́сті плотські́я воздержа́нієм оттря́с, / Боже́ственнаго сві́та незаходи́моє світи́ло яви́лся єси́, / чуде́с луча́ми всіх просвіща́єши / притека́ющих к моще́м твої́м, // Са́вво, преподо́бне о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Са́вво, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Амвросію, єпископу Медіоланському","e":"Akathist to St Ambrose, Bishop of Milan","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго чудотво́рця і світи́льника це́ркве Медіола́нськия свята́го Амвро́сія, прийді́те, ві́рнії, почти́м по достоя́нію усе́рдною хвало́ю. Ти же, уго́дниче Бо́жий ми́лостивий, прийми́ с любо́вію сіє́ приноше́ніє на́ше, да зове́м ті:","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгельських сил і всея́ тва́рі Соді́тель, єще́ от младе́нчеських пеле́н твої́х предуказа́вий добро́ту душі́ твоєя́, свя́те Амвро́сіє, подаде́ тя, во во́зраст прише́дша, а́нгела це́ркві Медіола́нстей, па́стиря і учи́теля слове́сному ста́ду Своєму́, і сим научи́ нас зва́ти тебі́ си́це:","Ра́дуйся, от колибе́лі младе́нчеськия на служе́ніє Це́ркві ро́єм пчел предуказа́нний;","ра́дуйся, ко святи́тельству чрез немо́тствующаго младе́нця Бо́гом призва́нний.","Ра́дуйся, бога́тство, сла́ву і по́чести ми́ра презрі́вий;","ра́дуйся, єди́ному Го́споду служи́ти восхоті́вий.","Ра́дуйся, апо́столов Христо́вих досто́йних преє́мниче;","ра́дуйся, архієре́єв святи́х преподо́бний сопресто́льниче.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя небе́сноє промишле́ніє, соверши́вшеєся в чу́днім призва́нії твоє́м ко служе́нію Це́ркві, прему́дре, посвяти́л єси́ про́чеє вре́м'я житія́ твоєго́ на угожде́ніє во́лі Боже́ственній, і прине́сл єси́ всего́ себе́ і вся своя́ в же́ртву призва́вшему тя Го́споду, поя́ єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним, напоє́нним же от сло́ва Бо́жия, уразумі́в я́ко основа́ніє всіх доброді́телей і сою́з соверше́нства духо́внаго люби́ к Бо́гу і бли́жнему єсть, благоче́стне, потща́лся яви́ти ю в себі́ не сло́вом то́кмо, но ді́лом і і́стиною. Ті́мже бе́дствующим ру́ку ско́рия по́мощі простира́л єси́, імі́нія своя́ вся убо́гим расточи́л єси́, і та́ко наста́вил єси́ нас зва́ти тебі́ си́це:","Ра́дуйся, я́ко путе́м нестяжа́нія апо́стольськаго ше́ствовати возлюби́л єси́;","ра́дуйся, я́ко все своє́ попече́ніє на Про́мисл Бо́жий возложи́л єси́.","Ра́дуйся, милосе́рдія я́же во Христі́ подража́телю;","ра́дуйся, нищети́ єго́ до́льнія доброво́льний послі́дователю.","Ра́дуйся, ме́ньших бра́тій Христо́вих дру́же і благоді́телю;","ра́дуйся, скорб'я́щих і озло́бленних ско́рий уті́шителю.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́єм, преподо́бне, труди́ і ско́рби вели́каго служе́нія святи́тельськаго на по́льзу це́ркве Медіола́нськия, во сла́ву же Го́спода Ісу́са, благоду́шно поне́сл єси́, о всіх же благословля́л єси́ Бо́га, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я жезл си́ли, крі́пость єва́нгельськую, по́сланную ті от Сіо́на Небе́снаго, святи́телю, госпо́дствовал єси́ посреді́ враго́в твої́х і не дал єси́ волко́м ходя́щим во о́вчих ко́жах, в се́рдці же нося́щим яд па́губи, расхи́тити ста́до твоє́. Ті́мже похва́льная воспису́єм ті сія́:","Ра́дуйся, слуго́ Спа́са ві́рнійший;","ра́дуйся, стра́же до́му Бо́жия бди́тельнейший.","Ра́дуйся, па́стирю Христо́в честні́йший;","ра́дуйся, побо́рниче ві́ри, во пре́ніїх с єресеучи́тельми мудрі́йший.","Ра́дуйся, злоче́стія арія́нськаго потреби́телю;","ра́дуйся, пра́вих догма́тов насади́телю.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю крамоли́, воздви́гшуюся на це́рков Медіола́нськую, зря, Амвро́сіє, сладкоглаго́ливою бесі́дою твоє́ю, соді́йствієм же Бо́жиїм утиши́л єси́ м'яте́ж людськи́й, і та́ко научи́л єси́ чад ми́ра пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Феодо́сій цар преще́ніє твоє́, і́мже возбраня́шеся єму́ я́ко уби́йце вни́ти в це́рков Бо́жию, во є́же приобщи́тися Тайн святи́х, повинова́ся ті, я́ко грі́шник смире́нно ка́ющийся і примире́нія с Го́сподом жа́ждущий. Того́ ра́ди по достоя́нію возглаша́єм ті:","Ра́дуйся, Та́їн Бо́жиїх му́дрий строї́телю;","ра́дуйся, постановле́ній оте́чеських ві́рний храни́телю.","Ра́дуйся, Нафа́ну і Предте́чі соревни́телю;","ра́дуйся, законопресту́пних нелицемі́рний обличи́телю.","Ра́дуйся, наста́вниче покая́нія і ісправле́нія;","ра́дуйся, Це́ркве Медіола́нськия неумира́ющая сла́во і украше́ніє.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ на тве́рди церко́вній бил єси́, о́тче Амвро́сіє, сві́тлостію уче́нія і житія́ твоєго́ мглу єресе́й разгоня́ющая і мрак безбо́жия потребля́ющая, неві́рних от тьми неві́рія к сві́ту невече́рнему привлача́ющая і всіх ко спасе́нію путеводя́щая, пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя медіола́нстії лю́діє му́драго пі́стуна і любвеоби́льнаго отця́ па́стві своє́й, святи́телю, притека́ху к милосе́рдію твоєму́ во всіх ско́рбіх і ну́ждах свої́х. Ти же, ми́лостиве, нікого́же отри́нул єси́, но всім всяк помо́щник бил єси́, досто́йний сицеви́х похва́л:","Ра́дуйся, си́рих покрови́телю;","ра́дуйся, оби́димих защи́тителю.","Ра́дуйся, пліне́нних от ва́рвар іскупи́телю;","ра́дуйся, от ко́зней сатани́нських свободи́телю.","Ра́дуйся, я́ко досто́йно сла́достноє і́м'я носи́л єси́;","ра́дуйся, я́ко воі́стину сла́достен наста́вник і пособи́тель всім бил єси́.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник веща́ємих ті от А́нгел к у́ху глаго́лов Бо́жиїх бил єси́, святи́телю Амвро́сіє, ті́мже словеса́ уст твої́х па́че ме́да і со́та услажда́ху всіх послу́шающих тебі́ і Бо́гу вопію́щих: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ а́ки со́лнце світ доброді́тельнаго житія́ твоєго́ на землі́, богому́дре о́тче, в тебі́ бо зрим вся єли́ка честна́, єли́ка пра́ведна, єли́ка пречи́ста. Сих ра́ди сла́в'яще Свята́го Ду́ха, вино́вника благи́х, от си́ли в си́лу свяще́ннотайні ве́дшаго тя, зове́м:","Ра́дуйся, доброді́телей єва́нгельських пребога́тоє сокро́вище;","ра́дуйся, всегда́шніх воздиха́ній і моли́тв я́же к Бо́гу пречестно́є святи́лище.","Ра́дуйся, кро́тости і смире́нія боголі́пноє жили́ще;","ра́дуйся, терпі́нія тве́рдоє храни́лище.","Ра́дуйся, церкве́й Бо́жиїх украси́телю і пречу́дний побо́рниче;","ра́дуйся, чистоти́ ді́вственний учи́телю і неоску́дний слез істо́чниче.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ улучи́ти спасе́ніє во мно́зі сові́ті, смиренному́дре, імі́л єси́ дру́га душі́ твоєя́ пресви́тера состарі́вшася і му́дра, почита́я єго́ я́ко отця́ і с ним совіща́лся о ді́ліх свої́х; вразуми́ і нас твори́ти вся с сові́том богому́дрих отце́в, да окормле́нієм їх спаса́ємі, поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Зна́меніє єва́нгельськия любве́ к бли́жнему яви́л єси́, о́тче Амвро́сіє, єгда́ враго́м свої́м благотвори́л єси́ і со грі́шники ка́ющимися го́рко пла́кал єси́. Ті́мже ті я́ко непам'ятозло́бному па́стирю і отцю́, боле́зновавшу о спасе́нії духо́вних чад твої́х, вопіє́м:","Ра́дуйся, незло́бія Христо́ва подража́телю;","ра́дуйся, ка́ющимся грі́шником те́плий сострада́телю.","Ра́дуйся, Іусти́не, враждова́вшей ті, благотвори́вий;","ра́дуйся, злоді́ю твоєму́ ру́ку усо́хшую ісціли́вий.","Ра́дуйся, я́ко весь кро́тость і любо́в бил єси́;","ра́дуйся, я́ко висоти́ соверше́нства дости́гл єси́.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нния і ди́вния си́ли перст Бо́жий сотвори́ в житії́ твоє́м, святи́телю, єгда́ уме́рша о́трока воскреси́ тобо́ю, разсла́бленную ісціли́, арія́нина, почита́нія ра́ди святи́х моще́й хули́вшаго тя, бі́су преда́, безсту́дную жену́ сирмі́йську уничижи́вшую тя, ка́рою порази́. І кто от сли́шащих вся сія́ не просла́вить ди́внаго в житії́ твоє́м Бо́га пі́снію: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнен бив ре́вности по Бо́зі, о́тче Амвро́сіє, такову́ю власть над де́мони стяжа́л єси́, я́ко ніже́ к две́рем до́му твоєго́ прибли́зитися можа́ху: огнь бо ісходя́й отту́ду гна́ше їх, я́ко прах, єго́же возмета́єть вітр от лиця́ землі́. Толи́ко стра́шний де́моном уго́дниче Бо́жий, огради́ і на́шу не́мощ предста́тельством твої́м от губи́тельних стріл їх, да вопіє́м ті сицева́я:","Ра́дуйся, от ко́зней лю́таго мироде́ржця крі́пкий ві́рних храни́телю;","ра́дуйся, от зло́бних слуг єго́, зія́ющих пожре́ти ни, ві́рний наш обличи́телю.","Ра́дуйся, я́ко пла́мень лиця́ бісо́в попаля́ющий;","ра́дуйся, я́ко гром киче́ніє па́дшаго денни́ці поража́ющий.","Ра́дуйся, всю си́лу єго́ си́лою кре́стною попра́вий;","ра́дуйся, нечи́стих духо́в от притека́ющих к тебі́ отгна́вий.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 9","ps":["Все житіє́ на́ше во юдо́лі земна́го стра́нствованія сего́ іспо́лнено безчи́сленних іскуше́ній і бід, гріхо́в і страсте́й, вою́ющих на ни: ка́ко у́бо ізби́ти возмо́жем ві́чних мук, окая́ннії, єгда́ пости́гнеть нас смерть неумоли́мая, а́ще не ти, о́тче, с наде́ждою на́шею Богома́терію, предста́тельствовати за ни бу́деши, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния ви́дим тобо́ю посра́мленния, святи́телю: А́рія бо ху́льних после́дователей препрі́л єси́, Симма́ха високоу́мнаго низложи́л єси́, мудреці́, і́же от восто́ка, глубино́ю богосло́вія своєго́ удиви́л єси́, і вся ві́рния уче́нієм і́стинним просвіти́л єси́. Ті́мже мо́лим тя: осія́й і нас сві́том богоразу́мія твоєго́, да отбі́гше скверн тлетво́рнаго ду́ха вре́мене і собла́знов бори́теля, вопіє́м ті:","Ра́дуйся, душ на́ших просвіти́телю;","ра́дуйся, ві́ри правосла́вния побо́рниче.","Ра́дуйся, велі́ній Бо́жиїх учи́телю;","ра́дуйся, пле́вел вра́жиїх, всева́ємих в ду́ші спя́щих челові́к, іскорени́телю.","Ра́дуйся, я́ко мно́гих коле́блемих неві́рієм в пра́вой ві́рі укріпи́л єси́;","ра́дуйся, я́ко догма́ть о єдиносу́щном і равноче́стном Отцю́ і Ду́хові Божестві́ Си́на уясни́л єси́.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 10","ps":["Спасе́ніє соверше́нноє улучи́в от привре́менних бур і бід, уго́дниче Бо́жий Амвро́сіє, не забу́ди нас, потопля́ємих напа́стей бу́рею. Но в ни́хже сам іскуше́н бил єси́, і нам іскуша́ємим помози́, да поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну тя тве́рдую і ізві́стно утвержде́ніє гра́ду твоєму́ і всім чту́щим па́м'ять твою́ іспові́дающе, святи́телю, дерза́єм по достоя́нію воспі́ти тебі́ хвале́ніє сіє́:","Ра́дуйся, царе́й бранелюби́вих умиротвори́телю;","ра́дуйся, благоде́нствія оте́чественнаго храни́телю.","Ра́дуйся, я́ко тобо́ю царю́ Гратія́ну побі́да на го́ти дарова́ся;","ра́дуйся, я́ко тобо́ю мно́гим мир от Феодо́сія ісхода́тайствовася.","Ра́дуйся, я́ко тобо́ю проще́ніє гріхо́в улуча́єм;","ра́дуйся, я́ко тобо́ю от бід спаса́ємі, мир с Бо́гом обріта́єм.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 11","ps":["Піснь «Тебе́ Бо́га хва́лим, Тебе́ Го́спода іспові́дуєм…» па́че вся́каго возду́шнаго орга́на услажда́ющую ві́рних, воспі́л єси́ в честь Боже́ственній Тро́йце, святи́телю. Ни́ні же в Це́ркві Небе́сній поє́ши со А́нгели і́ну піснь то́йжде Тро́йце: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельна світи́льника, єще́ на землі́ просія́вша невеще́ственним сві́том, ві́дуще тя, о́тче святи́й, ку́ю досто́йную похвалу́ принесе́м ті грі́шнії, ко́єю пі́снію ублажи́м тя недосто́йнії, о святи́телю Христо́в. Єди́н то́кмо сві́дий глубини́ серде́чния і реки́й: «Аз прославля́ющия М'я просла́влю», — єди́н Он вість, ка́ко по достоя́нію просла́вити тя. Оба́че ві́дий, я́ко челові́к, на́шу не́мощ, не отри́ни, я́ко оте́ць ми́лостивий, і на́ша убо́гія, но от і́скренних серде́ць приноси́мия ті хвали́ сія́:","Ра́дуйся, а́нгеле земни́й, єще́ на землі́ сві́том невеще́ственним озаре́нний;","ра́дуйся, челові́че небе́сний, єще́ во пло́ті лицезрі́нієм сладча́йшаго Ісу́са почте́нний.","Ра́дуйся, світи́льниче Боже́ственнаго сві́та, уче́нієм свої́м ми́ра конці́ озари́вий;","ра́дуйся, луче́ ми́сленнаго Со́лнця, теплото́ю любве́ своєя́ вертогра́д Єго́ оживи́вий.","Ра́дуйся, звіздо́, твердь церко́вную сві́тло украша́ющая;","ра́дуйся, похвало́ і дони́ні Медіола́н осіява́ющая.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́тію небе́снаго покро́ва твоєго́ не лиши́ нас нікогда́, о ми́лостиве о́тче, но при́сно моли́ся о нас к ще́дрому Го́споду, Єму́же с ли́ки святи́х немо́лчно поє́ши: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ і по́двиги преподо́бнаго житія́ твоєго́, святи́телю, сла́вим кончи́ну твою́, є́юже ми́рно отше́л єси́ на не́бо, і ублажа́єм соца́рствованіє твоє́ та́мо с Бо́гом ві́чним. Ти же, уго́дниче святи́й, при́зри с висоти́ о́наго блаже́ннаго приста́нища твоєго́ на нас, пла́вающих в молві́ жите́йських попече́ній і к тебі́, неви́димому окорми́телю на́шему, із глубини́ душі́ вопію́щих:","Ра́дуйся, пла́ваніє своє́ в жите́йськом мо́рі до́брі сверши́вий і безці́нноє сокро́вище ві́ри в бе́зднах єго́ не потопи́вий;","ра́дуйся, ко приста́нищу ра́йському безбі́дно припли́вий і віне́ць нетлі́нний от Христа́ улучи́вий.","Ра́дуйся, я́ко та́мо ликовству́я, і нас, до́лу су́щих, любо́вію твоє́ю досяза́єши;","ра́дуйся, я́ко ду́хом твої́м нам ви́ну спребива́єши.","Ра́дуйся, я́ко тобо́ю гні́ва Бо́жия ізбавля́ємся;","ра́дуйся, я́ко мольба́ми твої́ми к приста́нищу го́рнему направля́ємся.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 13","ps":["О святи́й і ми́лостивий уго́дниче Бо́жий Амвро́сіє! Прийми́ с любо́вію приноси́моє сіє́ ма́лоє, но от усе́рдія приноси́моє тебі́ хвале́ніє на́ше, і потщи́ся ізба́вити нас от болі́зней душе́вних і тіле́сних, от всіх бід і зол, да тобо́ю улучи́вше Ца́рство Небе́сноє, во ві́ки поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельських сил і всея́ тва́рі Соді́тель, єще́ от младе́нчеських пеле́н твої́х предуказа́вий добро́ту душі́ твоєя́, свя́те Амвро́сіє, подаде́ тя, во во́зраст прише́дша, а́нгела це́ркві Медіола́нстей, па́стиря і учи́теля слове́сному ста́ду Своєму́, і сим научи́ нас зва́ти тебі́ си́це:","Ра́дуйся, от колибе́лі младе́нчеськия на служе́ніє Це́ркві ро́єм пчел предуказа́нний;","ра́дуйся, ко святи́тельству чрез немо́тствующаго младе́нця Бо́гом призва́нний.","Ра́дуйся, бога́тство, сла́ву і по́чести ми́ра презрі́вий;","ра́дуйся, єди́ному Го́споду служи́ти восхоті́вий.","Ра́дуйся, апо́столов Христо́вих досто́йних преє́мниче;","ра́дуйся, архієре́єв святи́х преподо́бний сопресто́льниче.","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́ннаго чудотво́рця і світи́льника це́ркве Медіола́нськия свята́го Амвро́сія, прийді́те, ві́рнії, почти́м по достоя́нію усе́рдною хвало́ю. Ти же, уго́дниче Бо́жий ми́лостивий, прийми́ с любо́вію сіє́ приноше́ніє на́ше, да зове́м ті:","Ра́дуйся, Амвро́сіє, святи́телю Христо́в і чудотво́рче."]},{"h":"Молитва","ps":["О пресла́вний чудотво́рче, в ско́рбіх ско́рий помо́щниче і усе́рдний о ми́рі к Бо́гу моли́твенниче, о́тче святи́й Амвро́сіє! Ві́ми, я́ко ве́ліє ко Спа́су і́маши дерзнове́ніє, предстоя́ го́рнему Престо́лу Єго́, і сего́ ра́ди смире́нно припа́даєм ті: моли́ся Єму́, уго́дниче Бо́жий, да пода́сть наро́ду Украї́нському благоде́нственноє і ми́рноє житіє́, да ізба́вить от враг ви́димих і неви́димих, от наше́ствія іноплеме́нних, от неду́га і гла́да, от вся́кия ско́рби і смертоно́сния я́зви і от вся́каго зла; нам же всім, ві́рою пра́зднующим святу́ю па́м'ять твою́ і усе́рдно хода́тайства твоєго́ ча́ющим, да ниспо́слеть вся благопотре́бная ко вре́менному і ві́чному житію́ на́шему, па́че же оставле́ніє гріхо́в, мир по́мислов, тишину́ серде́чную, здра́віє душа́м і тілесе́м на́шим. Єй, святи́телю Бо́жий, па́стирю Христо́в ми́лостивейший, покрови́телю наш гото́війший! Усли́ши нас, єще́ єди́наго от тебе́ прося́щих: бу́ди те́плий моли́твенник і предста́тель ко Го́споду о духо́вних па́стиріх і отці́х на́ших (імена́), і́же не́мощі на́ша но́сять і о нас боле́знують, до́ндеже вообрази́ться в нас Христо́с, да сохрани́ть Он, всеблаги́й і вся могу́щий Влади́ка, дража́йшия дні житія́ їх в неруши́мом ми́рі і крі́пости сил духо́вних і тіле́сних, да приведе́ть нас, недосто́йних рабо́в Свої́х, їх окормле́нієм і моли́твами, твої́м же хода́йтайством і заступле́нієм ко приста́нищу жи́зні несконча́ємия, іді́же херуви́ми і серафи́ми, святі́ї всі с Богоро́дицею і с тобо́ю, покрови́телем на́шим, непреста́нними гла́си сла́в'ять Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О всесвяти́й Амвро́сіє, уго́дниче Бо́жий ізря́днійший, покрови́телю мой ми́лостивейший! При́зри с висоти́ го́рняго жили́ща твоєго́ на м'я недосто́йнаго, неради́ваго, уни́лаго в настоя́щем житії́ сем. Виждь мене́ грі́шнаго, в толи́цім обстоя́нії су́щаго, умо́м помраче́ннаго, во́лею ко злу преклоне́ннаго, і се́рдцем па́че к землі́, не́же к небесі́, прилепле́ннаго. Виждь стра́стноє обурева́ніє душі́ моєя́ і не́мощ і небреже́ніє моє́. Виждь при сем і кова́рство злонача́льника і губи́теля моєго́, виждь, о святи́телю Христо́в, і умилосе́рдися о мні, такова́го ра́ди положе́нія моєго́. Помози́ мі, о засту́пниче мой, ско́рим предста́тельством твої́м. Ісхода́тайствуй мі от Отця́ щедро́т бо́дрость і си́лу, во є́же твори́ти во́лю Єго́, благу́ю, уго́дную і соверше́нную, стра́сті моя́ умертви́ти, де́мона низложи́ти, мир себі́ расп'я́ти і себі́ ми́ру, і та́ко дости́гнути христия́нськия кончи́ни живота́ своєго́, безболі́зненни, непости́дни, ми́рни. По ісхо́ді же притре́петния душі́ моєя́ от окая́ннаго і бре́ннаго тілесе́ сего́, бу́ди єй а́нгел покрови́тель, добр спу́тник, ві́рен храни́тель і защи́тник от лю́тих нападе́ній нача́льника возду́шних мита́рств, да безбі́дно преше́д о́ния, си́лою предста́тельства твоєго́, сподо́блюся про́чеє і аз, послі́дній із всіх, і́же в ца́рстві благода́ті, узрі́ти сладча́йшеє лице́ Го́спода на́шего і сла́вити Єго́ со Отце́м і Святи́м Ду́хом, і твоє́ ми́лостивноє о мні предста́тельство, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / воздержа́нія учи́теля / яви́ тя ста́ду твоєму́, / я́же веще́й і́стина. / Сего́ ра́ди стяжа́л єси́ смире́нієм висо́кая, / нището́ю бога́тая, / о́тче Амвро́сіє, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Боже́ственними догма́ти облиста́я, / помрачи́л єси́ А́рієву пре́лесть, священнотаї́нниче і па́стирю Амвро́сіє; / чудоді́йствуя же си́лою Ду́ха, / стра́сті разли́чния я́ві ісціли́л єси́, о́тче преподо́бне, // Христа́ Бо́га моли́ спасти́ся душа́м на́шим."]},{"h":"Інший кондак, глас 8","ps":["Ізря́дно сло́во жи́зні стяжа́в, о́тче му́дре, / не усумні́ся висоти́ ца́рськия, богонаказа́тельне царя́ обличи́ і умудри́в. / Тім па́че че́стне почте́ся і люде́й свої́х па́ству к Бо́гу наста́ви. / Сего́ ра́ди зове́м ті: // ра́дуйся, Амвро́сіє преди́вне."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Амвро́сіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Луці, сповіднику, архієпископу Кримському (інший акафіст)","e":"Akathist to St Luke, Confessor, Archbishop of Crimea (another akathist)","secs":[{"h":"Кондак 1","ps":["Возбра́нний святи́телю Це́ркве Правосла́вния і іспові́дниче, возсія́вий страні́ на́шей в землі́ Кри́мстей, я́ко світоза́рноє світи́ло, до́брі потруди́вийся і за і́м'я Христо́во гоне́ніє претерпі́вий, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам тебе́ но́ваго моли́твенника і помо́щника, похва́льноє воспіва́єм ті пі́ніє: ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Влади́ці небесе́ і землі́, от вся́ких неду́гов душе́вних і тіле́сних свободи́ нас і до́брі стоя́ти в Правосла́вії укріпи́, да всі во умиле́нії зове́м ті:","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, Луко́ пресла́вний, подо́бно євангели́сту і апо́столу Лукі́, єму́же тезоімени́ть сий, от Бо́га дар ціли́ти неду́ги в челові́ціх прия́л єси́, во врачева́нії болі́зней бли́жніх мно́гія труди́ под'є́мля, і плоть нося́, о пло́ті не раді́л єси́, ді́ли до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже благода́рні во умиле́нії зове́м ті:","Ра́дуйся, от ю́ности ра́зум свой і́гу Христо́ву покори́вий.","Ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє би́вий.","Ра́дуйся, блаже́нство ми́лостивих, по Сло́ву Го́спода, унаслі́довавий.","Ра́дуйся, ві́рою Христо́вою і зна́нієм богодарова́нним мно́гія неду́жния ісціли́вий.","Ра́дуйся, стра́ждущих тіле́сними неду́ги врачу́ милосе́рдний.","Ра́дуйся, во дні бра́ні вожде́й і во́їнов ісціли́телю.","Ра́дуйся, всіх враче́й наста́вниче.","Ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче.","Ра́дуйся, Це́ркві Правосла́вния утвержде́ніє.","Ра́дуйся, землі́ на́шея озаре́ніє.","Ра́дуйся, кри́мськия па́стви похвало́.","Ра́дуйся, гра́да Симферо́поля украше́ніє.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 2","ps":["Ви́дя в челові́ціх во вре́м'я врачева́ній, а́ки в зерца́лі, прему́дрость і сла́ву Творця́ вся́чеських Бо́га, к Нему́ ду́хом ви́ну возноси́лся єси́, богому́дре, сві́том же богоразу́мія твоєго́ і нас озари́, да вопіє́м ку́пно с тобо́ю: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой Боже́ственними уче́ньми просвіти́л єси́, Луко́ всесла́вне, отве́ргнув вся́коє плотсько́є мудрова́ніє, с ра́зумом же і во́лю повину́л єси́ Го́сподеві. Подо́бен апо́столом бив, ті́ї бо по Сло́ву Христо́ву: «Гряди́та по Мні, і сотворю́ ви ловця́ челові́ком», – оста́виша вся і по Нем ідо́ша, і ти, свя́те, усли́шав зову́щаго тя на служе́ніє Го́спода Ісу́са чрез раба́ Своєго́ архієпи́скопа Ташке́нтськаго Інноке́нтія а́біє приє́млеши свяще́нство в Це́ркві Правосла́вній. Сего́ ра́ди, я́ко богому́драго наста́вника тя ублажа́юще, воспіва́єм си́це:","Ра́дуйся, А́нгела Храни́теля увеселе́ніє.","Ра́дуйся, я́ко того́ ніколи́же опеча́лил єси́.","Ра́дуйся, во уче́нії преспіва́вий і тім мудреці́ ми́ра сего́ удиви́вий.","Ра́дуйся, от творя́щих беззако́ніє уклони́вийся.","Ра́дуйся, Бо́жия Прему́дрости созерца́телю і пропові́дниче.","Ра́дуйся, і́стиннаго богосло́вія златослове́сний учи́телю.","Ра́дуйся, апо́стольських преда́ній блюсти́телю.","Ра́дуйся, свіще́, Бо́гом возже́нная, мрак нече́стія разгоня́ющая.","Ра́дуйся, звіздо́, путь ко спасе́нію показу́ющая.","Ра́дуйся, Правосла́вія ревни́телю.","Ра́дуйся, раско́льников обличи́телю.","Ра́дуйся, свиді́ній і оправда́ній Госпо́дніх возжада́вий.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия, єще́ во вре́менній жи́зні прия́л єси́ дар, свя́те Луко́, неду́ги ціли́ти, да всі, усе́рдно притека́ющії к тебі́ неду́гов тіле́сних і па́че душе́вних ісціле́нія сподобля́ються, вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я неуси́пноє попече́ніє о спасе́нії душ, вві́ренних тебі́ от Бо́га, Луко́ блаже́нне, па́стирськи к душеспаси́тельній жи́зні і сло́вом і са́мим ді́лом непреста́нно наставля́л єси́. Сего́ ра́ди прийми́ от на́шего усе́рдія досто́йния похвали́ тебі́:","Ра́дуйся, Бо́жия ра́зума іспо́лненний.","Ра́дуйся, благода́тію Ду́ха Свята́го преосене́нний.","Ра́дуйся, нищети́ Христо́ви подража́телю.","Ра́дуйся, па́стирю до́брий, уклоня́ющихся от ві́ри правосла́вния і блужда́ющих по гора́м суєму́дрія взиска́вий.","Ра́дуйся, ді́лателю виногра́да Христо́ва, чад Бо́жиїх укріпля́яй в і́стинній ві́рі правосла́вній.","Ра́дуйся, щі́те, защища́яй благоче́стіє.","Ра́дуйся, непоколеби́моє Правосла́вія основа́ніє.","Ра́дуйся, тве́рдий ка́меню ві́ри.","Ра́дуйся, душепа́губнаго неві́рія і злотво́рнаго обновле́нчества обличи́телю і іскорени́телю.","Ра́дуйся, в ді́ланії духо́внім подвиза́ющихся му́дрий укріпи́телю.","Ра́дуйся, от ми́ра ізгна́нним приста́нища ти́хаго указа́телю.","Ра́дуйся, я́ко приї́м крест, Христу́ послі́довал єси́.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній мно́гих, недоуміва́ше раб Бо́жий, что рече́ть о нем Госпо́дь, єгда́ проразуміва́ху єго́ досто́йна би́ти єпи́скопом гра́ду Ташке́нту: оба́че всего́ себе́ Христу́ Бо́гу предаде́, Тому́ о всем благодаре́ніє возсила́я, зови́й: «Благослове́н Бог, ізлива́яй благода́ть Свою́ на архієре́ї Своя́», – і поя́ Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє правосла́внії, в гоне́нії су́щії, о благопло́дних добро́тах душі́ твоєя́, богоно́се Луко́, і ви́дівше тя на сте́пені святи́тельства, я́ко досто́йний сосу́д Боже́ственния благода́ті, вся немощна́я врачу́ющия і оскудіва́ющая восполня́ющия, див'я́ться чу́дному промишле́нію Бо́жию о тебі́ і прино́сять ті сицева́я благохвале́нія:","Ра́дуйся, архієре́ю, от Самаго́ Го́спода пронарече́нний.","Ра́дуйся, о надписа́нії са́на єпи́скопскаго на кни́зі твоє́й предуказа́ніє ми́сленноє прия́вий.","Ра́дуйся, ієра́рхов украше́ніє.","Ра́дуйся, па́стирю до́брий, гото́вий ду́шу свою́ положи́ти за о́вці твоя́ слове́сния.","Ра́дуйся, многосві́тлий Це́ркве світи́льниче.","Ра́дуйся, апо́столов соприча́стниче.","Ра́дуйся, іспові́дников украше́ніє.","Ра́дуйся, о себі́ попече́ніє вся́коє отве́ргнувий.","Ра́дуйся, скорбе́й утоли́телю.","Ра́дуйся, о людськи́х неві́жествіїх печа́льниче.","Ра́дуйся, іска́вших спасе́нія пра́вим уче́нієм оглаша́вий.","Ра́дуйся, житіє́м твої́м сего́ уче́нія не посрами́вий.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 5","ps":["Богото́чною Кро́вію от ві́чния сме́рти іскупле́нния соблюда́я, єгда́ сан єпи́скопа в дні стра́шних гоне́ній по благослове́нію свята́го Патріа́рха Ти́хона от рук архієре́єв правосла́вних прия́л єси́, святи́телю Луко́, ді́ло благові́стника до́брі сотвори́л єси́, облича́я, запреща́я, умоля́я, со вся́ким долготерпі́нієм і уче́нієм, і поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше а́нгельстії чи́нове вели́кия твоя́ по́двиги, єгда́ по за́повіді Госпо́дней: «Блаже́нні і́згнані пра́вди ра́ди, я́ко тіх єсть Ца́рствіє Небе́сноє», – в крі́пості серде́чній безро́потно поне́сл єси́ заточе́ніє і ізгна́ніє в Сиби́р за і́м'я Го́спода і святу́ю Це́рков Христо́ву, терпі́нієм ве́ліїм устроя́я своє́ спасе́ніє, приме́ром же свої́м ві́рних ду́ші назида́я. Ми же тя усе́рдно любо́вію почита́юще, че́ствуєм похвала́ми си́ми:","Ра́дуйся, світи́льниче, на сві́щниці церко́вній поста́вленний.","Ра́дуйся, я́ко сло́во Писа́нія: «Люби́ долготерпи́ть», – на тебі́ оправда́ся.","Ра́дуйся, защища́ти тя ві́рним воспрети́вий.","Ра́дуйся, власте́м повину́вийся і сего́ ра́ди во́лею в ру́ки во́їнов но́щію преда́вийся.","Ра́дуйся, клевре́ти непра́ведних суді́й уничиже́нний.","Ра́дуйся, в заточе́ніє со смире́нієм безро́потно ше́дий.","Ра́дуйся, із управля́ємия тобо́ю Ташке́нтськия єпа́рхії пра́вди ра́ди ізгна́нний.","Ра́дуйся, ві́рними опла́канний.","Ра́дуйся, за Го́спода Расп'я́таго із'язвле́нний і зауше́нний.","Ра́дуйся, уста́ лжи́вих неве́ров загради́вий.","Ра́дуйся, пра́ведними усти́ небе́сния і́стини і в ізгна́нії віща́вий.","Ра́дуйся, я́ко му́ченици на небесі́х о терпі́нії твоє́м ликова́ху.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчний та́йни Пресвяти́я, Єдиносу́щния і Неразді́льния Тро́йці бил єси́ і в темни́ці, і во гра́діх сиби́рськаго ізгна́нія, терп'я́ глад, мраз сі́верния страни́ і жесто́кость клевре́тов безбо́жних. Сего́ ра́ди пропові́дуєть Це́рков Кри́мская вели́чія Бо́жия, явле́нная на тебі́, святи́телю Луко́, я́ко прия́л єси́ дар ціли́ти неду́ги душе́вния і тіле́сния і в страні́ ізгна́нія, да всі єди́ним се́рдцем і єди́ними усти́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко звізда́ лучеза́рная, красноя́рстей па́стві і тамбо́встій, озаря́я ду́ші ві́рних і разгоня́я тьму нече́стія і безбо́жия. І іспо́лнишася на тебі́ сло́ва Христо́ви: «Блаже́нні єсте́, єгда́ поно́сять вам, і іждену́ть, і реку́ть всяк зол глаго́л на ви лжу́ще, Мене́ ра́ди». Ти же, гони́мий із гра́да во град і клевети́ терп'я́, архипа́стирськоє служе́ніє усе́рдні ісполня́л єси́ і сла́достію писа́ній твої́х насища́л єси́ вся а́лчущия і жа́ждущия пра́вди, і́же благода́рні взива́ють тебі́:","Ра́дуйся, наста́вниче, вся к небесі́ наставля́яй.","Ра́дуйся, сла́ви Бо́жия і́стинний ревни́телю.","Ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, за Христа́ Го́спода темни́ці і біє́нія терпі́вий.","Ра́дуйся, смире́нія Єго́ і́стинний подража́телю.","Ра́дуйся, вмісти́лище Ду́ха Свята́го.","Ра́дуйся, вше́дий с му́дрими в ра́дость Го́спода твоєго́.","Ра́дуйся, користолю́бія обличи́телю.","Ра́дуйся, па́губу тщесла́вія показа́вий.","Ра́дуйся, беззако́нники ко обраще́нію призива́вий.","Ра́дуйся, і́мже сатана́ посрами́ся.","Ра́дуйся, і́мже Христо́с просла́вися.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 7","ps":["Хотя́ досто́йно соверши́ти по́двиг, возложе́нний на тя от Бо́га, обле́клся єси́ во вся ору́жія Бо́жия і стал на брань проти́ву миродержи́телей ві́ка сего́, духо́в зло́би поднебе́сних, препоя́сав чре́сла своя́ і́стиною і оболки́йся в броню́ пра́вди, угаси́л єси́, іспові́дниче Луко́, вся стрі́ли лука́ваго, поя́ Соді́телю і Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє гоне́ніє воздви́жеся беззако́нних челові́к і безбо́жних на Це́рков Правосла́вную, і в да́льнюю тає́жную глубину́ угна́ша тя, святи́телю Луко́, і близ сме́рти бив, руко́ю Бо́жиєю сохране́н, взива́л єси́ с Па́влом апо́столом: «До ни́нішняго часа́ і а́лчем, і жа́ждем, і наготу́єм, і стра́ждем, і скита́ємся. Гони́ми, терпи́м: я́коже отре́би ми́ру би́хом, всім попра́ніє досе́лі». Сего́ ра́ди, ві́дуще такова́я, ублажа́єм тя:","Ра́дуйся, іспові́дниче Христо́в блаже́нний.","Ра́дуйся, мраз лю́тий і глад во ізгна́нії претерпі́вий.","Ра́дуйся, близ сме́рти би́вий, Го́сподом сохране́нний.","Ра́дуйся, самоотверже́ніє всеці́лоє показа́вий.","Ра́дуйся, уневі́стивий ду́шу твою́ Жениху́ Христу́.","Ра́дуйся, Го́спода Расп'я́таго на Кресті́ при́сно пред собо́ю предзрі́вий.","Ра́дуйся, во бді́ніїх і моли́твах неосла́бно пребива́л єси́.","Ра́дуйся, Єдиносу́щния Тро́йці і́стинний ревни́телю.","Ра́дуйся, ско́рий от вся́кия болі́зні безме́здний врачу́.","Ра́дуйся, ломо́тния і опу́хлия уврачева́вий.","Ра́дуйся, от неісці́льния гно́йния болі́зні косте́й і ран здра́ви возста́вивий.","Ра́дуйся, я́ко ві́рою твоє́ю і труди́ враче́вними разсла́бленнії ізцеле́ша.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 8","ps":["Стра́нник во юдо́лі земні́й бив, терпі́нія, воздержа́нія і чистоти́ о́браз показа́л єси́, іспові́дниче Луко́. Любо́в єва́нгельськую яви́л єси́, єгда́ оте́чествіє твоє́ в опа́сности от наше́ствія іноплеме́нник пребива́ше, день от дне во враче́бниці трудя́шеся, ісціля́я неду́ги і ра́ни вожде́й і во́їнов оте́чествія земна́го, непам'ятозло́бієм і любо́вію удивля́я вся творя́щия ті напа́сти, і мно́гія сим обрати́ ко Христу́, во є́же пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнь любве́ Христо́ви, Луко́ благосе́рде, ду́шу твою́ полага́л єси́ за дру́ги твоя́, і я́ко А́нгел Храни́тель прису́щ бил єси́ бли́жнім і да́льним, озло́бленния укроща́я, вражду́ющия примиря́я і спасе́ніє всім устроя́я. Помина́я труди́ твоя́ во бла́го люде́й оте́чествія твоєго́, благода́рні взива́єм ті:","Ра́дуйся, ди́вную любо́в к оте́чествію земно́му показа́вий.","Ра́дуйся, смире́нія і незло́бія учи́телю.","Ра́дуйся, ізгна́ніє і жесто́кия му́ки мужему́дренно претерпі́вий.","Ра́дуйся, за Христа́ пострада́вий і муче́нія прия́вший.","Ра́дуйся, тве́рдо Єго́ іспові́давий.","Ра́дуйся, зло́бу враго́в любо́вію Христо́вою побіди́вий.","Ра́дуйся, о́тче благосе́рдий, взиска́вий спасе́нія мно́гих.","Ра́дуйся, я́ко вели́кими скорбми́ іскуше́н бил єси́.","Ра́дуйся, в гоне́ніїх терпі́ніє ди́вноє яви́вий.","Ра́дуйся, я́ко за враги́ умоля́л єси́ Го́спода.","Ра́дуйся, єго́же любо́в побіди́ вся́кую вражду́.","Ра́дуйся, єго́же незло́біє покори́ жесто́кия сердца́.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 9","ps":["Всім бил єси́ вся, я́коже і святи́й Па́вел, да вся́ко ні́кия спасе́ши, святи́телю Луко́, архипа́стирський по́двиг соверша́я в Тамбо́встем кра́є, мно́гими труди́ хра́ми обновля́я і созида́я, уста́ви святооте́чеськия стро́го соблюда́я, спасе́нію па́стви твоєя́ служи́ти не преста́л єси́, чи́сто Бо́гові поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії не возмо́гуть по достоя́нію ізрещи́ твої́х благодія́ній мно́жество, єгда́ яви́лся на Кри́мстей землі́, я́ко оте́ць чадолюби́вий, святи́телю о́тче Луко́. Щедрода́тельная бо десни́ця твоя́ всю́ду досяза́ше. Ми же благосе́рдію твоєму́ подража́ти хотя́ще, во удивле́нії взива́єм к тебі́:","Ра́дуйся, лучу́ любве́ Бо́жия.","Ра́дуйся, сокро́вище милосе́рдія Спа́сова неістощи́моє.","Ра́дуйся, я́ко вся своя́ неіму́щим раздава́л єси́.","Ра́дуйся, бли́жнія твоя́ па́че себі́ возлюби́вий.","Ра́дуйся, безма́терніх сиро́т пита́телю і окорми́телю.","Ра́дуйся, безпомо́щних ста́рцев і ста́риць попечи́телю.","Ра́дуйся, я́ко боля́щия і в темни́ці заключе́нния посіща́л єси́.","Ра́дуйся, я́ко ну́жди бі́дних предваря́л єси́ в разли́чних ве́сіх оте́чествія своєго́.","Ра́дуйся, я́ко ни́щія помина́я, обі́ди їм уготовля́л єси́.","Ра́дуйся, я́ко коєму́ждо в го́рестіх, а́ки а́нгел уті́шитель явля́лся єси́.","Ра́дуйся, а́нгеле земни́й і челові́че небе́сний.","Ра́дуйся, я́ко о глубині́ милосе́рдія твоєго́ Ма́тер Бо́жия возра́довася.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 10","ps":["Спасе́нію кри́мськия па́стви твоєя́ служи́ти многолі́тні не преста́л єси́, я́ко пастиренача́льник Христо́с, на ра́міх заблу́дшеє взем єстество́, Бо́гу і Отцю́ приве́л єси́. Бо́жиїм бо милосе́рдієм утіша́я, ко ісправле́нію житія́ словеси́ учи́тельними твої́ми влекл єси́ вся, во є́же се́рдцем чи́стим пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго, Христа́ Бо́га ві́рний служи́тель бив, святи́телю о́тче Луко́, неуста́нно возвіща́л єси́ сло́во і́стини во всіх хра́міх землі́ на́шея Таври́чеськия, душеспаси́тельною пи́щею уче́нія єва́нгельськаго ві́рния ча́да науча́я і уста́в Це́ркве стро́го ісполня́ти повеліва́я. Ті́мже тя, я́ко па́стиря до́браго, си́це прославля́єм:","Ра́дуйся, неутоми́мий пропові́дниче пра́вди єва́нгельськия.","Ра́дуйся, я́ко Бо́гом вруче́нноє тебі́ ста́до слове́сноє до́брі паси́й.","Ра́дуйся, я́ко о́вці своя́ слове́сния от душепа́губних волко́в охраня́вий.","Ра́дуйся, чи́на церко́внаго стро́гий блюсти́телю.","Ра́дуйся, чистоти́ ві́ри правосла́вния охрани́телю.","Ра́дуйся, тобо́ю бо Дух Святи́й написа́ словеса́ спаси́тельная.","Ра́дуйся, я́ко та́йну богосло́вія о ду́сі, душі́ і тілесі́ яви́л єси́ нам.","Ра́дуйся, я́ко в сло́во твоє́, а́ки в ри́зи позлаще́ни, та́йни ві́ри оді́яшася.","Ра́дуйся, мо́лніє, горди́ню низлага́ющая.","Ра́дуйся, гро́ме, беззако́нно живу́щия устраша́яй.","Ра́дуйся, церко́внаго благоче́стія насади́телю.","Ра́дуйся, архіпа́стирю, па́стирі духо́вния наставля́яй і вразумля́яй непреста́нно.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 11","ps":["Пі́ніє у гро́ба твоєго́, уго́дниче Бо́жий, не умолка́ше во днех блаже́ннаго успе́нія твоєго́. Мно́зі бо ві́дяху тя богоно́сна і равноа́нгельна су́ща, собра́шася от всіх преді́л земна́го твоєго́ оте́чествія соверши́ти собо́рноє моле́ніє о душі́ твоє́й, восходя́щей в Го́рнія оби́телі оте́чествія Небе́снаго, воспіва́юще і пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Свіща́ єси́ в Це́ркві Христо́вой, горя́щая невеще́ственним сві́том благода́ті Бо́жієй, бил єси́, святи́телю Луко́, вся конці́ землі́ на́шея озаря́я. Єгда́ же приспі́ вре́м'я отше́ствія твоєго́, Боже́ственнії а́нгели прия́ша святу́ю ду́шу твою́ і в Небе́сния оби́телі вознесо́ша. Ті́мже, помина́юще блаже́нноє успе́ніє і ве́ліє твоє́ на небесі́ і на землі́ прославле́ніє, с ра́достію прино́сим ті благохвале́нія сія́:","Ра́дуйся, світи́льниче неме́ркнущий Сві́та Невече́рняго.","Ра́дуйся, я́ко мно́зі просла́виша чрез твоя́ до́брая діла́ Отця́ Небе́снаго.","Ра́дуйся, я́ко світ до́брих діл твої́х просвіти́ся пред челові́ки.","Ра́дуйся, житіє́м твої́м пра́ведним Бо́гу угоди́вий.","Ра́дуйся, уго́дниче Бо́жий, тече́ніє благоче́стне сконча́вий.","Ра́дуйся, ві́ру, наде́жду і люби́ от Го́спода стяжа́вий.","Ра́дуйся, со Христо́м, Єго́же возлюби́л єси́, наві́ки соєдини́вийся.","Ра́дуйся, Ца́рствія Небе́снаго і сла́ви ві́чния наслі́дниче.","Ра́дуйся, архієре́ю, от ві́чнаго Архієре́я Христа́ благода́тними дара́ми іспо́лненний.","Ра́дуйся, ско́рий помо́щниче призива́ющим тя.","Ра́дуйся, землі́ Кри́мськия но́воє світи́ло і утвержде́ніє.","Ра́дуйся, ро́да христия́нськаго благода́тний покрови́телю.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше ті да́нную позна́вше, благогові́йно лобиза́єм честна́го ли́ка твоєго́ ізображе́ніє, святи́телю Луко́, ча́юще тобо́ю получи́ти проси́моє от Бо́га. Ті́мже припа́дая ко святи́м моще́м твої́м, со умиле́нієм мо́лим тя: укріпи́ нас до́брі стоя́ти во ві́рі правосла́вній і, угожда́юще благи́ми ді́ли, немо́лчно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, хва́лим тя, Христо́ва іспові́дника, святи́теля і предста́теля пред Го́сподем. Весь бо єси́ во ви́шніх, но і ни́жніх не оставля́єши, святи́телю о́тче Луко́, при́сно со Христо́м ца́рствуєши і о нас грі́шних пред Престо́лом Бо́жиїм хода́тайствуєши. Сего́ ра́ди во умиле́нії зове́м ті:","Ра́дуйся, сві́та непристу́пнаго зри́телю.","Ра́дуйся, звіздо́ лучеза́рная, над земле́ю на́шею возсія́вшая.","Ра́дуйся, єму́же сора́дуються а́нгели і о не́мже веселя́ться челові́ци.","Ра́дуйся, научи́вий за́повідем Христо́вим і сотвори́вий я.","Ра́дуйся, я́ко досто́їн яви́лся єси́ Ца́рствія Небе́снаго.","Ра́дуйся, путе́м іспові́дничества ра́йських селе́ній дости́гший.","Ра́дуйся, поноше́нія Христа́ ра́ди терпі́вий і ві́чную с Ним сла́ву прия́вий.","Ра́дуйся, ду́ші на́ша к Ца́рствію Небе́сному путеводя́й.","Ра́дуйся, предста́телю пред Престо́лом Бо́жиїм за ни грі́шния.","Ра́дуйся, Правосла́вія похвало́ і землі́ на́шея ра́дованіє.","Ра́дуйся, в со́нмі святи́х би́ти сподо́бивийся.","Ра́дуйся, Собо́ру всіх Кри́мських святи́х соприча́стниче.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 13","ps":["О, вели́кий і пресла́вний уго́дниче Бо́жий, святи́телю о́тче наш Луко́, прийми́ сіє́ похва́льноє пі́ніє от нас, недосто́йних, оба́че с любо́вію сино́внею тебі́ приноси́моє. Предста́тельством твої́м у Престо́ла Бо́жия і моли́твами твої́ми вся ни во ві́рі правосла́вній і до́брих ді́ліх утверди́. От вся́ких бід, скорбе́й, болі́зней і напа́стей в сей жи́зні находя́щих сохрани́, от муче́ній в бу́дущем ві́ці ізба́ви. І сподо́би во ві́чній жи́зні ку́пно с тобо́ю і со всі́ми святи́ми пі́ти Творцю́ на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, Луко́ пресла́вний, подо́бно євангели́сту і апо́столу Лукі́, єму́же тезоімени́ть сий, от Бо́га дар ціли́ти неду́ги в челові́ціх прия́л єси́, во врачева́нії болі́зней бли́жніх мно́гія труди́ под'є́мля, і плоть нося́, о пло́ті не раді́л єси́, ді́ли до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже благода́рні во умиле́нії зове́м ті:","Ра́дуйся, от ю́ности ра́зум свой і́гу Христо́ву покори́вий.","Ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє би́вий.","Ра́дуйся, блаже́нство ми́лостивих, по Сло́ву Го́спода, унаслі́довавий.","Ра́дуйся, ві́рою Христо́вою і зна́нієм богодарова́нним мно́гія неду́жния ісціли́вий.","Ра́дуйся, стра́ждущих тіле́сними неду́ги врачу́ милосе́рдний.","Ра́дуйся, во дні бра́ні вожде́й і во́їнов ісціли́телю.","Ра́дуйся, всіх враче́й наста́вниче.","Ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче.","Ра́дуйся, Це́ркві Правосла́вния утвержде́ніє.","Ра́дуйся, землі́ на́шея озаре́ніє.","Ра́дуйся, кри́мськия па́стви похвало́.","Ра́дуйся, гра́да Симферо́поля украше́ніє.","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 1","ps":["Возбра́нний святи́телю Це́ркве Правосла́вния і іспові́дниче, возсія́вий страні́ на́шей в землі́ Кри́мстей, я́ко світоза́рноє світи́ло, до́брі потруди́вийся і за і́м'я Христо́во гоне́ніє претерпі́вий, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам тебе́ но́ваго моли́твенника і помо́щника, похва́льноє воспіва́єм ті пі́ніє: ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Влади́ці небесе́ і землі́, от вся́ких неду́гов душе́вних і тіле́сних свободи́ нас і до́брі стоя́ти в Правосла́вії укріпи́, да всі во умиле́нії зове́м ті:","Ра́дуйся, святи́телю Кри́мський іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Молитва","ps":["О, всеблаже́нний іспові́дниче, Святи́телю о́тче наш Луко́, вели́кий уго́дниче Христо́в! Со умиле́нієм прекло́ньше колі́на серде́ць на́ших, і припа́дая к ра́ці честни́х і многоціле́бних моще́й твої́х, я́коже ча́да отця́ мо́лим тя всеусе́рдно: усли́ши нас, грі́шних, і принеси́ моли́тву на́шу к Ми́лостивому і Человіколю́бцю Бо́гу, Єму́же ти ни́ні в ра́дості святи́х і с ли́ки а́нгел предстої́ши. Ві́руєм бо, я́ко ти лю́биши ни то́ю же любо́вію є́юже вся бли́жнія возлюби́л єси́, пребива́я на землі́.","Іспроси́ у Христа́ Бо́га на́шего да утверди́ть во Святі́й Своє́й Правосла́вній Це́ркві дух пра́вия ві́ри і благоче́стія: па́стирям Єя́ да дасть святу́ю ре́вность і попече́ніє о спасе́нії вві́ренних їм люде́й: пра́во ве́рующия соблюда́ти, сла́бия і немощни́я во ві́рі укріпля́ти, неве́дущия наставля́ти, проти́вния облича́ти. Всім нам пода́й дар коєму́ждо благопотре́бен, і вся я́же к жи́зні вре́менній і к ві́чному спасе́нію поле́зная. Градо́в на́ших утвержде́ніє, землі́ плодоно́сіє, от гла́да і па́губи ізбавле́ніє. Скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, заблу́дшим на путь і́стини возвраще́ніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, си́рим і убо́гим по́мощ і заступле́ніє.","Пода́ждь нам всім твоє́ архипа́стирськоє і свято́є благослове́ніє, да тобо́ю осіня́ємі ізба́вимся от ко́зней лука́ваго і ізбі́гнем вся́кия вражди́ і нестроє́ній, єресе́й і раско́лов.","Да́руй нам богоуго́дно прейти́ по́прище вре́менной жи́зні, наста́ви нас на путь веду́щий в селе́нія пра́ведних, ізба́ви нас возду́шних мита́рств і моли́ о нас всеси́льнаго Бо́га, да во ві́чній жи́зні с тобо́ю непреста́нно сла́вим Отця́ і Си́на і Свята́го Ду́ха, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Возвісти́телю путі́ спаси́тельнаго, / іспові́дниче непоколеби́мий, / і́стинний храни́телю оте́чеських преда́ній, / Правосла́вія наста́вниче, / Кри́мськия землі́ архіпа́стирю, / врачу́ богому́дрий, святи́телю Луко́, / Христа́ Спа́са непреста́нно моли́, // дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 1","ps":["Я́коже звізда́ всесві́тлая, / в нощі́ безбо́жия доброді́тельми просія́л єси́, / і от гони́телей мно́го пострада́в, / непоколеби́м ві́рою преби́л єси́, / враче́бною же му́дростію укра́шен, / мно́гия лю́ди ісціли́л єси́. / Сего́ ра́ди с любо́вію вопіє́м ті: / ра́дуйся, добропобі́дний іспові́дниче, / ра́дуйся, о́тче святи́телю Луко́, // ра́дуйся, землі́ Ру́ськия похвало́ і утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм тя, іспові́дниче Христо́в святи́телю о́тче наш Луко́, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Антонію Сійському","e":"Akathist to our Venerable Father Anthony of Siya","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго вождя́ і́ноков, ізря́днаго учи́теля подви́жников, доброді́тельми я́ко цві́ти украси́вшася, чудеси́ же, я́ко луча́ми со́лнечними, сія́юща, восхваля́єм тя с любо́вію, преподо́бне. Ти же, предстоя́ престо́лу Пресвяти́я Тро́йці, іспроси́ нам оставле́ніє гріхо́в і ізбавле́ніє от всіх бід і зол; да житіє́ неблажненно і безм'яте́жно теку́ще, благода́рні зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Ікос 1","ps":["А́нгелов ревни́тель от ю́ности показа́лся єси́, преподо́бне; рожде́йся во убозей ві́си, я́ко граждани́н небе́снаго Ієрусали́ма ходи́л єси́; прост сий земледі́лець, первозва́нному апо́столов тезоімени́ть і подража́тель бил єси́; Христу́ послі́дуя, мно́гі ученики́ собра́л єси́. Сего́ ра́ди зове́м ті:","Ра́дуйся, рожде́нієм ра́дость, я́ко пе́рвенець, роди́телем пода́вий.","Ра́дуйся, і на небесі́х благослове́ніє перворо́дних наслі́дивий.","Ра́дуйся, ю́ности бу́єсть ізді́тська отложивий.","Ра́дуйся, слове́сноє млеко́ Боже́ственних писа́ній, па́че ма́терня, вожделі́вий.","Ра́дуйся, в душеполе́зних уче́ніїх све́рстники своя́ превозше́дий.","Ра́дуйся, благоче́стієм і ра́зумом наста́вники удиви́вий.","Ра́дуйся, я́ко ізмла́да сказа́нія о святи́х і жи́тельство їх возлюби́л єси́.","Ра́дуйся, я́ко ра́но уразумі́л і презрі́л єси́ суєту́ благ вре́менних.","Ра́дуйся, я́ко дом Бо́жий па́че о́тча ізбра́л єси́.","Ра́дуйся, я́ко ізді́тська нави́кл єси́ пісносло́вити Го́спода.","Ра́дуйся, я́ко о́браз Созда́теля на дсках живописуя, ясні́йшеє подо́біє Єго́ на скрижа́ліх се́рдця твоєго́ вообрази́л єси́.","Ра́дуйся, я́ко от ю́ности в се́рдці твоє́м к небе́сним восхожде́нія положи́л єси́.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 2","ps":["Ви́дяще близ кончи́ну живота́ своєго́, благові́рнії роди́теліє твої́ с моли́твою преда́ша тя і бра́тію твою́ Го́сподеві. Сего́ ра́ди і по сме́рті їх не позна́л єси́ себе́ си́ра, но со благодаре́нієм возопи́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом і іспита́нієм коне́чні позна́л єси́ суєту́ привре́менния сла́дости; дости́гнув же в мі́ру во́зраста в му́жа соверше́нна, подо́бно подвигополо́жнику своєму́, яви́вшему себі́ ми́рові, три́десяти літ вдал єси́ себе́ в слу́жбу Го́сподеві; оста́вив мир і вся, я́же в нем, прия́л єси́ о́браз а́нгельський. Таково́є у́бо ізволе́ніє твоє́ восхваля́юще, глаго́лем:","Ра́дуйся, я́ко на распу́тіїх ми́ра сего́ обрі́л єси́ пра́вий путь в Ца́рствіє Небе́сноє.","Ра́дуйся, я́ко оста́вив дом отця́ своєго́ водвори́лся єси́ в до́му Госпо́дні.","Ра́дуйся, до́брий ра́бе, я́ко бил єси́ ві́рен Влади́ці твоєму́.","Ра́дуйся, я́ко уже́ ні́си раб, но син і наслі́дник Бо́жий.","Ра́дуйся, я́ко і в супру́жестві, ка́ко угоди́ти Го́сподеві, помишля́л єси́.","Ра́дуйся, я́ко в і́ночестві всеці́ло Го́сподеві себі́ пре́дал єси́.","Ра́дуйся, я́ко вожделі́нія пло́ті обузда́л єси́.","Ра́дуйся, я́ко плоть ду́хові покори́л єси́.","Ра́дуйся, я́ко разда́в імі́нія своя́, ни́щия уще́дрил єси́.","Ра́дуйся, я́ко нището́ю бога́тство нетлі́нноє стяжа́л єси́.","Ра́дуйся, я́ко убі́гл єси́ собла́знов ми́ра і сіте́й дия́вола.","Ра́дуйся, го́рлице пустиннолю́бная, історгнувшаяся от сі́ті ло́вчі.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 3","ps":["Си́ла Боже́ственная я́ві укріпи́ тя, обнощевавша за п'ять поприщ до святи́я оби́телі Пахо́мія; єгда́ бо в со́ннім виді́нії кресто́м осіни́ тя ста́рець святолепен, реки́й ті: возьми́ крест твой і гряди́ вслід мене́, не боя́ся ко́зней дия́волих; ти, в ра́дості воста́в от сна, всю нощ моли́лся єси́ Го́сподеві, благода́рні воспіва́я: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й се́рдце угото́вано в слу́жбу Го́сподеві, Сего́ пречи́стому о́бразу со слеза́ми ра́дости і благодаре́нія поклони́лся єси́ во враті́х тоя́ оби́телі, в ню́же все́лься, не солга́л єси́ Свято́му Ду́ху, но па́че всіх рабо́тал єси́ Го́сподеві. Сего́ ра́ди зове́м ті:","Ра́дуйся, я́ко препоя́сался єси́ с висоти́ си́лою.","Ра́дуйся, я́ко крі́пці ополчи́лся єси́ проти́ву пло́ті, ми́ра і дия́вола.","Ра́дуйся, я́ко приі́скренні прине́слся єси́ Бо́гові.","Ра́дуйся, я́ко сраспя́лся єси́ Христу́.","Ра́дуйся, я́ко сла́дці поне́сл єси́ бре́м'я Єго́.","Ра́дуйся, я́ко смире́нієм украси́лся єси́.","Ра́дуйся, я́ко вся, я́же на землі́, мудрова́нія отри́нул єси́.","Ра́дуйся, я́ко по́стничеськими труди́ Бо́гу угоди́л єси́.","Ра́дуйся, я́ко глаго́ли Боже́ственними ду́шу напита́л і укріпи́л єси́.","Ра́дуйся, я́ко бо́дренною моли́твою і псалмопі́нієм дух твой окрилил єси́.","Ра́дуйся, я́ко бді́нії всено́щними і хране́нієм се́рдця угото́вал єси́ себе́ к зрі́нію невече́рняго сві́та.","Ра́дуйся, я́ко о́браз житія́ і́ночеськаго бил єси́.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 4","ps":["Бу́рю душегубительну непщу́я би́ти сла́ву челові́чу, із оби́телі в пусти́ню удали́лся, іді́же храм воздви́гл єси́, і та́мо седьм літ непреста́нними труди́, моли́твами і пости́ благоугождал єси́ Бо́гові, немо́лчно воспіва́я: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав молву́ і преще́нія окре́стних жи́телей, пом'яну́в єси́ словеса́ Христо́ва, біжа́ти от гоня́щих ни, і сквозі́ непрохо́дния де́бри приве́л єси́ ученики́ твоя́ ко є́зеру, іді́же обрі́теся мі́сто, за мно́га лі́та в жили́ще і́ноком назнаменанноє, і посреді́ де́брей, блать і єзе́р с ди́віїми звірми́ всели́лся єси́. Сего́ ра́ди взива́єм ті:","Ра́дуйся, смиренному́дрієм вся́ку ра́спрю погаси́вий.","Ра́дуйся, кро́тостію зло́бу побіди́вий.","Ра́дуйся, любо́вію вражду́ отмстивий.","Ра́дуйся, необита́ємая мі́ста моли́твою освяти́вий.","Ра́дуйся, безмо́лвния де́бри Боже́ственними пі́снми огласи́вий.","Ра́дуйся, в непроходи́мих стезі́ бла́гі обріти́й.","Ра́дуйся, в напа́стіх і іскуше́ніїх терпі́нія і упова́нія не погуби́вий.","Ра́дуйся, спу́тники твоя́ в терпі́нії укріпи́вий.","Ра́дуйся, в непра́веднім ізгна́нії, вхо́ди Ца́рства Небе́снаго обріти́й.","Ра́дуйся, дре́во плодоно́сно, при вода́х насажде́нноє.","Ра́дуйся, финиче, процвіти́й в пусти́ні.","Ра́дуйся, я́ко кедр, і́же от Лива́на, возвели́чивийся.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́ водя́й спу́тники твоя́ на мі́сто, іді́же пе́рвіє водрузи́л єси́ Крест Госпо́день, і сле́зно моли́лся єси́ Влади́ці Христу́, сохрани́ти тя от враг ви́димих і неви́димих, і утверди́ти в терпі́нії нести́ крест свой і пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя неви́димих враго́в прило́ги, отгонял єси́ тіх, под'ємля ру́ці на моли́тву в труді́х і по́двизіх непреста́нних, ди́віїми то́чію зелії пита́лся єси́; а́лчущия же ученики́ твоя́, не іми́й хлі́ба, словеси́ Боже́ственними насищал і укріпля́л єси́, до́ндеже ні́кто, мимоходя́й, подаде́ ті вся потре́бная к препита́нію і строє́нію оби́телі. Сицево́му у́бо смотре́нію Бо́жию, я́коже і ві́рі твоє́й див'я́щеся, ра́достно вопіє́м ті:","Ра́дуйся, безси́ліє те́мних сил обличи́вий.","Ра́дуйся, си́лу моли́тви побіди́тельну показа́вий.","Ра́дуйся, ві́ру непоколеби́му стяжа́вий.","Ра́дуйся, упова́ніє неотло́жно сохрани́вий.","Ра́дуйся, любо́в нелицемі́рну і безкористну соблюди́й.","Ра́дуйся, вся́ко жите́йськоє попече́ніє отложивий.","Ра́дуйся, вся́ку печа́ль на Го́спода возвергий.","Ра́дуйся, терпі́нієм во іскуше́ніїх, му́жество необори́мо яви́вий.","Ра́дуйся, му́дрий строї́телю, не на песці́, а на тве́рді ка́мені зи́ждяй.","Ра́дуйся, я́ко нищ бив Го́спода ра́ди, дово́лен бил єси́ мно́гі боголю́бці собра́ти і препита́ти.","Ра́дуйся, нічто́же іми́й, вся содержа́й.","Ра́дуйся, в промишле́нії любве́ Бо́жия, істо́чник вся́каго дово́льства неізсякающ обріти́й і іни́м яви́вий.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 6","ps":["Пропові́дник святи́ні твоєя́, преподо́бне, яви́ся враг твой, єди́н от приста́вник к собира́нію да́ней; он бо, непщу́я тя іму́ща стяжа́нія мно́га, ная́ть разбо́йники расхи́тити оби́тель твою́, но не возмо́же озло́бити ю, наро́да ра́ди, со ору́жії обстояща ю; уві́дівий же, я́ко не челові́ки, но Си́ли Небе́сними охраняєшися, при но́гу твоє́ю раска́яся о злі, прося́й проще́нія. Ти же незло́бив сий, с любо́вію отпусти́в єго́, воспі́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко звізда́ сві́тлая, луча́ми святи́ні озаря́я Украї́ну; сла́ва доброді́телей твої́х промче́ся по всім градо́м, привлача́щи мно́гія во оби́тель твою́. І цар, посла́в тебі́ грамоту, да стро́їши пусти́нноє жи́тельство, предаде́ себе́ і ца́рство своє́ твої́м богоприя́тним моли́твам, і́миже огражда́єми зове́м ті:","Ра́дуйся, украї́нських царе́й предста́телю.","Ра́дуйся, Оте́чествія твоєго́ храни́телю.","Ра́дуйся, світи́льниче, горя́й любо́вію і світя́й святи́нею.","Ра́дуйся, воєво́до полка́ і́ночеськаго.","Ра́дуйся, пра́вий води́телю і́щущих спасе́нія.","Ра́дуйся, си́лою Бо́жиєю ізимаяй із плі́на гріхо́внаго.","Ра́дуйся, свобожда́й от рабо́ти су́єтния.","Ра́дуйся, мно́гія ко́зні лука́ваго по́мощію Бо́жиєю побіди́вий.","Ра́дуйся, ісполня́яй ду́ші сла́достей духо́вних.","Ра́дуйся, істоча́яй то́ки сле́зния із серде́ць окамененних.","Ра́дуйся, воздія́нієм ру́ку твоє́ю, спаса́яй нас от нападе́ній ми́сленнаго Амали́ка.","Ра́дуйся, преводя́й благопокори́вия ті в зе́млю, святи́м обітова́нную.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 7","ps":["Хотя́й насища́ти словеси́ Боже́ственними і пі́снми духо́вними со́бранноє тобо́ю ста́до, созда́л єси́ храм Живонача́льния Тро́йці, і неопи́санний о́браз Трієди́наго Божества́ потща́лся єси́ вообрази́ти на іко́ні, споспішеству́ющу ті самому́ Го́споду, Єму́же в пості́ і моли́тві рабо́тал єси́, вопія́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до яви́ Госпо́дь, ізнесий неви́димою руко́ю честну́ю іко́ну із горя́щия це́ркве і невреди́му ю поста́вивий посреді́ оби́телі; ти же, ра́дуяся, приє́м ю, с упова́нієм на Го́спода, но́вий пространнейший дом Пресвяті́й Тро́йце воздви́гл єси́, і іни́я хра́ми назда́л єси́, і та́ко оби́тель благоустроїл єси́, ю́же і ни́ні огражда́єши моли́твами твої́ми, спаса́яй вопію́щия ті:","Ра́дуйся, я́ко твої́ми моли́твами но́вий істо́чник благода́ті Бо́жия отве́рзеся.","Ра́дуйся, я́ко іко́на Пресвяти́я Тро́йці, тобо́ю начерта́нная, чудеси́ просла́вися.","Ра́дуйся, я́ко в пусти́ні оби́тель благоче́стія процвіте́.","Ра́дуйся, я́ко тобо́ю приста́нище благоотишно душа́м угото́вася.","Ра́дуйся, я́ко тобо́ю учи́лище покая́нія устро́їся.","Ра́дуйся, я́ко тобо́ю откри́ся путь хотя́щим к по́чести ви́шняго зва́нія тещи́.","Ра́дуйся, я́ко тобо́ю лі́ствиця духо́вних восхожде́ній утверди́ся.","Ра́дуйся, я́ко і́щущим спасе́нія от пото́па гріхо́внаго нов кора́бль тобо́ю іспра́вися.","Ра́дуйся, я́ко во оби́телі твоє́й ісціля́ються неду́ги душ і тіле́с.","Ра́дуйся, дая́й прибі́жище цілому́дрію, по́стничеству і во́льній нищеті́.","Ра́дуйся, я́ко і́щущії твоєго́ предстателства, при́сно ми́лость Бо́жию обріта́ють.","Ра́дуйся, я́ко прия́л єси́ благода́ть моли́тися о всіх.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 8","ps":["Стра́нная чудеса́ во оби́телі твоє́й сотвори́ Госпо́дь своє́ю іко́ною, ю́же із пла́мене чу́дно спа́се; то́чію бо прикосну́ся к ней усти́ слуга́ ні́кий, а́біє свободи́ся от ду́ха зла́го. І́ний слуга́, положе́н бив пред не́ю, ізба́вися падучія болі́зні; і сестра́ ієре́я, слі́па су́щи, а́біє прозрі́, єгда́ облобиза́ше чудотво́рний о́браз Пресвяти́я Тро́йці. Сего́ ра́ди і ми Пресвяті́й Тро́йце вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь собо́р і́нок єдва́ возмо́же преклони́ти смире́ніє твоє́ к прия́тію ігу́менства; є́же приє́мь, ди́вен настоя́тель бил єси́, пе́рвенствуя в труді́х і́ночеських, я́ко мній всіх і раб всім показу́яся, ру́бищем покрива́я себі́, смире́нним же зра́ком утаєва́я оби́ліє благода́ті і бога́тство святи́ні. Сего́ ра́ди при́снії ра́довахуся, прише́льці же не мня́ху тя нача́лника би́ти, ми же уми́льні зове́м ті:","Ра́дуйся, я́ко мній мня́йся би́ти, ве́лій у Го́спода сла́ви вміни́лся єси́.","Ра́дуйся, я́ко уча́ і́ни твори́ти, вся пе́рвіє сам сотвори́л єси́.","Ра́дуйся, я́ко нощ не премо́же твоєго́ бді́нія.","Ра́дуйся, до́брий стра́же до́ма Бо́жия.","Ра́дуйся, я́ко в зра́ці твоє́м при́сно явля́шеся трезві́ніє ума́ твоєго́.","Ра́дуйся, пра́вило ві́ри і о́браз смире́нія.","Ра́дуйся, я́ко тягчайшия рабо́ти люботру́дні со всі́ми разділя́л єси́.","Ра́дуйся, я́ко боля́щим усе́рдно послужи́л єси́.","Ра́дуйся, я́ко стра́нния ввел і ни́щия препита́л єси́.","Ра́дуйся, я́ко не́мощі немощни́х терпіли́вно поне́сл єси́.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 9","ps":["Вся́ку сла́ву і честь а́ще і пра́ведне тебі́ воздаєму от челові́к, непщу́я би́ти вино́вну лише́нія сла́ви Бо́жия, пре́дал єси́ власть твою́ єди́ному от учени́к твої́х, і со єди́ним от них та́йно отше́л єси́ во о́стров єди́н, іді́же вдал єси́ себе́ непреста́нній моли́тві, трудо́м і поще́нію, бо́дренно воспіва́я Го́сподеві: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я ди́вен бил єси́, при́сно от се́рдця іспо́лнена любве́ глаго́ляй і помишле́нія челові́чеськая ду́хом прови́дяй, єди́наго от учени́к твої́х предвари́в, наста́вил єси́ не отлага́ти обі́ти і́ночеськия ра́ди мирськи́я пре́лести; і уті́шив єго́ словеси́ Писа́нія, возбрани́л єси́ зло́му по́мислу возврати́тися в се́рдці єго́. Сего́ ра́ди зове́м ті:","Ра́дуйся, ізря́днійший врачу́ духо́вний.","Ра́дуйся, ві́рний наста́вниче умо́в заблу́ждших.","Ра́дуйся, серде́ць м'ятущихся упокоїтелю.","Ра́дуйся, злих начина́ній разори́телю.","Ра́дуйся, благи́х помисло́в насади́телю.","Ра́дуйся, святи́х жела́ній внушителю.","Ра́дуйся, разсла́бленния во́лі укріпи́телю.","Ра́дуйся, іскуше́ній і собла́знов ізба́вителю.","Ра́дуйся, от прило́гов дия́волих защити́телю.","Ра́дуйся, уни́лих і отчаявающихся уті́шителю.","Ра́дуйся, усипленних со́вістей возбудителю.","Ра́дуйся, путе́й покая́нія і спасе́нія му́дрий сказа́телю.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щії стужа́ху ті, приходя́ще в пусти́нную ке́ллію твою́; сего́ ра́ди далеча́йше в дебр отбі́гл єси́, і во глубині́ гор, а́ки в коно́бі, водвори́лся єси́, і тягчайшия по́двиги под'ял єси́, презрі́в страхова́нія де́монов і обнажи́в до чресл ті́ло мши́цям, в моли́тві терпі́л єси́, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю крі́пкою і опло́том надежним бил єси́ оби́телі твоє́й, єгда́ возврати́лся єси́ в ню ко ученико́м твої́м, разсі́ятися хотя́щим, і до́брі пасл єси́ ста́до твоє́; уста́ бо твоя́, я́ко сот мед, іска́паху словеса́ благода́ті, зрак же твой явля́ше кро́тость і любо́в о́тчу, сіди́на ізві́ствоваше му́дрость ума́ і чистоту́ се́рдця, согбенний вид твой, ста́рче Бо́жий, подоб'яше тя дре́ву, кра́сних плодо́в оби́лієм до́лу преклоне́ну. Сего́ ра́ди зове́м ті:","Ра́дуйся, красото́ Це́ркве Христо́ви.","Ра́дуйся, сосу́де святи́ні.","Ра́дуйся, цві́те і́ночества.","Ра́дуйся, світи́лниче ми́рові.","Ра́дуйся, кра́сноє зда́ніє благода́ті Христо́ви.","Ра́дуйся, преукраше́нний храм Свята́го Ду́ха.","Ра́дуйся, но́вий о́бразе Бо́жий.","Ра́дуйся, подо́біє Христо́во.","Ра́дуйся, дража́йший кораблю́, внося́й в приста́нище неісчетна сокро́вища духо́вная.","Ра́дуйся, купе́ць, приумноживий вданниє ті от Бо́га тала́нти.","Ра́дуйся, ві́рний приста́вниче до́му Бо́жия.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє Го́сподеві соверши́вшим ученико́м твої́м, в пра́здник боголі́пнаго Преображе́нія Христо́ва предложи́л єси́ во сла́ву Бо́жию ве́ліє і чу́дно учрежде́ніє на трапе́зі, я́коже і Госпо́дь сотвори́; повелі́л єси́ рибаре́м, обно́щ всу́є труждавшимся о лови́тві риб, па́ки воврещи́ мре́жу во є́зеро, і я́коже предре́кл єси́ їм, ізвлеко́ша мно́жество вели́ких і разли́чних риб, я́ко всім диви́тися, і ди́вному во святи́х Бо́гу воспі́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную жизнь скончава́я, (седьми́десяти дев'яти́ літ) ста́рець сий, я́ко оте́ць чадолюби́в, вся смотрителне устро́їл єси́ во оби́телі твоє́й. Ученики́ твоя́, о скорем преставле́нії твоє́м скорб'я́щия, наста́вил і уті́шил єси́; уста́ви общежи́тія писа́нієм утверди́л єси́, і вмі́сто себе́ іно́го ігу́мена наре́кл єси́; сам же во бді́нії і моли́тві не вкуси́л єси́ поко́я, до́ндеже Го́сподеві пре́дал єси́ святу́ю ду́шу твою́. Ученици́ же твої́, возвра́щшеся із хра́ма і ви́дівше тя бездиха́нна лежа́ща, ру́ці же я́ко моля́щуся при пе́рсіх іму́ща, со слеза́ми возопи́ша:","Ра́дуйся, благи́й наш о́тче, зряй ни́ні Отця́ сві́тов.","Ра́дуйся, па́стирю наш до́брий, предстоя́й ни́ні пастиреначалнику Христу́.","Ра́дуйся, пита́телю наш, сла́достьми небе́сними насищаяйся.","Ра́дуйся, покрови́телю наш, во кро́віх небе́сних водворивийся.","Ра́дуйся, предста́телю наш пред Бо́гом, а́нгельськая зряй утіше́нія.","Ра́дуйся, сожи́телю святи́м небожителем.","Ра́дуйся, граждани́не го́рняго Ієрусали́ма.","Ра́дуйся, свяще́нная главо́, вінча́нная от Царя́ сла́ви.","Ра́дуйся, зри́телю Триіпоста́снаго Сві́та.","Ра́дуйся, ві́дче боже́ственних та́їн.","Ра́дуйся, на ло́ні любве́ Бо́жия упокоївийся.","Ра́дуйся, ра́достей ра́ди небе́сних, вся́ку болі́знь і печа́ль коне́чні заби́вий.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 12","ps":["Благода́ті сосу́д честно́є ті́ло твоє́, не дерзну́ша ученици́ твої́, по глаго́лу твоєму́, ізврещи́ в дебр на растерза́ніє звіре́м, іли́ обі́сити на стіні́ в снідь пти́цям іли́ потопи́ти во є́зері; но пра́ведно разори́ша завіща́ніє твоє́, благоче́стне поло́жше мо́щі твоя́ во хра́мі Живоначалния Тро́йці і гробни́цю твою́ украси́вше святи́ми іко́ни, по всяк ве́чер усе́рдно стека́хуся пі́ти над не́ю надгро́бная: Аллилу́я."]},{"h":"Ікос 12","ps":["Пі́ти вся чудеса́ твоя́ не возмо́жем, мно́га бо зіло́ ди́вная сотвори́л єси́ і по сме́рті твоє́й. Сего́ ра́ди ві́руєм, я́ко ни́ні на небесі́х живе́ши, і приноси́мая тебі́ пі́нія ми́лостивно приє́млеши, і па́че дерза́єм глаглати:","Ра́дуйся, боже́ственний врачу́, вся́ку болі́знь і вся́ку я́зю ско́ро ісціля́яй.","Ра́дуйся, разсла́бленния возставля́яй.","Ра́дуйся, і малоду́шния утвержда́яй.","Ра́дуйся, сліпи́я ви́діти творя́й.","Ра́дуйся, і помраче́нния уми́, сми́сленни ді́яй.","Ра́дуйся, і неві́рующия ві́ровати науча́яй.","Ра́дуйся, упова́ющия спаса́яй.","Ра́дуйся, із гріхо́вния бе́здни із'ємляй.","Ра́дуйся, от наси́лія де́монськаго свобожда́яй.","Ра́дуйся, к самоубийству теку́щия восп'ящаяй.","Ра́дуйся, па́че наде́жди по́мощ подава́яй.","Ра́дуйся, і не звавшим тя, я́ко зван, благовре́менні помога́яй.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 13","ps":["О преди́вний чудотво́рче і вели́кий уго́дниче Христо́в, преподо́бне о́тче Анто́ніє, предстоя́й ни́ні престо́лу Пресвяти́я Тро́йці, прийми́ от нас грі́шних приноси́мая ті хвале́бная пі́нія і моли́твами твої́ми іспроси́ нам у Го́спода отпуще́ніє гріхо́в, ізбавле́ніє от бід вре́менних і спасе́ніє от мук ві́чних, да с тобо́ю ви́ну Трийпоста́сному Бо́гу воспіва́єм: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ревни́тель от ю́ности показа́лся єси́, преподо́бне; рожде́йся во убозей ві́си, я́ко граждани́н небе́снаго Ієрусали́ма ходи́л єси́; прост сий земледі́лець, первозва́нному апо́столов тезоімени́ть і подража́тель бил єси́; Христу́ послі́дуя, мно́гі ученики́ собра́л єси́. Сего́ ра́ди зове́м ті:","Ра́дуйся, рожде́нієм ра́дость, я́ко пе́рвенець, роди́телем пода́вий.","Ра́дуйся, і на небесі́х благослове́ніє перворо́дних наслі́дивий.","Ра́дуйся, ю́ности бу́єсть ізді́тська отложивий.","Ра́дуйся, слове́сноє млеко́ Боже́ственних писа́ній, па́че ма́терня, вожделі́вий.","Ра́дуйся, в душеполе́зних уче́ніїх све́рстники своя́ превозше́дий.","Ра́дуйся, благоче́стієм і ра́зумом наста́вники удиви́вий.","Ра́дуйся, я́ко ізмла́да сказа́нія о святи́х і жи́тельство їх возлюби́л єси́.","Ра́дуйся, я́ко ра́но уразумі́л і презрі́л єси́ суєту́ благ вре́менних.","Ра́дуйся, я́ко дом Бо́жий па́че о́тча ізбра́л єси́.","Ра́дуйся, я́ко ізді́тська нави́кл єси́ пісносло́вити Го́спода.","Ра́дуйся, я́ко о́браз Созда́теля на дсках живописуя, ясні́йшеє подо́біє Єго́ на скрижа́ліх се́рдця твоєго́ вообрази́л єси́.","Ра́дуйся, я́ко от ю́ности в се́рдці твоє́м к небе́сним восхожде́нія положи́л єси́.","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Кондак 1","ps":["Ізбра́ннаго вождя́ і́ноков, ізря́днаго учи́теля подви́жников, доброді́тельми я́ко цві́ти украси́вшася, чудеси́ же, я́ко луча́ми со́лнечними, сія́юща, восхваля́єм тя с любо́вію, преподо́бне. Ти же, предстоя́ престо́лу Пресвяти́я Тро́йці, іспроси́ нам оставле́ніє гріхо́в і ізбавле́ніє от всіх бід і зол; да житіє́ неблажненно і безм'яте́жно теку́ще, благода́рні зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Анто́ніє."]},{"h":"Молитва","ps":["О преди́вний чудотво́рче і вели́кий уго́дниче Бо́жий, преподо́бне о́тче Анто́ніє, па́стирю наш до́брий, те́плий засту́пниче і ско́рий помо́щниче; предстоя́й престо́лу Пресвяти́я Тро́йці, при́зри ми́лостивим о́ком на ни і на вся лю́ди, благогові́йні притека́ющия к честно́му гро́бу твоєму́, в не́мже лежа́щия святи́я мо́щі твоя́, от дній дре́вніх нетлі́нієм цвіту́щия і благода́тію Животворя́щаго Пресвята́го Ду́ха благоуха́ющия, ісціле́нія от вся́ких неду́гов душе́вних і тіле́сних неоску́дно істоча́ють. Усли́ши нас моля́щихся тебі́ і чту́щих святу́ю па́м'ять твою́. Простри́ ру́ці твої́ ко Влади́ці небесе́ і землі́, стра́ждущую страну́ Украї́нськую от лю́тих безбо́жник і вла́сті їх да свободи́ть, і да возста́вить престо́л правосла́вних царе́й, ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш, і іспроси́ нам оставле́ніє прегріше́ній на́ших. Моли́ ми́лостиваго Бо́га отврати́ти от нас вся́кий гнів Єго́, пра́ведно на ни дви́жимий і сохрани́ти не то́чію оби́тель на́шу, но і вся гра́ди і ві́си, і вся страни́ христия́нськия, і лю́ди живу́щия в них от гра́да і гла́да, от тру́са і пото́па, от огня́ і меча́, от наше́ствія іноплеме́нних і междоусо́бния бра́ні, от смертоно́сния я́зви і вся́кия па́губи і вся́каго зла, дарова́ти же нам вся к жи́зні вре́менній благопотре́бная і к ві́чному спасе́нію поле́зная. Помози́ нам, свя́тче Бо́жий, ізбіжа́ти па́губних сіте́й дия́волих, препобіди́ти собла́зни ми́ра і умертви́ти у́ди на́ша су́щия на землі́; отврати́ о́чі на́ші от су́єтних і преле́стних веще́й земни́х, напра́ви же уми́ і ми́слі на́ша к зрі́нію красо́т боже́ственних, пренебе́сних і нетлі́нних; се́рдця на́ша, неду́гующая страстьми́ гріхо́вними, ісціли́, да не прильпну́ть сласте́м привре́менним, і безмі́стним; согрі́й же я боже́ственною любо́вію, да вожделі́ють і́стиннаго і непреходя́щаго блаже́нства, є́же в Бо́зі. Укріпи́ нас ко ісполне́нію за́повідей Госпо́дніх, даждь нам покая́ніє серде́чноє і умиле́ніє сле́зноє, моли́тву непреста́нную і трудолю́біє неосла́бноє, бо́дренноє трезві́ніє ума́ і хране́ніє се́рдця, мир помисло́в, чистоту́ жела́ній, правоту́ дія́ній, да ізба́вльшеся тобо́ю от всіх враг ви́димих і неви́димих, от вся́ких зол душе́вних і тіле́сних, і соблю́дше ві́ру пра́вую, наде́жду неотло́жную і любо́в нелицемі́рную, богоуго́дні сконча́єм житіє́ на́ше на землі́, і преше́дше в жизнь ві́чную, сподо́бимся зрі́ти трисві́тлую зарю́ трисія́ющаго ві́чнаго Со́лнця, і в невече́рнім дні Небе́снаго Ца́рствія, ку́пно с тобо́ю і со всі́ми святи́ми, благода́рні воспіва́ти і благослови́ти Пресвяту́ю Тро́йцю, Отця́ і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О богоблаже́нне і приснопа́м'ятне о́тче наш Анто́ніє! Не мним тя ме́ртва су́ща, а́ще ті́лом і преста́вился єси́ от нас, но жив в собо́рі а́нгелов водворя́єшися. Моли́ за ни, ізбра́нниче Христо́в, і не пре́зри нас ві́рою і любо́вію чту́щих тя, помина́й нас недосто́йних у престо́ла Царя́ Небе́снаго, тебі́ бо даде́ся благода́ть моли́тися за ни. О, засту́пниче і моли́твенниче наш до́брий! Се бо святи́х моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть, сохраня́й у́бо нас всегда́ от сіте́й вра́жиїх; моли́ся ко Го́споду о спасе́нії душ на́ших і іспроси́ нам покая́нія вре́м'я і христия́нськую кончи́ну безболі́зненну, непости́дну, ми́рну, да невозбра́нно пре́йдем мита́рства возду́шних князе́й і сподо́бимся Небе́снаго Ца́рствія со всі́ми угоди́вшими Влади́ці не́ба і землі́, Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Жела́нієм духо́вним распали́вся / і м'яте́жи мирськи́я отри́нув, / ко єди́ному же Бо́гу любо́вію приліпи́лся єси́, / і, Того́ вседу́шні взиску́я, / во вну́треннюю пусти́ню отше́л єси́, при вода́х всели́вся, / іді́же во слеза́х і труді́х пребива́я многолі́тноє вре́м'я, / в терпі́нії мно́зім житіє́ а́нгельськоє проходи́л єси́, / в наставле́нії Боже́ственнаго ра́зума: / і мно́жество мона́хов собра́л єси́, му́дре, / ї́хже посіща́я не оста́ви, Анто́ніє преподо́бне о́тче наш, / Пресвяті́й Тро́йце моля́ся // от зол вся́чеських ізба́вити і спасти́ ду́ші на́ша."]},{"h":"Інший тропар, глас 6","ps":["І́же воі́стину на землі́ тя А́нгела / і на Небесі́ челові́ка Бо́жия почти́м, / сію́ жизнь су́єтную оста́вль, / я́ко воі́стину преудо́брен во́їн Христа́ Бо́га, / на стра́сті душепа́губния подвиза́вся в жи́зні сей су́єтній / бді́нієм і поще́нієм, / во всем бив о́браз свої́м ученико́м. / Ті́мже бо в тя всели́ся Пресвяти́й Дух, / Єго́же ді́йствієм сві́тло укра́шен, / но я́ко імі́я дерзнове́ніє ко Святі́й Тро́йці, / помина́й святу́ю оби́тель сію́ / і ста́до своє́, є́же собра́, му́дре, / і не забу́ди, я́коже обіща́ся, / посіща́й чад свої́х, // Анто́ніє преподо́бне, о́тче наш."]},{"h":"Кондак, глас 8","ps":["От ю́ности, преподо́бне, плоть твою́ в пості́х і моли́твах істончи́л єси́ / і крест твой взем, Христу́ послі́довал єси́, / ті́мже і к Ви́шнім тече́ніє ра́достно соверши́л єси́, / іді́же со всі́ми святи́ми Святі́й Тро́йці предстої́ши; / і ни́ні ста́до твоє́ посіща́я, / помина́й чту́щих пресвяту́ю па́м'ять твою́, / да всі благода́рні вопіє́м ті: // ра́дуйся, Богому́дре Анто́ніє, наста́вниче пусти́нний."]},{"h":"Інший кондак, глас 3","ps":["Христа́ єди́наго вожделі́в, / і к Тому́ любо́вію уязви́вся, / і Тому́ неотло́жним путе́м послі́довал єси́. / Вся́коє жите́йськоє наслажде́ніє возненави́дів, / ті́мже, я́ко второ́є со́лнце, чудеси́ сія́я, / і сего́ ра́ди тя да́ром обогати́ Влади́ка, / помина́й нас, чту́щих пресві́тлую па́м'ять твою́, да зове́м ті: // ра́дуйся, Анто́ніє, преподо́бне о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Анто́ніє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст великомученику Євстафію Плакіді","e":"Akathist to the Great Martyr Eustathius Placidas","secs":[{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді, к ли́ку святи́х сопричтенному, свято́му Євста́фію Плакиде пі́сні похва́льния прино́сим ни́ні. Ти же, великому́чениче, огне́м муче́ній в поко́й небе́сний вше́дий, от огня́ страсте́й і вся́ких нас бід свободи́, со упова́нієм тебі́ зову́щих:","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгелов Влади́ка і челові́ков Творе́ць хотя́й всім спасти́ся і в ра́зум і́стини прийти́, в ди́внім о́бразе яви́ся тебі́, Євста́фіє, єгда́ над главо́ю єле́ня Крест і на нем подо́біє расп'я́таго за ни Го́спода Ісу́са Христа́ узрі́л єси́. Ти же глас Христо́в: «Почто́ го́ниши М'я, Плакидо?» во ізумленії сли́шав, в стра́сі вопроша́л єси́: «Кто Ти, Го́споди, ко мні реки́й?» І уві́дів, я́ко Той єсть Ісу́с Христо́с, прише́дий грі́шния спасти́, і́стинним Бо́гом Того́ іспові́дал єси́. Ми же, таково́му твоєму́ обраще́нію к ві́рі і́стинній чудя́щеся, взива́єм си́це:","Ра́дуйся, із среди́ нечести́вих Го́сподем ізведе́нний.","Ра́дуйся, на путь спаси́тельний Їм наста́вленний.","Ра́дуйся, всім се́рдцем Творця́ возлюби́вий.","Ра́дуйся, огнь страсте́й в себі́ угаси́вий.","Ра́дуйся, я́ко за і́м'я Сладча́йшаго Ісу́са страда́нія ве́лія претерпі́л єси́.","Ра́дуйся, я́ко ві́рен Єму́ да́же до сме́рти лю́тия преби́л єси́.","Ра́дуйся, вінце́м му́ченичеським главу́ свою́ украси́вий.","Ра́дуйся, ра́йськія сла́дости со святи́ми вкуси́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь се́рдця твоєго́ чистоту́ і ве́ліє милосе́рдіє ко всім бедствующим і стра́ждущим, не оста́ви тя во мра́кі ідолослуже́нія пребива́ти, оба́че сві́том ві́ри Христо́ви тя просвіти́, да, позна́в і́стиннаго Бо́га, со всі́ми пра́ведними воспоє́ши Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́н імі́я і гла́сом Боже́ственним сви́ше наста́вленний, свя́те Євста́фіє, я́ко му́драя глава́ до́му своєму́, ко спаси́тельній ві́рі і свято́му Креще́нію приве́л єси́ вся живу́щия в нем. Сего́ ра́ди восхваля́єм тя, глаго́люще:","Ра́дуйся, і́стину Боже́ственную возлюби́вий.","Ра́дуйся, ми́лостиню Христа́ ра́ди творивий.","Ра́дуйся, о́браз житія́ пра́веднаго нам показу́яй.","Ра́дуйся, ра́ни гріхо́вния іску́сно врачу́яй.","Ра́дуйся, я́ко ві́рних к прославле́нію Го́спода воздвиза́єши.","Ра́дуйся, я́ко любве́ к Бо́гу і бли́жнім нас науча́єши.","Ра́дуйся, сладкогла́сний Христо́в пропові́дниче.","Ра́дуйся, Го́рняго Ца́рствія со святи́ми наслі́дниче.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния любве́ укріпля́ємі, святі́ї му́ченици Євста́фіє і Феопистіє, со смире́нієм і терпі́нієм вся біди́ і напа́сти претерпі́ли єсте́, упова́ніє своє́ на єди́наго Го́спода возлага́я, с ві́рою пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи в се́рдці своє́м жела́ніє Єди́ному Го́споду ві́рно служи́ти, дом твой оста́вил єси́, Євста́фіє, і по мо́рю во Єги́пет со всім семейством устреми́лся єси́. Таково́му смире́нію твоєму́ і упова́нію на Про́мисл Бо́жий див'я́щеся, прино́сим ті похвали́ сицеви́я:","Ра́дуйся, я́ко нас ра́ди обнища́вшему Го́сподеві уподо́бился єси́.","Ра́дуйся, я́ко подража́яй Свято́му Сіме́йству, во Єги́пет біжа́л єси́.","Ра́дуйся, ві́ру ве́лію во Христа́ в се́рдці своє́м імі́вий.","Ра́дуйся, вся ско́рбі му́жественно претерпі́вий.","Ра́дуйся, су́щим в ну́ждах і ско́рбіх ско́рий помо́щниче.","Ра́дуйся, душ на́ших до́брий наста́вниче.","Ра́дуйся, Крест Христо́во в се́рдці своє́м начерта́вий.","Ра́дуйся, безро́потним несенієм креста́ своєго́ путь спаси́тельний нам показа́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю лю́тих гоне́ній і бід воздви́же на тя враг ро́да челові́чеськаго, великому́чениче Євста́фіє: ти же, я́ко І́ов Многострада́льний, вся лише́нія низпосилаємия тебі́, безро́потно приє́мля, укреплявшему тя Бо́гу взива́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь моли́тви твоя́ к Нему́ возноси́мия, по́мощ і утіше́ніє ми́лостиво подава́ше тебі́, Євста́фіє; ти же, любо́вію к Бо́гу і бли́жнім распаля́яся, скорб о лише́нії супру́жници і чад свої́х со смире́нієм і кро́тостію претерпіва́л єси́, за вся Бо́га благодаря́ще. Ми же, таково́му твоєму́ терпі́нію удивля́яся, со умиле́нієм воспіва́єм ті:","Ра́дуйся, ві́ри непоколеби́мий сто́лпе.","Ра́дуйся, христия́н несокруши́мий щиті́.","Ра́дуйся, неоскудіва́ємоє чуде́с сокро́вище.","Ра́дуйся, неісчерпа́ємий ісціле́ній істо́чниче.","Ра́дуйся, я́ко ві́рних во благоче́стії укріпля́єши.","Ра́дуйся, я́ко вся ско́рбі со смире́нієм претерпіва́ти науча́єши.","Ра́дуйся, вмісти́лищем дарова́ній Бо́жиїх на землі́ би́вий.","Ра́дуйся, доброді́тельним житіє́м Ца́рствіє Небе́сноє стяжа́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю, приводящею к позна́нію житія́ смиренному́дреннаго показа́лся єси́, великому́чениче Євста́фіє: в страні́ чужде́й мно́гія лі́та, доблестний воєво́да сий, в услуженії господи́ну своєму́ во смире́нії пребива́л єси́, непреста́нно поя́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще ві́ру, терпі́ніє і благодаре́ніє твоє́ за вся, досточу́дне Євста́фіє, умиля́ємся і, чту́ще любо́вію святу́ю па́м'ять твою́, вопіє́м ті си́це:","Ра́дуйся, земна́го оте́чествія му́жественний защи́тниче.","Ра́дуйся, небе́сних селе́ній досто́йний наслі́дниче.","Ра́дуйся, я́ко Го́спода Помо́щником ви́ну імі́л єси́.","Ра́дуйся, я́ко житія́ твоєго́ за дру́ги своя́ не щади́л єси́.","Ра́дуйся, пред Бо́гом наш те́плий хода́таю.","Ра́дуйся, о душа́х на́ших ско́рий предста́телю.","Ра́дуйся, у Престо́ла Бо́жия о нас усе́рдно моля́йся.","Ра́дуйся, о призива́ющих і́м'я твоє́ непреста́нно пеки́йся.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дник ві́ри во Христа́ сло́вом і ді́лом яви́лся єси́, святи́й му́чениче, доброді́тельним житіє́м свої́м мно́гія ідолопокло́нники сві́том і́стини Христо́ви просвіща́я і і́стинному Бо́гу пі́ти всіх науча́я: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ ра́дости ве́лія, Го́сподем ми́лостивно тебі́ ниспосланния, Євста́фіє сла́вне, єгда́ по мно́зіх лі́тіх семе́йство твоє́ па́ки вку́пі соєдини́ся. Воспіва́я ди́вноє Промишле́ніє Бо́жиє, на тебі́ і сро́дниціх твої́х явле́нноє, зове́м ті:","Ра́дуйся, благоче́стієм твої́м Христу́ угоди́вий.","Ра́дуйся, ве́ліє дерзнове́ніє к Нему́ стяжа́вий.","Ра́дуйся, сугу́бия благода́ті от Царя́ сла́ви сподо́бивийся.","Ра́дуйся, вінце́м му́ченичеським от него́ вінча́нний.","Ра́дуйся, Святи́я Це́ркви би́сере драги́й.","Ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, бога́тства ми́ра сего́ ні во что́же вміни́вий.","Ра́дуйся, от Го́спода небе́сную сла́ву улучи́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́й нечести́вий Адрія́н же́ртву і́долом принести́, повелі́ ті, Євста́фіє, сим поклони́тися, мня́ше бо, я́ко ті́ї тебі́ побі́ду на враги́ дарова́ша; ти же отвіща́л єси́ єму́, я́ко христия́нин єси́ і єди́ному і́стинному Бо́гу – Ісу́су Христу́ ві́рно покланя́єшися, ви́ну воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зло показа́ служи́тель врага́ ро́да челові́чеськаго Адрія́н, єгда́ в безумнем гні́ві своє́м повелі́ тя с жено́ю і ча́ди твої́ми на растерза́ніє звіре́м преда́ти; оба́че не возмо́же вре́да вам сотвори́ти: зві́ріє бо лю́тії кротції соді́лашася, благода́тію Бо́жиєю усмиряємі. Сего́ ра́ди, прославля́я Го́спода, ди́внаго во святи́х Свої́х, с любо́вію вопіє́м ті:","Ра́дуйся, іспові́данієм Бо́га і́стиннаго нечести́вия посрами́вий.","Ра́дуйся, преще́нія мучи́теля ні во что́же вміни́вий.","Ра́дуйся, і́дольськаго служе́нія іскорени́телю.","Ра́дуйся, христия́нськаго благоче́стія насади́телю.","Ра́дуйся, пре́лесть бісо́вськую обличи́вий.","Ра́дуйся, по́двиг му́ченичеський до́брі соверши́вий.","Ра́дуйся, ду́шу свою́, во є́же спасти́ ю, Христа́ ра́ди погуби́вий.","Ра́дуйся, во Ца́рствії Небе́снім наслі́діє со святи́ми улучи́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нно бі ви́діти і сли́шати неверующим во Христа́ і неві́дущим си́ли Бо́жия, ка́ко в немощні́м челові́честім тілесі́ такови́я муки́ за Христа́ претерпіва́ти возмо́жно: бил бо єси́, многострада́льне Євста́фіє, по повелі́нію нечести́ваго іге́мона, вве́ржен с супру́жницею і ча́дами в раскаленнаго мі́днаго вола́, в не́мже ви, муки́ тя́жкия претерпіва́я, воспіва́ли єсте́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ра́дости боже́ственния іспо́лнился єси́, святи́й му́чениче, і, любо́вію ко Христу́ Го́споду го́ря, на смерть за і́м'я Христо́во му́жественні поте́кл єси́. Ми же, страда́нія твоя́ і при́сних твої́х воспомина́юще і ве́ліє терпі́ніє ва́ше похваля́юще, глаго́лем:","Ра́дуйтеся, і́стиннаго Бо́га пропові́дници.","Ра́дуйтеся, те́плії к Бо́гу моли́твенниці.","Ра́дуйтеся, ві́рою крі́пкою Христу́ послі́довавшії.","Ра́дуйтеся, сме́ртію му́ченичеською Христо́ві спогребшіїся.","Ра́дуйтеся, в ра́дость Го́спода своєго́ вше́дшії.","Ра́дуйтеся, скорбми́ мно́гими живо́т ві́чний наслі́довавшії.","Ра́дуйтеся, я́ко ра́йськія две́рі вам отверзо́шася.","Ра́дуйтеся, я́ко в селе́ніїх пра́ведних на ві́ки водворишася.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Ви́дівше ві́рнії, я́ко тілеса́ ва́ша, му́ченици всехва́льнії, невреди́ми во огні́ обріто́шася, восхвали́ша Бо́га, прославля́ющаго святи́я Своя́, і припа́дающе ко святи́м моще́м ва́шим, піснь надгро́бную воспі́ша: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть досто́йния похвали́ ізрещи́ вам, святі́ї му́ченици, і позна́ти си́лу Христо́ву, є́юже ви, я́ко броне́ю облеко́шася. Ми же, похваля́я по́двиги страда́ній ва́ших, ї́хже за ві́ру Христо́ву му́жественні претерпі́ли єсте́, воспіва́єм вам такова́я:","Ра́дуйся, Євста́фіє, семе́йств благочести́вих укріпле́ніє.","Ра́дуйся, дома́шнія це́ркві утвержде́ніє.","Ра́дуйся, Феопистіє, жен і ма́терей похвало́.","Ра́дуйся, бра́ка христия́нськаго дияди́мо.","Ра́дуйся, Ага́піє, роди́телей доброді́тельних утіше́ніє.","Ра́дуйся, цілому́дреннаго житія́ украше́ніє.","Ра́дуйся, Феописте, с при́сними твої́ми на пир Госпо́день призва́нний.","Ра́дуйся, с ни́ми Царе́м сла́ви вінце́м му́ченичеським увінча́нний.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Хотя́й Госпо́дь Ісу́с Христо́с просла́вити вас, святі́ї му́ченици Євста́фіє, Феопистіє, Ага́піє і Феописте, внуши́ свято́му Константи́ну це́рков на мі́сті му́ченичеськия кончи́ни ва́шея созда́ти, да всі притека́ющії к многоціле́бним моще́м ва́шим, по́мощ ско́рую от вас воспри́ймуть, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну заступле́нія от вся́ких бід і напа́стей, обрі́тше вас, всехва́льнії му́ченици, Отцю́ Небе́сному благодаре́ніє усе́рдно возсила́єм за вся благодія́нія Єго́, ва́ми нам, недосто́йним, явля́ємая; вам же, те́плим моли́твенником на́шим, сицево́є прино́сим пі́ніє:","Ра́дуйтеся, Це́ркви Христо́ви столпи́ непоколеби́мії.","Ра́дуйтеся, любо́вію Христо́вою соєдиненнії.","Ра́дуйтеся, А́нгелов Бо́жиїх на небесі́х собесі́дниці.","Ра́дуйтеся, призива́ющих вас на землі́ ско́рії помо́щници.","Ра́дуйтеся, Ца́рствія Христо́ва надежнії нам хода́таї.","Ра́дуйтеся, те́плії о нас к Бо́гу предста́теліє.","Ра́дуйтеся, і по сме́рті ва́шей нас не оставля́ющії.","Ра́дуйтеся, на путі́ спасе́нія нас руководствующії.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє, ни́ні на́ми приноси́моє, приймі́те, му́ченици святі́ї, ви бо, в же́ртву благоуха́нную Го́сподеві себі́ прине́сши, воспіва́ли єсте́ єму́ до послі́дняго іздиха́нія ва́шего піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рния зві́зди яви́лися єсте́ на не́бі церковнім, му́ченици всехва́льнії, среди́ ко́їх і ти, Євста́фіє всехва́льне, сві́тло сія́єши; сего́ ра́ди прийми́ от нас похвали́ сія́:","Ра́дуйся, я́ко сла́ву Трисія́ннаго Божества́ лице́м к лицю́ зри́ши.","Ра́дуйся, я́ко і нам сві́том Боже́ственния і́стини просвіти́тися тщи́шися.","Ра́дуйся, ві́рния на путь спасе́нія направля́яй.","Ра́дуйся, грі́шния на покая́ніє наставля́яй.","Ра́дуйся, я́ко моща́ми твої́ми чудеса́ істоча́єши.","Ра́дуйся, я́ко в хра́міх, созда́нних на прославле́ніє і́мене твоєго́, незри́мо обита́єши.","Ра́дуйся, стра́нствующих неви́димий спутниче.","Ра́дуйся, всіх призива́ющих тя ско́рий помо́щниче.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, ві́дуще, страстоте́рпче Христо́в Євста́фіє, с благогові́нієм і любо́вію покланя́ємся многоціле́бним моще́м твої́м, от ни́хже в неду́зіх ісціле́ніє і в ско́рбіх утіше́ніє приє́млем: ті́мже і по достоя́нію прославля́єм тя, засту́пника на́шего небе́снаго, воспіва́я о тебі́ Го́сподеві: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая і пресла́вная чудеса́ твоя́, великому́чениче Євста́фіє, ублажа́єм тя ку́пно с супру́жницею і ча́ди твої́ми, я́ко засту́пников і моли́твенников на́ших пред Бо́гом, і мо́лим тя: бу́ди нам во всем ко бла́гу помо́щник, усе́рдно взивающим ті:","Ра́дуйся, му́чеников висо́кая похвало́.","Ра́дуйся, іспові́дников многопі́тая сла́во.","Ра́дуйся, разли́чния болі́зні ісціля́яй.","Ра́дуйся, в неду́зіх облегче́ніє да́руяй.","Ра́дуйся, братолю́бія наста́вниче.","Ра́дуйся, покая́нія пропові́дниче.","Ра́дуйся, с небе́с на нас призира́яй.","Ра́дуйся, неви́димо нам помога́яй.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О всехва́льний великому́чениче Христо́в Євста́фіє, прийми́ от нас похвали́ сія́, с любо́вію тебі́ приноси́мия, і предста́тельством твої́м у Престо́ла Го́спода Вседержи́теля іспроси́ нам от всіх неду́г душе́вних і тіле́сних, от враг ви́димих і неви́димих і мук ві́чних ізбавле́ніє, да ку́пно с тобо́ю в бу́дущем ві́ці воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Влади́ка і челові́ков Творе́ць хотя́й всім спасти́ся і в ра́зум і́стини прийти́, в ди́внім о́бразе яви́ся тебі́, Євста́фіє, єгда́ над главо́ю єле́ня Крест і на нем подо́біє расп'я́таго за ни Го́спода Ісу́са Христа́ узрі́л єси́.Ти же глас Христо́в: «Почто́ го́ниши М'я, Плакидо?» во ізумленії сли́шав, в стра́сі вопроша́л єси́: «Кто Ти, Го́споди, ко мні реки́й?» І уві́дів, я́ко Той єсть Ісу́с Христо́с, прише́дий грі́шния спасти́, і́стинним Бо́гом Того́ іспові́дал єси́. Ми же, таково́му твоєму́ обраще́нію к ві́рі і́стинній чудя́щеся, взива́єм си́це:","Ра́дуйся, із среди́ нечести́вих Го́сподем ізведе́нний.","Ра́дуйся, на путь спаси́тельний Їм наста́вленний.","Ра́дуйся, всім се́рдцем Творця́ возлюби́вий.","Ра́дуйся, огнь страсте́й в себі́ угаси́вий.","Ра́дуйся, я́ко за і́м'я Сладча́йшаго Ісу́са страда́нія ве́лія претерпі́л єси́.","Ра́дуйся, я́ко ві́рен Єму́ да́же до сме́рти лю́тия преби́л єси́.","Ра́дуйся, вінце́м му́ченичеським главу́ свою́ украси́вий.","Ра́дуйся, ра́йськія сла́дости со святи́ми вкуси́вий.","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нному воєво́ді, к ли́ку святи́х сопричтенному, свято́му Євста́фію Плакиде пі́сні похва́льния прино́сим ни́ні. Ти же, великому́чениче, огне́м муче́ній в поко́й небе́сний вше́дий, от огня́ страсте́й і вся́ких нас бід свободи́, со упова́нієм тебі́ зову́щих:","Ра́дуйся, великому́чениче Євста́фіє, моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["О пресла́вний, святи́й і многострада́льний великому́чениче Христо́в Євста́фіє! Усли́ши нас грі́шних і недосто́йних, святу́ю па́м'ять твою́ пра́зднующих. Іспроси́ нам у Го́спода многомо́щними моли́твами твої́ми благода́ть, я́же ко спасе́нію, і всіх гріхо́в, соді́янних на́ми, проще́ніє, землі́ благопло́діє, ми́ру ми́рноє устроє́ніє і от лю́тих дия́вольських ко́зней свобожде́ніє, христия́нськую кончи́ну житія́ на́шего і нем'яте́жноє чрез возду́шния мита́рства к небесі́ прехожде́ніє, ти бо прия́л єси́ благода́ть сію́ от Го́спода, є́же моли́тися за ни, і а́ще восхо́щеши по́мощи нам, почита́ющим свяще́нную па́м'ять твою́, вся мо́жеши сотвори́ти. Не пре́зри у́бо нас, недосто́йних, страстоте́рпче святи́й, і іспроси́ от Го́спода вся блага́я і поле́зная душа́м на́шим, я́ко да і ми сподо́бимся сла́вити і воспіва́ти всесвято́є і великолі́поє і́м'я Єго́ во преми́рном Ца́рствії Небе́снім, іді́же єсть всіх святи́х жили́ще, во ві́ки віко́в. Амі́нь."]},{"h":"Кондак, глас 2","ps":["Стра́сті Христо́ви я́ві подража́в / і Сего́ іспи́в усе́рдно ча́шу, / о́бщник, Євста́фіє, і сла́ви снаслі́дник бил єси́, / от Сама́го всіх Бо́га // приє́мля с висоти́ боже́ственноє оставле́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й Євста́фіє, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст преподобному Антонію Великому","e":"Akathist to our Venerable Father Anthony the Great","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, преподо́бне о́тче Анто́ніє, любо́вію восхваля́юще богоуго́дноє житіє́ твоє́, благодаре́нія піснь о тебі́ Бо́гу прино́сим. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Ікос 1","ps":["А́нгельськоє житіє́ от ю́ности возлюби́вши, в за́повідіх Бо́жиїх ходи́ти вожделі́л єси́, преподо́бне о́тче, і се́рдцем пламені́я ко Го́споду сил, ум на Боже́ственная возве́л єси́, вре́менная і земна́я во уме́ти вміня́я. Ті́мже, промишле́нію Бо́жию о тебі́ див'я́щеся, с ві́рою зове́м ті:","Ра́дуйся, благочести́вих роди́телей си́не досто́йний.","Ра́дуйся, во благоче́стії і́ми воспита́нний.","Ра́дуйся, от ю́ности за Христо́м послі́довавий.","Ра́дуйся, суєту́ земну́ю ні во что́же вміни́вий.","Ра́дуйся, вертогра́да Христо́ва ді́лателю усе́рдний.","Ра́дуйся, пустиножителей наста́вниче вели́кий.","Ра́дуйся, спасе́нія всім жела́вий.","Ра́дуйся, путь і́стиннаго мона́шества показа́вий.","Ра́дуйся, світи́льниче, огне́м Боже́ственним возжже́нний.","Ра́дуйся, ка́меню ві́ри во Христа́ несокрушенний.","Ра́дуйся, благода́тію Ду́ха Свята́го осія́нний.","Ра́дуйся, да́ром чудотворе́ній облагода́тствованний.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 2","ps":["Ви́дя враг ро́да челові́чеськаго тебі́, богоно́сне о́тче, на висоту́ духо́вную возне́сшагося, восхоті́ погуби́ти тя, но устиди́ся усе́рдія і смире́нія твоєго́, ти бо непреста́нно в пості́ і моли́тві подвиза́лся єси́, главу́ неви́димаго змі́я сокруша́я, Бо́гу же со умиле́нієм поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́вше се́рдцем і умо́м, я́ко вся блага́я ми́ра сего́ скоротечни і скоропреходящия суть, в пеще́рі те́мній затвори́л єси́ себе́, стра́сті умерщвля́я і єди́ному Го́сподеві рабо́тая. Сего́ ра́ди, похваля́я равноа́нгельноє житіє́ твоє́, вопіє́м ті:","Ра́дуйся, упова́ніє своє́ на Бо́га возложи́вий.","Ра́дуйся, врага́ безу́міє посрами́вий.","Ра́дуйся, неустраши́мий разруши́телю ко́зней дия́вольських.","Ра́дуйся, чистото́ю і святи́нею А́нгелом уподо́бивийся.","Ра́дуйся, пусти́ню по́двиги твої́ми освяти́вий.","Ра́дуйся, мно́гія в Ца́рствіє Небе́сноє упра́вивий.","Ра́дуйся, презренную го́рдость низлага́яй.","Ра́дуйся, смиренному́дрію науча́яй.","Ра́дуйся, сві́те, всіх богому́дрієм просвіща́яй.","Ра́дуйся, лучеза́рная звіздо́, сія́нієм по́двигов твої́х всіх озаря́яй.","Ра́дуйся, во сла́ву Бо́жию пожи́вий.","Ра́дуйся, па́стирю до́брий і долготерпіли́вий.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго укріпля́ше тя, Анто́ніє преблаже́нне, ти бо в пості́, моли́тві, неустанних труді́х і бді́ніїх пребива́я і вся́кия вра́жия іскуше́нія побіжда́я, воспіва́л єси́ благода́тію покривавшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і ду́шу непоро́чну, блаже́нне о́тче, уразумі́л єси́ ми́ра сего́ суєту́ і непостоя́нство, і ві́чних благ вожделі́в, благ вре́менних отре́клся єси́. Ті́мже, ублажа́юще тя, вопіє́м:","Ра́дуйся, смире́нія блага́го ревни́телю.","Ра́дуйся, му́дрости духо́вния іска́телю.","Ра́дуйся, на висоту́ безстра́стія возше́дий.","Ра́дуйся, всего́ себе́ Бо́гу преда́вий.","Ра́дуйся, Го́споду твоєму́ незло́бієм уподо́бивийся.","Ра́дуйся, нището́ю твоє́ю бога́ть би́вий.","Ра́дуйся, пусти́ні благода́тноє украше́ніє.","Ра́дуйся, ми́рові світи́льниче пресві́тлий.","Ра́дуйся, бісо́в стра́шний прогони́телю.","Ра́дуйся, пре́лести їх потреби́телю.","Ра́дуйся, па́че мудрецо́в ми́ра сего́ мудрі́йший.","Ра́дуйся, подви́жниче всеусе́рднійший.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 4","ps":["Бу́рю злих напа́стей утиша́я, в пусти́ню всели́лся єси́, Анто́ніє преблаже́нне, в не́йже многоскорбний путь і́ночеськаго житія́ проше́л єси́, вся ко́зні вра́жеськия попира́я і прельще́нія єго́ отсіка́я, укріпля́ющему тя Христу́ поя́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о богоуго́дном житії́ твоє́м, преподо́бне, прихожда́ху к тебі́ от всіх конце́в і́щущії пра́вди Бо́жия, ї́хже ти с любо́вію приє́мля, ко спасе́нію руково́дствовал єси́. Ми же, умиле́нною душе́ю восхваля́я тя, вопіє́м си́це:","Ра́дуйся, пустинножи́телей пра́вило і основа́ніє.","Ра́дуйся, до́брий стада́ Христо́ва наста́вниче.","Ра́дуйся, Це́ркви Христо́ви украше́ніє.","Ра́дуйся, мона́шествующих сла́во.","Ра́дуйся, всего́ себе́ в же́ртву Го́сподеві принеси́й.","Ра́дуйся, стра́сті гріхо́вния в себі́ умертви́вий.","Ра́дуйся, А́нгелов весе́ліє.","Ра́дуйся, де́монов всегуби́тельноє попра́ніє.","Ра́дуйся, пусти́нний жи́телю.","Ра́дуйся, безмо́лвія рачи́телю.","Ра́дуйся, на путь пра́вий наставля́яй.","Ра́дуйся, Ца́рствіє Небе́сноє возвіща́яй.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ чи́ну і́ночеському яви́лся єси́, преподо́бне о́тче Анто́ніє, о́браз бив сло́вом, житіє́м, любо́вію, ві́рою, чистото́ю, воспіва́я Го́споду: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя враг ро́да челові́чеськаго чи́стоє і свято́є житіє́ твоє́, о́тче Анто́ніє, мно́гажди ополчашеся на тя: ти же смире́нієм свої́м єго́ побіжда́я, от путі́ спаси́тельнаго не уклони́лся єси́. Ми же, ві́дуще сіє́, поє́м ті:","Ра́дуйся, ві́чния жи́зні прича́стниче.","Ра́дуйся, спасе́нія вели́кий наста́вниче.","Ра́дуйся, житіє́м твої́м єди́ному Бо́гу послужи́вий.","Ра́дуйся, і́го Христо́во восприя́вий.","Ра́дуйся, кова́рство лука́вих де́монов облича́яй.","Ра́дуйся, на путь спасе́нія наставля́яй.","Ра́дуйся, чистоти́ храни́телю.","Ра́дуйся, Тро́їчеськаго сві́та зри́телю.","Ра́дуйся, па́дших воста́ніє.","Ра́дуйся, бісо́вськия си́ли прогна́ніє.","Ра́дуйся, сто́лпе ві́ри утвержде́нний.","Ра́дуйся, учи́телю соверше́нний.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 6","ps":["Про́повіді Єва́нгельськия послу́шав: «А́ще хо́щеши соверше́н би́ти, іди́, прода́ждь імі́ніє твоє́, і даждь ни́щим, і імі́ти і́маши сокро́вище на небесі́; і гряди́ в слід Мене́», отріши́л єси́ себе́, о́тче Анто́ніє, от бога́тств земни́х і, всели́вся в пусти́ню, житіє́ по́стничеськоє пожи́л єси́, по́двиги твої́ми сокро́вище себе́ на небесі́ стяжава́я. Вразуми́ і нас, о́тче благосе́рдий, к скорогибнущим веще́м земни́м се́рдцем не приліпля́тися, а па́че о го́рніх помишля́ти, вопія́ Го́споду сил: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко богосві́тлоє світи́ло, в пусти́ні Єги́петстій, о́тче Анто́ніє, озаря́я всіх луча́ми доброді́телей і чуде́с твої́х. Ми же, помина́я по́двиги твоя́, ублажа́єм тя, глаго́люще:","Ра́дуйся, і́мже вінча́ються преподо́бнії.","Ра́дуйся, і́мже спаса́ються челові́ци.","Ра́дуйся, благода́тноє боля́щих посіще́ніє.","Ра́дуйся, лю́ті стра́ждущих помо́щниче.","Ра́дуйся, вражди́ разруши́телю.","Ра́дуйся, враго́в істребителю.","Ра́дуйся, ві́рним мир і утвержде́ніє.","Ра́дуйся, ско́роє от бід ізбавле́ніє.","Ра́дуйся, зло́би і кова́рства губи́телю.","Ра́дуйся, отча́янних посіти́телю.","Ра́дуйся, правосла́вним побо́рниче.","Ра́дуйся, христия́ном помо́щниче.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 7","ps":["Хотя́й досто́йні по́двигом до́брим подвиза́тися, вся вре́менная во уме́ти вміни́л єси́, і нищ і убо́г пребива́я, в пусти́ню всели́лся єси́, да с єди́ним Бо́гом бесі́дуєши, непреста́нно поя́ Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго воі́стину наста́вника мона́хов яви́ тя Госпо́дь, о́тче Анто́ніє: мно́зі бо позна́вше богоуго́дноє і пра́ведноє житіє́ твоє́, і висо́кую му́дрость духо́вную уразумі́вше, послу́шаху слове́с твої́х, я́ко слове́с вели́каго уго́дника Бо́жия, єму́же досто́їть пі́ти такова́я:","Ра́дуйся, ві́рі Авраа́ма подража́вий.","Ра́дуйся, кро́тостію Дави́ду уподо́бивийся.","Ра́дуйся, ре́вность Іліїну́ стяжа́вий.","Ра́дуйся, стезя́ми Крести́теля послі́довавий.","Ра́дуйся, во́ду в пусти́ні моли́твою істочи́вий.","Ра́дуйся, разсла́бленния от одра́ болі́зні воздви́гнувий.","Ра́дуйся, сліпи́м прозрі́ніє дарова́вий.","Ра́дуйся, мно́гія боля́щия ісціли́вий.","Ра́дуйся, наста́вниче мона́хов преди́вний і богому́дрий.","Ра́дуйся, Христа́ Бо́га служи́телю усе́рдний.","Ра́дуйся, прети́хоє ско́рбних утіше́ніє.","Ра́дуйся, прелюби́моє і́ноков похвале́ніє.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 8","ps":["Стра́нноє і пачеєсте́ственноє житіє́ преподо́бнаго Па́вла ви́дів, блаже́нне Анто́ніє, диви́лся єси́ висоті́ по́двигов і доброделей єго́. Ду́шу же єго́, А́нгели окружаєму, на небеса́ восходя́щую узрі́вши, Бо́гу, ди́вному во святи́х Свої́х, возгласи́л єси́: Аллилу́я."]},{"h":"Ікос 8","ps":["Ра́достію ве́лією возра́довался єси́, о́тче Анто́ніє, ви́дяще восхожде́ніє на не́бо душі́ преподо́бнаго Аммонія, єго́же прозорли́вима очи́ма зрел єси́. Сего́ ра́ди со мно́гим удивле́нієм взива́єм ті си́це:","Ра́дуйся, очеса́ своя́ ви́ну на не́бо возводи́вий.","Ра́дуйся, сла́ву небе́сную па́че всего́ возлюби́вий.","Ра́дуйся, непреста́нними моли́твами се́рдце своє́ освяти́вий.","Ра́дуйся, мисль твою́ в Бо́зі утверди́вий.","Ра́дуйся, гряду́щая я́ко настоя́щая прови́дівий.","Ра́дуйся, смире́нієм твої́м висо́кая дарова́нія стяжа́вий.","Ра́дуйся, стужа́ємия от злих духо́в свободи́телю.","Ра́дуйся, душе́внаго і тіле́снаго здра́вія пода́телю.","Ра́дуйся, в ну́ждах і біда́х пресла́вний засту́пниче.","Ра́дуйся, в напа́стіх і ско́рбіх ско́рий защи́тниче.","Ра́дуйся, я́ко нас, на землі́ су́щих, не оставля́єши.","Ра́дуйся, я́ко о нас, грі́шних, мольби́ Бо́гу прино́сиши.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся висоті́ по́двигов твої́х, преподо́бне, я́ко в немощні́й челові́честій пло́ті сий, по всему́ уподо́бился єси́ А́нгелом і, си́лою Ви́шняго укріпля́єм, во вся́ких доброді́теліх дово́льні ізобиловал єси́. Сего́ ра́ди а́нгельським чинам причте́н, поє́ши Всеси́льному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть к досто́йному прославле́нію житія́ твоєго́, о́тче Анто́ніє: кто бо іспові́сть вся поще́нія і бді́нія, болі́зні і труди́ твоя́? Кто ізочте́ть сле́зи і воздиха́нія твоя́ я́же к Бо́гу? Оба́че ми, любо́вію к тебі́ подвиза́ємі, дерза́єм воспіва́ти си́це:","Ра́дуйся, вели́кий пустинножи́телю.","Ра́дуйся, соверше́нства учи́телю.","Ра́дуйся, і́стиннаго Бо́га служи́телю.","Ра́дуйся, бісо́в із пусти́ні прогони́телю.","Ра́дуйся, гро́ме, дия́вола поража́яй.","Ра́дуйся, кова́рство єго́ ізоблича́яй.","Ра́дуйся, благода́ті Бо́жия вмісти́лище.","Ра́дуйся, Ду́ха Свята́го обита́лище.","Ра́дуйся, по́стников украше́ніє.","Ра́дуйся преподо́бних похвало́.","Ра́дуйся, мона́хов основа́ніє.","Ра́дуйся, отце́в сла́во.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим ві́рний наста́вник бил єси́, преподо́бне, і ни́ні нам, грі́шним, спасе́нія желающим, помози́ святи́ми твої́ми моли́твами, да тобо́ю вспомоществу́ємі, дости́гнем Ца́рствія Небе́снаго, іді́же А́нгели немо́лчно пою́ть: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая і необори́мая бил єси́ свої́м ученико́м, сохраня́я їх от стріля́ній бісо́вських, і ни́ні нам бу́ди стіна́ і покро́в от всіх ко́зней дия́вольських вопію́щих ті такова́я:","Ра́дуйся, а́нгеле земни́й.","Ра́дуйся, челові́че небе́сний.","Ра́дуйся, святи́ні чи́стоє і честно́є жили́ще.","Ра́дуйся, вели́ких доброді́телей вмісти́лище.","Ра́дуйся, благоче́стія ревни́телю.","Ра́дуйся, єресе́й обличи́телю.","Ра́дуйся, любве́ Христо́ви ісполне́ніє.","Ра́дуйся, і́ноков науче́ніє.","Ра́дуйся, тве́рдоє ві́рних прибі́жище.","Ра́дуйся, крі́пкоє па́дающих возведе́ніє.","Ра́дуйся, укріпле́ніє немощни́х і разсла́бленних.","Ра́дуйся, утіше́ніє унива́ющих і безнаде́жних.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє, от любві́ і усе́рдія в похвалу́ тебі́ от нас возноси́моє, прийми́, благоутро́бне о́тче Анто́ніє, приклони́ся к нам ми́лостиво і в покая́нії преуспі́ти сподо́би, да моли́твами твої́ми ви́ну поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Светоприємний світи́льник і́стиннаго Сві́та су́щим на землі́ яви́лся єси́, преподо́бне Анто́ніє, просвіща́єши бо се́рдця ві́рних по́двиги твої́ми і чудеси́, наставля́я на путь добродетельного і богоуго́днаго житія́. Ті́мже сли́шиши от всіх такова́я:","Ра́дуйся, наста́вниче прему́дрий.","Ра́дуйся, вождю́ благонаде́жний.","Ра́дуйся, всего́ себе́ во́лі Бо́жієй преда́вий.","Ра́дуйся, Го́спода Ісу́са па́че всего́ возлюби́вий.","Ра́дуйся, терпі́нієм скорбе́й многоразли́чних просія́вий.","Ра́дуйся, во́льною нището́ю ві́чноє бога́тство стяжа́вий.","Ра́дуйся, в терпі́нії і злострада́нії житіє́ твоє́ проводивий.","Ра́дуйся, пусти́нноє озлобле́ніє му́жеськи терпі́вий.","Ра́дуйся, ліни́вих к по́двигом возбудителю.","Ра́дуйся, ісправле́нія грі́шников поручителю.","Ра́дуйся, А́нгелов і всіх святи́х собесі́дниче.","Ра́дуйся, о всем ми́рі усе́рдний моли́твенниче.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 12","ps":["Благода́ть да́нную Ті от Бо́га ві́дуще, благогові́йно лобиза́єм святолі́пноє ізображе́ніє ли́ка твоєго́, уго́дниче Бо́жий, і мо́лимся: не оста́ви нас твої́м моли́твенним предста́тельством ко Христу́ Бо́гу, Єму́же благода́рно поє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ житіє́, восхваля́єм ми́рную кончи́ну твою́, преподо́бне о́тче Анто́ніє, і мо́лим ті ся: бу́ди нам во всем ко бла́гу ско́рий помо́щник, зовущим ті такова́я:","Ра́дуйся, небе́сний жи́телю.","Ра́дуйся, Тро́йці Єдиносу́щния предстоя́телю.","Ра́дуйся, А́нгелов весе́ліє.","Ра́дуйся, святи́х собесі́дниче.","Ра́дуйся, і́стинний уго́дниче Бо́жий.","Ра́дуйся, ізбра́нний слуго́ Госпо́день.","Ра́дуйся, те́плий хода́таю о всіх призива́ющих і́м'я твоє́.","Ра́дуйся, наста́вниче і упова́ніє почита́ющих тя.","Ра́дуйся, благода́тію Бо́жиєю насище́нний.","Ра́дуйся, от істо́чника Боже́ственнаго напоє́нний.","Ра́дуйся, пото́ком слез спаси́тельних орошенний.","Ра́дуйся, оде́ждою нетлі́нія оді́янний.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 13","ps":["О преподо́бне о́тче наш Вели́кий Анто́ніє, ві́чно живи́й в невече́рнім дні Ца́рствія Христо́ва, умоли́ всіх Влади́ку ізба́витися нам от бід, скорбе́й і ві́чнаго муче́нія, да во ві́ки поє́м Єму́ во Ца́рствії Єго́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськоє житіє́ от ю́ности возлюби́вши, в за́повідіх Бо́жиїх ходи́ти вожделі́л єси́, преподо́бне о́тче, і се́рдцем пламені́я ко Го́споду сил, ум на Боже́ственная возве́л єси́, вре́менная і земна́я во уме́ти вміня́я. Ті́мже, промишле́нію Бо́жию о тебі́ див'я́щеся, с ві́рою зове́м ті:","Ра́дуйся, благочести́вих роди́телей си́не досто́йний.","Ра́дуйся, во благоче́стії і́ми воспита́нний.","Ра́дуйся, от ю́ности за Христо́м послі́довавий.","Ра́дуйся, суєту́ земну́ю ні во что́же вміни́вий.","Ра́дуйся, вертогра́да Христо́ва ді́лателю усе́рдний.","Ра́дуйся, пустиножителей наста́вниче вели́кий.","Ра́дуйся, спасе́нія всім жела́вий.","Ра́дуйся, путь і́стиннаго мона́шества показа́вий.","Ра́дуйся, світи́льниче, огне́м Боже́ственним возжже́нний.","Ра́дуйся, ка́меню ві́ри во Христа́ несокрушенний.","Ра́дуйся, благода́тію Ду́ха Свята́го осія́нний.","Ра́дуйся, да́ром чудотворе́ній облагода́тствованний.","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, преподо́бне о́тче Анто́ніє, любо́вію восхваля́юще богоуго́дноє житіє́ твоє́, благодаре́нія піснь о тебі́ Бо́гу прино́сим. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, преподо́бне о́тче Анто́ніє, пусти́ннаго житія́ нача́льниче."]},{"h":"Молитва","ps":["О преподо́бне і богоно́сне о́тче наш Анто́ніє! Ві́руєм, я́ко ти, предстоя́ престо́лу Пресвяти́я Тро́йці, ве́ліє і́маши дерзнове́ніє в моли́твах ко Всемилостивому́ Го́споду Бо́гу, І́же всегда́ послу́шаєть тебі́, ві́рнаго раба́ і уго́дника Своєго́. Сего́ ра́ди со умиле́нієм смире́нно припа́даєм к тебі́, свя́тче Бо́жий: не премолчи́ о нас моли́тися ко Го́споду Бо́гу, в Тро́йці покланя́ємому і сла́вимому, да, ми́лостивно призрі́в на ни, не попу́стить нам поги́бнути во грісі́х на́ших, но да возста́вить па́дших, да пода́сть ісправле́ніє зло́му і окая́нному на́шему житію́, от гряду́щих гріхопаде́ній восхища́я, і да прости́ть нам вся, єли́ка согріши́хом ми́слію, сло́вом і ді́лом, от рожде́нія до сего́ часа́. Ти, подви́жниче доброді́телі, ві́си не́мощ і скорб време́н настоя́щих, моли́ у́бо ви́ну Христа́ Бо́га, да ніколи́же нас оставля́єть Єго́ неізрече́нноє милосе́рдіє, но да храни́ть нас от мирськи́х іскуше́ній, от дия́вольських сіте́й і от плотськи́х по́хотей, да при́ймем от Него́ тобо́ю і вся потре́бная к жи́зні вре́менній, освобожде́ніє от бід і напа́стей, і неосла́бноє терпі́ніє до конця́. Іспроси́ нам в ми́рі і покая́нії сконча́ти живо́т наш і невозбра́нно прейти́ от землі́ на не́бо, мита́рств же, і бісо́во возду́шних, і ві́чния муки́ ізба́витися, і сподо́битися Ца́рства Небе́снаго с тобо́ю і со всі́ми святи́ми, угоди́вшими Го́споду Бо́гу і Спаси́телю на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Ревни́теля Ілію́ нра́ви подра́жая, / Крести́телю пра́вими стезя́ми послі́дуя, / о́тче Анто́ніє, / пусти́ні бил єси́ жи́тель, / і вселе́нную утверди́л єси́ моли́твами твої́ми. / Ті́мже моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Жите́йськія молви́ отри́нув, / безмо́лвно житіє́ сконча́л єси́, / Крести́теля подража́яй вся́ким о́бразом преподо́бнійший, / с ним у́бо тя почита́єм, // отце́в нача́льниче Анто́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Анто́ніє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Геннадію, Костромському і Любимоградському чудотворцю","e":"Akathist to our Venerable Father Gennadius of Kostroma and Lyubimograd, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний ізмла́да Го́споду рабо́тати, подвиза́вся до́брим по́двигом ві́ри, тече́ніє твоє́ до́блестно сконча́л єси́. Водворя́яся же днесь в Небе́сних Селе́ніїх, моли́ся є́же ізба́витися нам от лю́тих обстоя́ній, от всіх зол і напа́стей, да зове́м ті:","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Ікос 1","ps":["Ангелському житію́ восхоті́в подража́ти, ізмла́да яви́лся єси́ тщали́війший в до́му Бо́жиєм ді́латель, нося́ в се́рдці зако́ни і оправда́нія Єго́. Сего́ ра́ди ра́достно вопіє́м ті:","Ра́дуйся, вся́коє мудрова́ніє пло́ті умертви́вий.","Ра́дуйся, єще́ от пеле́н путь і́стини позна́вий.","Ра́дуйся, презрі́вий вся су́єтная бла́га ми́ра, Го́спода ра́ди.","Ра́дуйся, все́ю душе́ю Бо́гові приліпи́вийся.","Ра́дуйся, во́їне Царя́ Небе́снаго.","Ра́дуйся, по́двигом до́брим подвиза́вийся пред Ним.","Ра́дуйся, блага́я о́трасле блага́го ко́рене.","Ра́дуйся, світи́льниче страни́ Любимогра́дськия.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще тя при́снії єще́ ю́на зіло́, не отходя́ща от це́ркві, і пребива́юща в пості́ і моли́тві, тща́хуся осла́бити духо́вний по́двиг твой. Ти же, от ю́ности твоєя́, вда́вий се́рдце Бо́гові, преби́л єси́ непоколеби́м, ду́хом го́ря, Го́сподеві рабо́тая і воспіва́я: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум, ісходя́й от Отця́ сві́тов, я́ко би́сер драги́й обрі́т, тім озаря́єм, вся́ку мглу гріхо́вную дале́че отгна́л єси́ от себе́; управля́єм же сий, я́ко путеводною звіздо́ю, в пусти́ню, сподо́бился єси́ очи́ма твої́ма зрі́ти труди́ і по́двиги Корни́лія і внима́ти словесе́м му́дрости єго́. Ми же восхваля́юще тя вопіє́м си́це:","Ра́дуйся, луча́ми Бо́жия му́дрости озаре́нний.","Ра́дуйся, благода́тною си́лою во вся́цім ді́лі бла́зі утвержде́нний.","Ра́дуйся, по́хоть пло́ті, по́хоть оче́с і го́рдость жите́йськую низложи́вий.","Ра́дуйся, некра́домоє доброді́телей сокро́вище стяжа́вий.","Ра́дуйся, пусти́ню облагоуха́вий діл твої́х добро́тою.","Ра́дуйся, заблудших на путь за́повідей і оправда́ній Госпо́дніх наста́вивий.","Ра́дуйся, і́ноком да́вий о́браз кро́тости і смиренному́дрія.","Ра́дуйся, оби́тель твою́ моли́твами твої́ми ограждаяй і спаса́яй.","Ра́дуйся, Люби́ма гра́да прибі́жище і ра́дованіє.","Ра́дуйся, помо́щниче притека́ющих к тебі́ с ві́рою.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою, да́нною ті сви́ше, в пусти́нях подвиза́яся, а́ще і мно́гі напа́сти і озлобле́нія от враг ви́димих і неви́димих претерпі́л єси́; оба́че та вся до́блестно побіди́л єси́, і ко́зні їх разруши́л єси́, воспіва́я к Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я от ю́ности твоєя́ всажде́н в се́рдці твоє́м страх Бо́жий, не дал сна очи́ма твої́ма, і ві́ждома твої́ма дрема́нія, до́ндеже обрі́л єси́ в пусти́ні Любимоградськой, при вода́х Сурських, мі́сто Го́сподеві, селе́ніє Бо́гу Іа́ковлю, і рекл єси́: се поко́й мой во вік ві́ка, зді вселю́ся, я́ко ізво́лих і. Ми, чудя́щеся всеблаго́му о тебі́ Бо́жию смотре́нію, вопіє́м ті:","Ра́дуйся, я́ко ізмла́да позна́л і все́ю душе́ю твоє́ю возлюби́л єси́ Отця́ Небе́снаго.","Ра́дуйся, я́ко вся су́єтная і тлі́нная презрі́л єси́.","Ра́дуйся, я́ко вся земна́я, уме́ти би́ти вміни́л єси́, взиску́я Ієрусали́ма Го́рняго.","Ра́дуйся, я́ко ізво́лил єси́ под'яти вся́ко поноше́ніє па́че, не́жели вкуша́ти вре́менную гріха́ сла́дость.","Ра́дуйся, я́ко скорбми́ мно́гими вшел єси́ в ра́дость Го́спода твоєго́.","Ра́дуйся, я́ко стра́нник і пришле́ць сий, созда́л єси́ дом Бо́жий, храм Го́сподеві, в не́мже от літ мно́гих призва́ся свято́є і́м'я Єго́.","Ра́дуйся, вод Сурських ликова́ніє.","Ра́дуйся, гра́да Люби́ма огражде́ніє.","Ра́дуйся, Костромськи́х преді́л благолі́пноє украше́ніє.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю злорі́чія, клеве́ть і шепта́нія, по ді́йству змі́я древнаго, іско́ннаго отця́ лжі, окая́ннії воздвиго́ша на тя в оби́телі доблестнаго Корни́лія. Оба́че Госпо́дь, ві́дий ізбавля́ти і утіша́ти преподо́бния своя́, обрати́ студ на главу́ враг твої́х; тебі́ же на широту́ ізведе́, і поста́ви на простра́нстві но́зі твої́, Єму́же принося́ же́ртву хвали́ і благодаре́нія, вопія́л єси́ ви́ну: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша бли́жнії і да́льнії, от дніпро́вських до волжських стран о богоуго́дном житії́ твоє́м, твої́х по́двизіх і терпі́нії мно́зім; град же Москва́, в прише́ствіє твоє́ с Серапіоном і Уа́ром, чудя́щеся, із уст твої́х прия́ша прорече́ніє, єгда́ рекл єси́ непорочной, я́ко а́гници су́щей Анастасі́ї: ти єси́ розга́ прекра́сная, вінце́м ца́рським бу́деши благоукрашена; є́же і сби́стся во вре́м'я своє́. Хва́ляще Бо́га, да́вшаго ті дар прозрі́нія, вопіє́м:","Ра́дуйся, ду́ха проро́чества богому́дренним житіє́м стяжа́вий.","Ра́дуйся, благода́тію ду́шу свою́ оживи́вий і чистото́ю возви́сивий ю.","Ра́дуйся, сбитіє́м проро́чества обрадовавший ца́рство правосла́вноє.","Ра́дуйся, я́ко руко́ю благочести́вой Анастасі́ї утрошася сле́зи мно́гих.","Ра́дуйся, я́ко цари́ця су́щи, державцю Ру́ськия землі́ сла́ву во благочестном жителстве приумножи.","Ра́дуйся, я́ко отложи́во во успе́нії віне́ць тлі́нний, сподо́бился єси́ прия́ти віне́ць сла́ви несконча́ємия.","Ра́дуйся, я́ко і мно́зім жена́м, су́щим в болі́зні і ско́рбіх, по́мощ і утіше́ніє подава́л єси́.","Ра́дуйся, я́ко і немощні́ї младе́нці не отщети́шася от твоєя́ по́мощі, но цільбу́ і во́зраста преспі́яніє от святи́я ра́ки твоєя́ получи́ша.","Ра́дуйся, я́ко і всім притека́ющим ко гро́бу твоєму́ ско́рий явля́єшися помо́щник.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чной уподо́бився звізді́, прите́кл єси́ от ю́га во страни́ сі́вера; і луча́ми доброді́телей твої́х озари́в пусти́ню любимоградськую, науча́л єси́, о́тче, іспові́датися Бо́гу Небе́сному і пі́ти і́мені Єго́, зову́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя благода́ть я́же в тебі́ і дар Свята́го Ду́ха, цар Іоа́нн ізво́ли, да і ча́да єго́ твоє́ю руко́ю, преподо́бне, обновля́ються в пакибитіє́. Ми же сла́в'яще Бо́га, вознося́щаго смире́нних се́рдцем, і вінча́ющаго їх ми́лостію і щедро́тами, взива́єм:","Ра́дуйся, Генна́діє, я́ко ста́рці послу́ша тя і му́дрії в сові́т твой внидо́ша.","Ра́дуйся, я́ко і пред цари́ глаго́лал єси́ о судьба́х і оправда́ніїх Госпо́дніх.","Ра́дуйся, я́ко сло́во твоє́ бисть ви́ну во благода́ті, со́лію растворе́нно.","Ра́дуйся, я́ко ніколи́же сло́во пра́здно і гни́ло ізи́де із уст твої́х, па́че же вся бя́ху к назида́нію ві́рних.","Ра́дуйся, я́ко бил єси́ сосу́д в честь, освяще́н, благопотре́бен Влади́ці.","Ра́дуйся, я́ко соблю́л єси́ та́їнство ві́ри в чи́стой со́вісти.","Ра́дуйся, я́ко преби́л єси́ во і́стині благовіствова́нія.","Ра́дуйся, я́ко а́нгелу благовестнику уподо́бился єси́, предре́к сла́ву Анастасі́ї, о не́йже возвесели́шася бога́тії і убо́зії.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 6","ps":["Пустинножительствовавий на Свирі ріці́ преподо́бний Алекса́ндр, ра́достно прия́т тя с содругом твої́м Фео́дором, і прозорли́вець сий, предпоказа́ в тебі́ блага́го і му́драго і́ночествующим вождя́ і наста́вника. Сли́шавшії такова́я прорече́нія, просла́виша Го́спода, глаго́люще: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́, я́ко звізда́ у́тренняя, і я́ко луна́ полна́ во днех свої́х, сла́ва по́двигов, тружденія і терпі́нія твоєго́; пусти́ня бо возвісти́ о тебі́, і доброді́телі твоя́ о́крест живу́щим пові́да. Сего́ ра́ди я́коже они́, та́кожде і ми благодаря́ще Бо́га, вопіє́м ті:","Ра́дуйся, презрі́вий сла́ву ми́ра, іща́ Бо́жия сла́ви.","Ра́дуйся, сбитіє́ проро́чества, є́же о тебі́, до́брі показа́вий.","Ра́дуйся, яви́вийся при́сний ревнователь преподо́бним Алекса́ндру і Корни́лію.","Ра́дуйся, среди́ жите́йських обурева́ній обріти́й ти́хоє приста́нище.","Ра́дуйся, пусти́ню і є́зеро освяти́вий ангелоподо́бним жителством твої́м.","Ра́дуйся, положи́вий основа́ніє тве́рдо оби́телі твоє́й, і моли́твами твої́ми оградивий ю.","Ра́дуйся, о́браз честна́го жителства і́ноком собо́ю да́вий.","Ра́дуйся, сло́вом і ді́лом наказавий бу́їя і строптивия.","Ра́дуйся, заблудших наста́вниче і всіх притека́ющих к тебі́ ско́рий помо́щниче.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 7","ps":["Просла́вити хотя́ пусти́ню непрохо́дную і просвіти́ти сидящия во тьмі і сі́ні сме́ртній, всеблаги́й Бог, держа́вним ма́нієм Васи́лія Іоанновича указу́єть ті мі́сто, да сози́ждеши олта́р Бо́гові і селе́ніє іспові́дающим і́м'я свято́є Єго́. Ти же, Го́споду споспішеству́ющу, сія́ соді́лав, с со́нмом подви́жников і со всі́ми, і́же ви́діша благослове́ніє на ді́ліх рук твої́х, воспі́л єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий і ди́вний злоче́стія обличи́тель яви́лся єси́, преподо́бне, єгда́ святотатственную просте́ршаго ко олтарю́ ру́ку, разслабле́нієм наказа́л єси́; єгда́ же іспові́да гріх свой пред тобо́ю, і в раска́яніє при́йде, того́ благода́тною си́лою ісціли́л єси́, і на путь спасе́нія наста́вил єси́. Сего́ ра́ди па́м'ять твою́, уго́дниче Бо́жий, честву́юще, зове́м ті си́це:","Ра́дуйся, злоче́стія обличи́телю.","Ра́дуйся, ка́ющихся во грісі́х свої́х уті́шителю.","Ра́дуйся, заблудших наста́вниче.","Ра́дуйся, моли́твами твої́ми подава́яй ісціле́ніє тіле́сноє, вку́пі же і душе́вноє.","Ра́дуйся, заступничеством твої́м низлага́яй де́монськая возста́нія.","Ра́дуйся, благода́тію я́же в тебі́ подава́яй си́ли к животу́ і благоче́стію.","Ра́дуйся, сви́ше да́нною ті прему́дростію умудря́яй неразу́мния.","Ра́дуйся, я́ко всім притека́ющим к тебі́ с ві́рою, при́сно подає́ши утіше́ніє і ра́дованіє.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до яви́ся, єгда́ немоществующий болярин Бори́с, прия́в с благогові́нієм по́сох от руки́ твоєя́, преподо́бне, здрав бисть. Ієре́й же Васи́лій, го́рдостно презрі́в прия́тий от преподо́бнаго дар, і пове́рг о́ний, тя́жко іскуше́н бисть. Позна́в же гріх свой, і прине́с покая́ніє Бо́гу, просла́ви пра́вду Єго́, і уго́дника Єго́, вопія́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ум впери́во в го́рняя, єди́наго, іску́пльшаго нас Го́спода возлюби́л єси́, Тому́ послі́довал єси́ і Того́ я́зви на ті́лі своє́м носи́л єси́, с Ни́мже і прославля́єшися днесь. Сего́ ра́ди восхваля́єм тя:","Ра́дуйся, обріти́й прему́дрость, ю́же нікто́же от князе́й ві́ка сего́ разумі́.","Ра́дуйся, не ду́ха ми́ра сего́ прия́вий, но Ду́ха І́же от Бо́га.","Ра́дуйся, ві́рою уразумі́вий та́йни суде́б Бо́жиїх.","Ра́дуйся, показа́вий ві́ру твою́ не в му́дрости челові́честій, но в си́лі Бо́жієй.","Ра́дуйся, я́ко Гра́да Небе́снаго взиска́л єси́.","Ра́дуйся, я́ко к Ієрусали́му Небе́сному восте́кл єси́.","Ра́дуйся, я́ко на ве́черю бра́ка А́гнча зван єси́.","Ра́дуйся, не к тому́ себі́ пожи́в, но Бо́гові, днесь во Ца́рствії Єго́ вселя́єшися.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кими духо́вними дарова́нії укра́шен, вся́кия цільби́ пода́тель яви́лся єси́, блаже́нне. Ті́мже хва́ляще і благодаря́ще Бо́га, вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї немотствоваху і му́дрії ві́ка сего́ ізумевахуся, ви́дяще, ка́ко бесний, лю́ті стражда́й, і пу́ти желі́зними свя́зан сий, пред гробо́м твої́м, преподо́бне, а́біє ісцілі́ і воздаде́ хвалу́ Бо́гові, ди́вному во святи́х Свої́х. Та́яжде творя́ще, і ми глаго́лем:","Ра́дуйся, си́ли мно́гі сотвори́вий.","Ра́дуйся, де́монськая сопротивувостанія ні во что же вміни́вий.","Ра́дуйся, обдержимих лю́тими неду́гами уврачева́вий.","Ра́дуйся, безутешним утіше́ніє і ра́дость о Го́споді пода́вий.","Ра́дуйся, омраче́нних умо́м в ра́зум і́стини приведи́й.","Ра́дуйся, от серде́чнаго окамене́нія і нече́стія мно́гих обрати́вий к Бо́гу.","Ра́дуйся, я́ко немощству́ющим ду́хом і ті́лом просте́рл єси́ ру́ку по́мощі.","Ра́дуйся, я́ко безнаде́жних і отча́янних су́щих, утверди́л єси́ во упова́нії на Бо́га жива́ і і́стинна.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 10","ps":["Спасе́нія іски́й, я́ко би́сера многоці́ннаго, і к Бо́гу душе́ю возжада́в, я́коже єле́нь на істо́чники водни́я, нічто́же земно́є в себі́ помишля́л єси́; рабо́тая же Го́сподеві со стра́хом і ра́дуяся пред Ним с тре́петом, сподо́бился єси́, блаже́нне, с ли́ки ізбра́нних предстоя́ти Престо́лу Царя́ сла́ви, і при́сно воспіва́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і прибі́жище бил єси́, Генна́діє, во ві́ці сем: в пусти́ню бо, в ней же восхоті́л єси́ водвори́тися, к тебі́ притека́ху сла́внії землі́, бога́тії і убо́зі, вожделевающе, да при́ймуть от руки́ твоєя́ благослове́ніє, да сло́во уст твої́х уті́шить, і моли́тва твоя́ огради́ть їх от враг ви́димих і неви́димих; і ми та́кожде, притека́юще ві́рою к ра́ці твоє́й, і моля́ще о заступле́нії нас грі́шних і неключи́мих раб, вопіє́м:","Ра́дуйся, я́ко страсте́й возста́ніє побіди́л єси́.","Ра́дуйся, я́ко призива́ющих тя предвари́л єси́ в день озлобле́нія.","Ра́дуйся, я́ко потопля́ємих напа́стей бу́рею, ізхитил єси́ із пучи́ни зол.","Ра́дуйся, я́ко влаємих волна́ми жите́йських попече́ній, к ти́хому приста́нищу упра́вил єси́.","Ра́дуйся, і́щущих Ца́рствія Небе́снаго і пра́вди єго́, моли́твами твої́ми утвержда́яй на ка́мені за́повідей Госпо́дніх.","Ра́дуйся, оби́телі твоєя́ сто́лпе і утвержде́ніє.","Ра́дуйся, подвиза́ющихся во благоче́стії неуси́пний спомощниче.","Ра́дуйся, покая́нния сле́зи пролива́ющих ко Го́споду сомоли́твенниче.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́нія і славосло́вія, по́двиги і моли́твенния тружденія, па́че же всего́ себе́ прине́сл єси́, преподо́бне, в же́ртву живу́, свя́ту, благоуго́дну Бо́гові. Сего́ ра́ди, стяжа́в блаже́нноє безсме́ртіє, в черто́зі Царя́ сла́ви, с тьма́ми тім безпло́тних сил ликовству́я, воспіва́єши: Аллилу́я."]},{"h":"Ікос 11","ps":["Светозарной звізді́ уподо́бився, от Могилева гра́да, от преді́л дніпро́вських, а́може пе́рвії возсія́ша, посреді́ і́дольськаго нече́стія, лучи́ благода́тния ві́ри, прите́кл єси́, да і во мра́ці пусти́ні костромськи́я у́зрять лю́діє сла́ву Бо́жию і чудеса́ Єго́ пові́дять. Сія́ у́бо зрим ни́ні, і сла́в'яще Бо́га, глаго́лем:","Ра́дуйся, напоі́вий себі́ струя́ми вод благода́тних.","Ра́дуйся, утверди́вий себі́ во ві́рі, є́юже просвіти́ся равноапостольний вели́кий князь Влади́мир.","Ра́дуйся, осія́нний благослове́нієм святи́я Афо́нськия гори́, почивающим на оби́телі пече́рських чудотво́рцев.","Ра́дуйся, їх житію́ подража́вий.","Ра́дуйся, я́ко оста́вль бога́тство і сла́ву до́ма отчаго, пусти́ню возлюби́л єси́.","Ра́дуйся, я́ко хлад і зной і вся́ку тяготу́ поне́сл єси́.","Ра́дуйся, я́ко поруга́нія і озлобле́нія, Го́спода ра́ди, претерпі́л єси́.","Ра́дуйся, я́ко в терпі́нії мно́зі стяжа́в ду́шу свою́, живо́т ві́чний наслі́довал єси́.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть і си́лу да́нную ті от Бо́га, є́же ціли́ти немощству́ющия ду́хом, немощству́ющия ті́лом, є́же спаса́ти погиба́ющих і ізбавля́ти от лю́тих обстоя́ній, дая́ти же дая́нія блага́я, с ві́рою і любо́вію притека́ющим к тебі́; зна́меньми і чудеси́ науче́ни су́ще, сві́ми. Ті́мже мо́лимся ті, преподо́бне, моли́ся о нас, я́ко скобми па́че же мно́гими гріхми́ обдержи́ми єсьми́ ви́ну, да хода́тайством твої́м улучи́вше спасе́ніє, воспоє́м Го́сподеві: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і превознося́ще Бо́га, ди́внаго во святи́х свої́х, благолі́пно честву́єм святу́ю па́м'ять твою́, уго́дниче; єще́ бо во днех пло́ті твоєя́ чудоді́йственния благода́ті бил єси́ прича́стник; по блаже́нном успе́нії твоє́м наследствуя с ли́ки святи́х ві́чную жизнь, мо́лиши о чту́щих тя. Сего́ ра́ди вопіє́м:","Ра́дуйся, просла́вивий Бо́га в душі́ і тілесі́ своє́м.","Ра́дуйся, я́ко сла́ви от челові́к не прия́л єси́, сла́ва же Госпо́дня осія́ тя.","Ра́дуйся, я́ко обита́я в Небе́сних селе́ніїх, не оставля́єши нас хода́тайством твої́м.","Ра́дуйся, я́ко наді́ющеся на тя, возсила́єм моли́тви на́ша і тобо́ю хва́лимся.","Ра́дуйся, я́ко наде́жда притека́ющих к ра́ці твоє́й с ві́рою, ніколи́же посрами́ся.","Ра́дуйся, я́ко ста́рці і младе́нці возра́довашася о тебі́.","Ра́дуйся, я́ко при́сний храни́тель єси́ Любимогра́дськия страни́, сподобльшіяся храни́ти святи́я мо́щі твоя́.","Ра́дуйся, я́ко па́м'ять твоя́ во благослове́нії і чудеса́ твоя́ возвещаються в ро́ди родо́в.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 13","ps":["О свя́тче Бо́жий і чудотво́рче, преподо́бне Генна́діє! Прийми́ моли́тви і благохвале́нія на́ша, приноси́мия тебі́ днесь, по достоя́нію, і не забу́ди нас притека́ющих к тебі́, і і́щущих по́мощі твоєя́ і заступле́нія. Па́че же бу́ди хода́тай наш пред Бо́гом; да отбі́гше нече́стія, і ізба́вльшеся от вся́каго зла́го обстоя́нія, сподо́бимся наслі́дити Ца́рство Небе́сноє, і та́мо с ли́ки святи́х, сла́вити Отця́ і Си́на і Свята́го Ду́ха, і во вся ві́ки воспіва́ти пред Ним: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ангелському житію́ восхоті́в подража́ти, ізмла́да яви́лся єси́ тщали́війший в до́му Бо́жиєм ді́латель, нося́ в се́рдці зако́ни і оправда́нія Єго́. Сего́ ра́ди ра́достно вопіє́м ті:","Ра́дуйся, вся́коє мудрова́ніє пло́ті умертви́вий.","Ра́дуйся, єще́ от пеле́н путь і́стини позна́вий.","Ра́дуйся, презрі́вий вся су́єтная бла́га ми́ра, Го́спода ра́ди.","Ра́дуйся, все́ю душе́ю Бо́гові приліпи́вийся.","Ра́дуйся, во́їне Царя́ Небе́снаго.","Ра́дуйся, по́двигом до́брим подвиза́вийся пред Ним.","Ра́дуйся, блага́я о́трасле блага́го ко́рене.","Ра́дуйся, світи́льниче страни́ Любимогра́дськия.","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний ізмла́да Го́споду рабо́тати, подвиза́вся до́брим по́двигом ві́ри, тече́ніє твоє́ до́блестно сконча́л єси́. Водворя́яся же днесь в Небе́сних Селе́ніїх, моли́ся є́же ізба́витися нам от лю́тих обстоя́ній, от всіх зол і напа́стей, да зове́м ті:","Ра́дуйся, Генна́діє, те́плий наш к Бо́гу моли́твенниче і чудотво́рче."]},{"h":"Молитва","ps":["Ізбра́нниче Бо́жий і чудотво́рче, преподо́бний о́тче Генна́діє! От ю́ности твоєя́ іспо́лнен сий ду́ха прему́дрости і ра́зума, ду́ха благоче́стія і стра́ха Госпо́дня, і приї́м вся ору́жія Бо́жия, препоя́сав чре́сла твоя́ і́стиною, обо́лкся в броню́ пра́вди і обу́в но́зі во угото́ваніє благовіствова́нія ми́ра, над всі́ми же восприї́м щит ві́ри, возмо́гл єси́, я́ко добр во́їн Христо́в, вся стрі́ли лука́ваго разжже́ния угаси́ти. Сего́ ра́ди, водворя́яся днесь, с ли́ки безпло́тних сил, в оби́теліх Отця́ Небе́снаго, неув'яда́ємим вінце́м ув'язе́н єси́; і предстоя́ Престо́лу Царя́ сла́ви Го́спода сил, і́маши дерзнове́ніє возноси́ти к Нему́ моле́нія і благохвале́нія твоя́. Ми же окая́ннії, возводя́ще із глубини́ зол о́чі і се́рдця на́ша ко го́рнему Сіо́ну, жили́щу Бо́га Іа́ковля, мо́лим тя, преподо́бне Генна́діє: бу́ди засту́пник і хода́тай наш пред Бо́гом і Го́сподем на́шим, Судіє́ю пра́веднійшим, Єго́же ви́ну прогнівля́єм, согріша́юще пред Ним. І я́коже во дні пло́ті своєя́, ди́вная і пресла́вная соверши́л єси́, о́тче всехва́льне, та́ко і ни́ні преше́д от нас в оби́телі Отця́ Небе́снаго удиви́ хода́тайством свої́м ми́лость Госпо́дню на нас. Да отбі́гше нече́стія і мирськи́х по́хотей, Бо́гові же благоугоди́вше, обря́щем по́мощ Єго́ во вре́м'я благопотре́бно, і благослове́ніє на ни і на діла́ рук на́ших, і да сподо́бит нас наслі́дити Ца́рство Небе́сноє, і с ли́ки святи́х сла́вити і воспіва́ти пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко пустиннолюби́вая го́рлиця, / от су́єтнаго і многом'яте́жнаго ми́ра в пусти́ню удали́вся, / чистото́ю і гові́нієм, моли́твами і тружде́нієм / просла́вил єси́ Бо́га в душе́ і тілесі́ своє́м. / І та́ко благоче́стно пожи́в, / яви́лся єси́, преподо́бне Генна́діє, пусти́ні Любимогра́дськия украше́ніє, / і́ноком честна́го житія́ о́браз / і те́плий моли́твенник за всіх, // притека́ющих к тебі́ с ві́рою."]},{"h":"Кондак, глас 3","ps":["Моли́твою і посто́м, тружде́нієм і терпі́нієм / умертви́вий вся́коє пло́ті мудрова́ніє, / чистоти́ сосу́д благолі́пен, / Боже́ственних даро́в і чуде́с прича́стник, / і́ноком же до́блій наста́вник бил єси́, / сподвиза́яся блаже́нному Корни́лію, о́тче Богому́дре. / Сего́ ра́ди вопіє́м: / моли́ся ко Го́споду, // да моли́твами твої́ми да́руєть мир і спасе́ніє душа́м на́шим."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Генна́діє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]}];
export default D;
